diff --git a/dev/zero/internal/execprofile/profile.go b/dev/zero/internal/execprofile/profile.go
--- a/dev/zero/internal/execprofile/profile.go
+++ b/dev/zero/internal/execprofile/profile.go
@@ @@
 	Thorough = Profile{
 		Name:            "thorough",
 		MaxTurns:        160,
 		ReasoningEffort: "high",
 		SelfCorrect:     true,
 	}
+
+	// Zeromaxing is the top posture: thorough's knobs with double the turn
+	// budget again, plus the loop-posture reminders the agent injects while it
+	// is active (see agent.Zeromaxing).
+	//
+	// HONEST DELTA over thorough: the turn budget, and nothing else. Effort is
+	// already at the ceiling and self-correction is already armed. Delta states
+	// that to the user's face rather than leaving it in a commit message — a
+	// posture whose advertised behaviour exceeds its real behaviour is worse
+	// than no posture at all.
+	//
+	// ReasoningEffort is "high" and MUST STAY "high" — pinned by
+	// TestZeromaxingReasoningEffortStaysHigh. "high" is the top rung every
+	// provider actually maps: anthropic's thinkingBudgetForEffort and its gemini
+	// twin fall through to their default arm (budget 0 => extended thinking
+	// DISABLED) for anything above it, and the openai mapper drops the field
+	// entirely. Raising this to "xhigh"/"max" would silently turn thinking OFF —
+	// a downgrade wearing an upgrade's name. Raising the real ceiling means
+	// teaching the providers those tiers first.
+	Zeromaxing = Profile{
+		Name:            "zeromaxing",
+		MaxTurns:        320,
+		ReasoningEffort: "high",
+		SelfCorrect:     true,
+	}
 )

 var catalog = map[string]Profile{
-	Balanced.Name: Balanced,
-	Fast.Name:     Fast,
-	Thorough.Name: Thorough,
+	Balanced.Name:   Balanced,
+	Fast.Name:       Fast,
+	Thorough.Name:   Thorough,
+	Zeromaxing.Name: Zeromaxing,
 }
+
+// Delta is the user-facing statement of what selecting zeromaxing actually
+// changes, shown by /effort, /profile, and the exec selection notice. It is
+// deliberately concrete and deliberately admits the two knobs it does NOT move:
+// a user paying for a higher posture is owed the real delta, not a slogan.
+//
+// The child-budget sentence is not a caveat, it is the point: zeromaxing is a
+// maximal posture, so the raised budget is exported to spawned sub-agents
+// exactly as /turns does (asserted by TestZeromaxingTurnBudgetPropagatesToChildren).
+const Delta = "zeromaxing raises the tool-turn budget to 320 (thorough uses 160) and applies that budget to spawned sub-agents too. " +
+	"Reasoning effort and post-edit self-correction are unchanged from thorough: effort is already at the highest level providers accept, and self-correction is already armed."
+
+// Name is the single spelling of this posture, everywhere: /effort zeromaxing,
+// /profile zeromaxing, --exec-profile zeromaxing, --reasoning-effort zeromaxing.
+// One name, one table — no aliases, so there is no second spelling to keep in
+// step with this one.
+const Name = "zeromaxing"
+
+// IsZeromaxing reports whether p is the zeromaxing posture. Callers use it
+// instead of comparing name strings so the literal lives in exactly one place.
+func (p Profile) IsZeromaxing() bool { return p.Name == Name }
+
+// SelectionRefusal returns a non-empty, user-facing reason when the named
+// profile may not be selected here, or "" when selection is allowed.
+//
+// It is the ONE authoritative selection rule, called by BOTH the headless exec
+// path and the TUI /effort + /profile paths. Those paths already differ in how
+// they apply a profile's knobs; letting each decide selection independently is
+// exactly how a rule gets applied to one call path and silently omitted from
+// its sibling. TestSelectionRefusalAgreesAcrossPaths pins that they agree.
+//
+// disabled comes from resolved config. A project .zero/config.json may set it
+// (DISABLE) but can never clear it (ENABLE) — see mergeProjectConfig.
+func SelectionRefusal(p Profile, disabled bool) string {
+	if p.IsZeromaxing() && disabled {
+		return "the zeromaxing posture is disabled for this workspace (profiles.disableZeromaxing in config)"
+	}
+	return ""
+}
diff --git a/dev/zero/internal/agent/zeromaxing.go b/dev/zero/internal/agent/zeromaxing.go
--- /dev/null
+++ b/dev/zero/internal/agent/zeromaxing.go
@@ @@
+package agent
+
+// The zeromaxing execution posture's model-facing reminders.
+//
+// WHERE THESE GO, AND WHY IT IS NOT NEGOTIABLE
+//
+// Every string here is appended to the CONVERSATION as a user-role message, at
+// the tail, exactly like the failure hint and the plan/progress reminders in
+// the turn loop. None of it ever reaches buildSystemPromptParts.
+//
+// The system prompt and the tool definitions are the provider's cached prefix
+// (the anthropic mapper puts its cache_control breakpoint on the last system
+// block and the last tool). #760 made that prefix build ONCE per run precisely
+// so it stays byte-identical across turns. A reminder that varies per turn and
+// lands above the breakpoint invalidates the cache on every single turn —
+// roughly doubling input cost — and nothing in the system reports it. Hence:
+// tail only.
+//
+// The same reasoning is why ZeromaxingStillOnNotice is a fixed literal with no
+// turn counter, no timestamp, and no accumulated state. It is repeated verbatim
+// on every continuing turn. If it ever grew a varying part and someone later
+// moved it into prompt assembly, that would be a silent cost bug rather than a
+// loud test failure. TestRunPreservesRequestPrefixAcrossTurnsUnderZeromaxing is
+// the tripwire.
+//
+// The wording is written for this project: plain, neutral, describing Zero's
+// own posture in Zero's own terms. It deliberately promises no orchestration,
+// no fan-out and no workflow tool — Phase 1 ships none of those, and a reminder
+// that implies capabilities the run does not have is a prompt-level lie.
+
+// Zeromaxing is where a run sits in the zeromaxing posture's lifecycle. It is
+// set by whoever selected the posture (headless exec for a one-shot run, the
+// TUI across a session) and read only by the turn loop.
+type Zeromaxing int
+
+const (
+	// ZeromaxingOff: the posture is not active. Every reminder is suppressed and
+	// the loop is byte-identical to a run that never heard of it. This is the
+	// zero value, so every existing caller keeps today's behaviour.
+	ZeromaxingOff Zeromaxing = iota
+	// ZeromaxingEntering: this run is the first since the posture was turned on,
+	// so its first turn carries the enter notice and the budget guideline.
+	ZeromaxingEntering
+	// ZeromaxingActive: the posture was already on before this run began, so
+	// even the first turn gets the continuing notice rather than the enter one.
+	ZeromaxingActive
+	// ZeromaxingExiting: this run is the first since the posture was turned off.
+	// Its first turn carries the exit notice and nothing after that.
+	ZeromaxingExiting
+)
+
+// The four messages. Exported as constants so tests assert on the same bytes
+// the model receives rather than on a paraphrase.
+const (
+	// ZeromaxingEnterNotice announces the flip. It fires once, on the first turn
+	// of the run in which the posture was selected.
+	ZeromaxingEnterNotice = "The zeromaxing execution posture is now active for this session. " +
+		"You have a substantially larger tool-turn budget than usual, so prefer verifying your work over assuming it: " +
+		"read the code you are about to change, run the checks that would catch a mistake, and follow up on anything you noticed but did not confirm."
+
+	// ZeromaxingBudgetNotice states the budget guideline alongside the enter
+	// notice. Split from it so the two can be asserted independently, and so a
+	// future budget change touches one string.
+	ZeromaxingBudgetNotice = "Budget guideline under zeromaxing: the larger turn budget is for depth on one task, not for widening its scope. " +
+		"Finish what was asked, verify it, and stop — do not start adjacent work because there are turns left."
+
+	// ZeromaxingStillOnNotice repeats on every continuing turn.
+	//
+	// It is intentionally short and FIXED. Do not add a turn number, a
+	// remaining-budget count, a timestamp, or anything else that differs between
+	// turns — see the file comment.
+	ZeromaxingStillOnNotice = "The zeromaxing execution posture is still active."
+
+	// ZeromaxingExitNotice announces the flip back. It fires once, on the first
+	// turn of the run after the posture was turned off.
+	ZeromaxingExitNotice = "The zeromaxing execution posture is no longer active. " +
+		"The tool-turn budget has returned to its normal value; work at the usual depth."
+)
+
+// zeromaxingReminders returns the reminder lines to append before the given
+// turn, oldest first, or nil when there is nothing to say. turn is 1-based, so
+// turn == 1 is the run's first provider request.
+//
+// The whole state machine is this function: it is pure, it depends only on
+// (posture, turn), and it has no memory. That is what makes "enter exactly
+// once" and "still-on never on the first turn" testable as data rather than as
+// a sequence of observed side effects.
+func zeromaxingReminders(posture Zeromaxing, turn int) []string {
+	if turn < 1 {
+		return nil
+	}
+	switch posture {
+	case ZeromaxingEntering:
+		if turn == 1 {
+			return []string{ZeromaxingEnterNotice, ZeromaxingBudgetNotice}
+		}
+		return []string{ZeromaxingStillOnNotice}
+	case ZeromaxingActive:
+		// Already on when the run started: no enter notice, not even on turn 1.
+		return []string{ZeromaxingStillOnNotice}
+	case ZeromaxingExiting:
+		// One notice on the way out, then silence — the posture is off, so a
+		// "still active" line every turn would be a lie.
+		if turn == 1 {
+			return []string{ZeromaxingExitNotice}
+		}
+		return nil
+	default:
+		return nil
+	}
+}
diff --git a/dev/zero/internal/execprofile/zeromaxing_test.go b/dev/zero/internal/execprofile/zeromaxing_test.go
--- /dev/null
+++ b/dev/zero/internal/execprofile/zeromaxing_test.go
@@ @@
+package execprofile
+
+import (
+	"strings"
+	"testing"
+)
+
+// (d) THE TRAP PIN.
+//
+// Zeromaxing.ReasoningEffort must stay "high". Every level above it falls
+// through the providers' effort→budget mappers into their DEFAULT arm, and
+// those defaults mean "no extended thinking":
+//
+//	anthropic thinkingBudgetForEffort default -> 0   (thinking disabled)
+//	gemini    thinkingBudgetForEffort default -> 0   (thinking disabled)
+//	openai    openAIReasoningEffort    default -> "" (field omitted entirely)
+//
+// So "raising" this to xhigh/max would silently turn reasoning OFF while the UI
+// claimed a higher posture — a downgrade wearing an upgrade's name, invisible
+// at runtime. Raising the real ceiling means teaching the providers those tiers
+// first; until then this test is what stands in the way.
+func TestZeromaxingReasoningEffortStaysHigh(t *testing.T) {
+	if Zeromaxing.ReasoningEffort != "high" {
+		t.Fatalf("Zeromaxing.ReasoningEffort = %q, want \"high\" — see this test's comment: "+
+			"any level above \"high\" hits the providers' default arm and DISABLES thinking",
+			Zeromaxing.ReasoningEffort)
+	}
+	// Thorough is the rung below and shares the ceiling; if these ever diverge,
+	// the honest-delta text is wrong.
+	if Thorough.ReasoningEffort != Zeromaxing.ReasoningEffort {
+		t.Fatalf("thorough effort %q != zeromaxing effort %q — Delta claims they are equal",
+			Thorough.ReasoningEffort, Zeromaxing.ReasoningEffort)
+	}
+}
+
+// One name, one table. No aliases means no second spelling to keep in step.
+func TestZeromaxingHasExactlyOneSpelling(t *testing.T) {
+	profile, ok := Lookup(Name)
+	if !ok {
+		t.Fatalf("%q is not in the catalog", Name)
+	}
+	if profile != Zeromaxing || !profile.IsZeromaxing() {
+		t.Fatalf("Lookup(%q) = %+v, want %+v", Name, profile, Zeromaxing)
+	}
+	// Case/whitespace insensitivity, matching the other profiles.
+	if p, ok := Lookup("  ZEROMAXING "); !ok || !p.IsZeromaxing() {
+		t.Fatalf("Lookup is not case/space insensitive: %+v ok=%v", p, ok)
+	}
+	// The rejected spellings. Every one of these resolving would mean a second
+	// name for one posture, which is the drift this design exists to avoid.
+	for _, alias := range []string{"max", "deep", "deepmode", "zero-maxing", "zeromax", "zm"} {
+		if _, ok := Lookup(alias); ok {
+			t.Fatalf("%q must NOT resolve — the posture has exactly one name, %q", alias, Name)
+		}
+	}
+	found := false
+	for _, name := range Names() {
+		if name == Name {
+			found = true
+		}
+	}
+	if !found {
+		t.Fatalf("Names() omits %q, so usage text and hints will not offer it: %v", Name, Names())
+	}
+}
+
+// The knobs, pinned. The turn budget is the ONLY mechanical delta over
+// thorough — Delta says exactly that to the user, so if these drift apart the
+// user-facing claim becomes false.
+func TestZeromaxingKnobsMatchTheDeltaItAdvertises(t *testing.T) {
+	if Zeromaxing.MaxTurns != 320 {
+		t.Fatalf("Zeromaxing.MaxTurns = %d, want 320", Zeromaxing.MaxTurns)
+	}
+	if Zeromaxing.MaxTurns != Thorough.MaxTurns*2 {
+		t.Fatalf("budget %d is not double thorough's %d", Zeromaxing.MaxTurns, Thorough.MaxTurns)
+	}
+	if !Zeromaxing.SelfCorrect || !Thorough.SelfCorrect {
+		t.Fatalf("Delta claims self-correction is already armed at thorough: zeromaxing=%v thorough=%v",
+			Zeromaxing.SelfCorrect, Thorough.SelfCorrect)
+	}
+	// It arms no escalation triggers (it is the top rung — nothing to escalate
+	// to), so Policy returns nil exactly like thorough and balanced.
+	if policy := Zeromaxing.Policy(80, true); policy != nil {
+		t.Fatalf("zeromaxing must arm no escalation policy, got %+v", policy)
+	}
+	for _, want := range []string{"320", "160", "sub-agents"} {
+		if !strings.Contains(Delta, want) {
+			t.Fatalf("Delta must state %q so the user sees the real delta: %q", want, Delta)
+		}
+	}
+}
+
+// (m)+(n) at the rule level: SelectionRefusal is the single authority both
+// selection paths consult. Its callers are asserted separately (CLI and TUI).
+func TestSelectionRefusalDisablesOnlyZeromaxingAndOnlyWhenDisabled(t *testing.T) {
+	if refusal := SelectionRefusal(Zeromaxing, true); refusal == "" {
+		t.Fatal("a disabled workspace must refuse zeromaxing")
+	} else if !strings.Contains(refusal, "disableZeromaxing") {
+		t.Fatalf("the refusal must name the setting so the user can act on it: %q", refusal)
+	}
+	if refusal := SelectionRefusal(Zeromaxing, false); refusal != "" {
+		t.Fatalf("zeromaxing must be selectable when not disabled, got %q", refusal)
+	}
+	// The disable flag is posture-scoped: it must not silently take out the
+	// other profiles, which have no cost-multiplier justification for gating.
+	for _, other := range []Profile{Balanced, Fast, Thorough} {
+		if refusal := SelectionRefusal(other, true); refusal != "" {
+			t.Fatalf("disableZeromaxing must not refuse %q: %q", other.Name, refusal)
+		}
+	}
+}
diff --git a/dev/zero/internal/cli/exec_zeromaxing_test.go b/dev/zero/internal/cli/exec_zeromaxing_test.go
--- /dev/null
+++ b/dev/zero/internal/cli/exec_zeromaxing_test.go
@@ @@
+package cli
+
+import (
+	"strings"
+	"testing"
+
+	"github.com/Gitlawb/zero/internal/agent"
+	"github.com/Gitlawb/zero/internal/execprofile"
+	"github.com/Gitlawb/zero/internal/modelregistry"
+)
+
+// (a) CLI: an explicit --reasoning-effort survives zeromaxing. The profile
+// fills only what the caller left unset, exactly as fast/thorough do.
+func TestZeromaxingDoesNotOverrideExplicitReasoningEffortCLI(t *testing.T) {
+	options := execOptions{execProfile: execprofile.Name, reasoningEffort: "low"}
+	profile, effortFilled, err := applyExecProfile(&options)
+	if err != nil {
+		t.Fatalf("applyExecProfile: %v", err)
+	}
+	if !profile.IsZeromaxing() {
+		t.Fatalf("profile = %q, want %q", profile.Name, execprofile.Name)
+	}
+	if options.reasoningEffort != "low" {
+		t.Fatalf("reasoningEffort = %q, the explicit low must survive the posture's high", options.reasoningEffort)
+	}
+	if effortFilled {
+		t.Fatal("must report it did NOT fill the effort, or a mid-run escalation would clear a hand-pinned value")
+	}
+}
+
+// (b) CLI: --mode's fills survive zeromaxing. applyExecMode runs first, so its
+// values read as "set" by the time the profile arrives — precedence is enforced
+// by ordering, and this pins that the ordering still holds with a fourth profile.
+func TestZeromaxingDoesNotOverrideModeFillsCLI(t *testing.T) {
+	options := execOptions{mode: "fast", execProfile: execprofile.Name}
+	if err := applyExecMode(&options); err != nil {
+		t.Fatalf("applyExecMode: %v", err)
+	}
+	modeEffort := options.reasoningEffort
+	modeTurns := options.maxTurns
+	profile, _, err := applyExecProfile(&options)
+	if err != nil {
+		t.Fatalf("applyExecProfile: %v", err)
+	}
+	if modeEffort != "" && options.reasoningEffort != modeEffort {
+		t.Fatalf("reasoningEffort = %q, the mode's %q must win", options.reasoningEffort, modeEffort)
+	}
+	if modeTurns > 0 {
+		// Mirror the real call site: a mode's --max-turns fill lands in
+		// options.maxTurns AND flows through config overrides into
+		// resolved.MaxTurns, so both arguments carry it. The profile must then
+		// back off entirely — displaced 0, budget untouched.
+		effective, displaced := applyProfileTurnBudget(profile, options.maxTurns, options.maxTurns)
+		if effective != modeTurns || displaced != 0 {
+			t.Fatalf("turn budget = (%d, displaced %d), the mode's %d must win with nothing displaced",
+				effective, displaced, modeTurns)
+		}
+	}
+}
+
+// (c) CLI: fills only what is unset; an explicit --max-turns pins the budget so
+// the profile backs off with nothing displaced.
+func TestZeromaxingFillsOnlyUnsetCLI(t *testing.T) {
+	options := execOptions{execProfile: execprofile.Name}
+	profile, effortFilled, err := applyExecProfile(&options)
+	if err != nil {
+		t.Fatalf("applyExecProfile: %v", err)
+	}
+	if options.reasoningEffort != "high" || !effortFilled {
+		t.Fatalf("unset effort must be filled with high, got %q filled=%v", options.reasoningEffort, effortFilled)
+	}
+	if !options.selfCorrect {
+		t.Fatal("must arm self-correction when it was unset")
+	}
+	if effective, displaced := applyProfileTurnBudget(profile, 0, 80); effective != 320 || displaced != 80 {
+		t.Fatalf("over resolved 80 = (%d, %d), want (320, 80)", effective, displaced)
+	}
+	if effective, displaced := applyProfileTurnBudget(profile, 50, 50); effective != 50 || displaced != 0 {
+		t.Fatalf("with explicit --max-turns 50 = (%d, %d), want (50, 0)", effective, displaced)
+	}
+}
+
+// (g) CLI: --reasoning-effort zeromaxing and --exec-profile zeromaxing resolve
+// to IDENTICAL state. One posture, one name, reachable from either flag.
+func TestZeromaxingEffortFlagResolvesLikeProfileFlagCLI(t *testing.T) {
+	viaEffort := execOptions{reasoningEffort: execprofile.Name}
+	if err := normalizeZeromaxingEffort(&viaEffort); err != nil {
+		t.Fatalf("normalize: %v", err)
+	}
+	viaProfile := execOptions{execProfile: execprofile.Name}
+	if err := normalizeZeromaxingEffort(&viaProfile); err != nil {
+		t.Fatalf("normalize: %v", err)
+	}
+	if viaEffort != viaProfile {
+		t.Fatalf("the two entry points diverged:\n--reasoning-effort: %+v\n--exec-profile:     %+v", viaEffort, viaProfile)
+	}
+	// ...and after profile expansion they are still identical.
+	pe, fe, err := applyExecProfile(&viaEffort)
+	if err != nil {
+		t.Fatalf("applyExecProfile(effort path): %v", err)
+	}
+	pp, fp, err := applyExecProfile(&viaProfile)
+	if err != nil {
+		t.Fatalf("applyExecProfile(profile path): %v", err)
+	}
+	if pe != pp || fe != fp || viaEffort != viaProfile {
+		t.Fatalf("resolved state diverged after expansion:\n%+v %v\n%+v %v", pe, fe, pp, fp)
+	}
+	if viaEffort.reasoningEffort != "high" {
+		t.Fatalf("both paths must resolve the effort to the profile's high, got %q", viaEffort.reasoningEffort)
+	}
+}
+
+// A conflicting pair is a usage error, not a silent winner.
+func TestZeromaxingEffortFlagConflictIsUsageError(t *testing.T) {
+	options := execOptions{reasoningEffort: execprofile.Name, execProfile: "fast"}
+	err := normalizeZeromaxingEffort(&options)
+	if err == nil {
+		t.Fatal("--reasoning-effort zeromaxing with --exec-profile fast must be a usage error")
+	}
+	if !strings.Contains(err.Error(), "conflicts") {
+		t.Fatalf("the error must name the conflict: %v", err)
+	}
+	// The same profile on both flags is not a conflict.
+	same := execOptions{reasoningEffort: execprofile.Name, execProfile: execprofile.Name}
+	if err := normalizeZeromaxingEffort(&same); err != nil {
+		t.Fatalf("naming the same posture twice must be accepted: %v", err)
+	}
+}
+
+// (e) THE LOAD-BEARING GUARD. The posture name must never be forwarded to a
+// provider as an effort value — not by any path, not for any model.
+func TestZeromaxingIsNeverForwardedToAProvider(t *testing.T) {
+	registry, err := modelregistry.DefaultRegistry()
+	if err != nil {
+		t.Fatalf("DefaultRegistry: %v", err)
+	}
+	// Across a reasoning model, a non-reasoning model, and a model the catalog
+	// has never heard of (where unknown values are otherwise passed through).
+	for _, model := range []string{"claude-sonnet-4.5", "gpt-4.1", "some-custom-endpoint-model"} {
+		for _, spelling := range []string{"zeromaxing", "ZEROMAXING", "  Zeromaxing  "} {
+			if got := forwardedReasoningEffort(registry, model, spelling); got != "" {
+				t.Fatalf("forwardedReasoningEffort(%q, %q) = %q, want \"\" — the posture name is not a provider value",
+					model, spelling, got)
+			}
+		}
+	}
+	// The guard must not over-reach: real levels still forward.
+	if got := forwardedReasoningEffort(registry, "claude-sonnet-4.5", "high"); got != "high" {
+		t.Fatalf("a real level must still forward, got %q", got)
+	}
+}
+
+// (f) THE RESERVATION. /effort max and --reasoning-effort max are UNCHANGED by
+// this feature: "max" still parses as a raw provider level (ValidReasoningEffort
+// accepts ReasoningEffortMax) and still resolves to nothing usable on today's
+// models. The spelling stays free for a real provider rung.
+func TestEffortMaxReservationUnchangedCLI(t *testing.T) {
+	if !modelregistry.ValidReasoningEffort(modelregistry.ReasoningEffortMax) {
+		t.Fatal("ReasoningEffortMax must remain a valid raw effort value — the reservation depends on it")
+	}
+	if _, ok := execprofile.Lookup("max"); ok {
+		t.Fatal("\"max\" must NOT resolve to a profile — it is reserved for a provider rung")
+	}
+	registry, err := modelregistry.DefaultRegistry()
+	if err != nil {
+		t.Fatalf("DefaultRegistry: %v", err)
+	}
+	// No curated model lists "max", so it coerces away rather than forwarding.
+	if got := forwardedReasoningEffort(registry, "claude-sonnet-4.5", "max"); got == "max" {
+		t.Fatal("no current model supports \"max\"; it must not be forwarded as-is")
+	}
+	// And it must NOT be swallowed by the zeromaxing normalizer.
+	options := execOptions{reasoningEffort: "max"}
+	if err := normalizeZeromaxingEffort(&options); err != nil {
+		t.Fatalf("normalize: %v", err)
+	}
+	if options.reasoningEffort != "max" || options.execProfile != "" {
+		t.Fatalf("\"max\" must pass through the normalizer untouched, got effort=%q profile=%q",
+			options.reasoningEffort, options.execProfile)
+	}
+}
+
+// (l) CLI leg of the honesty rule: a model that cannot take the effort is TOLD.
+// reasoningEffortNotice is the existing coerce-and-tell helper, and it fires for
+// a PROFILE-FILLED effort, not just an explicitly flagged one.
+func TestZeromaxingUnsupportedEffortIsReportedCLI(t *testing.T) {
+	registry, err := modelregistry.DefaultRegistry()
+	if err != nil {
+		t.Fatalf("DefaultRegistry: %v", err)
+	}
+	const nonReasoning = "gpt-4.1" // a catalog model with no reasoning capability
+	notice := reasoningEffortNotice(registry, nonReasoning, "high")
+	if notice == "" {
+		t.Fatal("a non-reasoning model must produce a notice when an effort is requested")
+	}
+	if !strings.Contains(notice, "reasoning effort") {
+		t.Fatalf("the notice must explain what was not applied: %q", notice)
+	}
+	if forwarded := forwardedReasoningEffort(registry, nonReasoning, "high"); forwarded != "" {
+		t.Fatalf("forwarded effort = %q, want empty for a non-reasoning model", forwarded)
+	}
+	// ...and the rest of the posture still applies: the budget is unaffected.
+	profile, _ := execprofile.Lookup(execprofile.Name)
+	if effective, _ := applyProfileTurnBudget(profile, 0, 80); effective != 320 {
+		t.Fatalf("the turn budget must still apply on an unsupported model, got %d", effective)
+	}
+}
+
+// (m)+(n) CLI leg of the config gate.
+func TestZeromaxingSelectionRefusalCLI(t *testing.T) {
+	profile, _ := execprofile.Lookup(execprofile.Name)
+	if refusal := execprofile.SelectionRefusal(profile, true); refusal == "" {
+		t.Fatal("exec must refuse the posture when config disabled it")
+	}
+	if refusal := execprofile.SelectionRefusal(profile, false); refusal != "" {
+		t.Fatalf("exec must allow it when config did not disable it, got %q", refusal)
+	}
+}
+
+// (o) The raised budget PROPAGATES to spawned children. Deliberate — this is a
+// maximal posture — so it is asserted explicitly rather than left to be
+// discovered. applyProfileTurnBudget's effective value becomes resolved.MaxTurns,
+// which is what the run exports as ZERO_MAX_TURNS for sub-agents.
+func TestZeromaxingTurnBudgetPropagatesToChildren(t *testing.T) {
+	profile, _ := execprofile.Lookup(execprofile.Name)
+	effective, _ := applyProfileTurnBudget(profile, 0, 80)
+	if effective != 320 {
+		t.Fatalf("effective budget = %d, want 320", effective)
+	}
+	if effective > config.MaxTurnsCeiling {
+		t.Fatalf("the budget %d exceeds the shared ceiling %d", effective, config.MaxTurnsCeiling)
+	}
+	// The delta text promises exactly this, so the promise and the number must
+	// not drift apart.
+	if !strings.Contains(execprofile.Delta, "sub-agents") {
+		t.Fatalf("Delta must tell the user the budget reaches sub-agents: %q", execprofile.Delta)
+	}
+}
+
+// The headless posture mapping: selecting it enters; everything else is off.
+func TestExecZeromaxingMapping(t *testing.T) {
+	profile, _ := execprofile.Lookup(execprofile.Name)
+	if got := execZeromaxing(profile); got != agent.ZeromaxingEntering {
+		t.Fatalf("execZeromaxing(zeromaxing) = %v, want ZeromaxingEntering", got)
+	}
+	for _, name := range []string{"balanced", "fast", "thorough"} {
+		other, _ := execprofile.Lookup(name)
+		if got := execZeromaxing(other); got != agent.ZeromaxingOff {
+			t.Fatalf("execZeromaxing(%s) = %v, want ZeromaxingOff", name, got)
+		}
+	}
+	if got := execZeromaxing(execprofile.Profile{}); got != agent.ZeromaxingOff {
+		t.Fatalf("execZeromaxing(zero) = %v, want ZeromaxingOff", got)
+	}
+}
