@@ @@
+package specialist
+
+import (
+	"fmt"
+	"regexp"
+	"sort"
+	"strings"
+	"time"
+)
+
+// ZeroMaxing Phase 2: plan capture, executed SEQUENTIALLY.
+//
+// The deliverable is DATA. A plan declares a dependency graph, Zero runs it in
+// topological order one task at a time, and records how long each task took. If
+// the recorded max_speedup says fan-out would not have paid for itself, Phase 3
+// is not built — see PlanReport.MaxSpeedup.
+//
+// Fan-out, pipeline and phase are ONE structure: fan-out is tasks with no
+// dependencies, a pipeline is a chain, a phase is a label plus a barrier. The
+// prototype grew five separate hooks for these and never invoked any of them.
+
+// Plan is a validated, executable plan.
+//
+// Its fields are UNEXPORTED and ParsePlan is the only constructor. That is not
+// stylistic: it makes skipping validation impossible rather than merely wrong.
+// The prototype's validator was reachable, correct, and never called from the
+// production path; a type that cannot be constructed any other way removes the
+// choice.
+type Plan struct {
+	name        string
+	description string
+	tasks       []Task
+	budget      Budget
+	// order is the topological order Kahn's algorithm emitted during
+	// validation. The executor reuses it rather than recomputing, so admission
+	// and execution cannot disagree about the order or about acyclicity.
+	order []string
+}
+
+// Task is one unit of a plan.
+type Task struct {
+	ID        string
+	Prompt    string
+	DependsOn []string
+	// Tools is the read-only subset this task may use. Empty means "the parent's
+	// full read-only grant". It can only ever NARROW: validated here and
+	// intersected again at dispatch, so a validator bug cannot widen authority.
+	Tools []string
+	// Phase is a display and ordering label only. It carries no execution
+	// semantics in Phase 2 — a barrier is expressible as dependencies.
+	Phase string
+}
+
+// Budget bounds a plan. Every field is required to be sane at admission and
+// MaxTokens is enforced again at dispatch.
+type Budget struct {
+	// MaxWorkers must be 1. Phase 2 is sequential, and a plan asking for more is
+	// REJECTED rather than coerced — coercion would let a caller believe it got
+	// concurrency, and would make the field meaningless for Phase 3.
+	MaxWorkers int
+	MaxTokens  int
+	MaxWall    time.Duration
+}
+
+// Limits are the caller-supplied hard caps a plan must fit inside.
+type Limits struct {
+	// MaxTasks bounds plan size.
+	MaxTasks int
+	// MaxTokens is the ceiling a plan's own budget may not exceed.
+	MaxTokens int
+	// ParentTools is the grant the parent run holds. A task's Tools must be a
+	// subset; anything outside it is rejected.
+	ParentTools []string
+	// CurrentDepth is the depth of the run issuing the plan. Its tasks run one
+	// level deeper, so the check is against maxSpecialistDepth.
+	CurrentDepth int
+}
+
+// planIDPattern is an ALLOW-LIST. Enumerating permitted characters rather than
+// forbidden ones is this repo's standing rule for classification: every
+// deny-list here has leaked (git -C, then git -c, then --exec-path).
+var planIDPattern = regexp.MustCompile(`^[a-zA-Z0-9_-]+$`)
+
+// writeToolMarkers name the mutating capabilities Phase 2 tasks may not have.
+// Matched as an allow-list would be inverted, so this list is checked AGAINST a
+// read-only allow-list below rather than used as the primary gate.
+var planReadOnlyTools = map[string]bool{
+	"read_file":          true,
+	"read_minified_file": true,
+	"list_directory":     true,
+	"grep":               true,
+	"glob":               true,
+	"update_plan":        true,
+	"lsp_navigate":       true,
+}
+
+// Name, Description, Tasks and Budget expose a validated plan for execution and
+// reporting. Read-only accessors: a Plan cannot be mutated after ParsePlan.
+func (p Plan) Name() string        { return p.name }
+func (p Plan) Description() string { return p.description }
+func (p Plan) Budget() Budget      { return p.budget }
+
+// Tasks returns a copy so a caller cannot mutate a validated plan.
+func (p Plan) Tasks() []Task {
+	out := make([]Task, len(p.tasks))
+	copy(out, p.tasks)
+	return out
+}
+
+// Order returns the validated topological order.
+func (p Plan) Order() []string {
+	out := make([]string, len(p.order))
+	copy(out, p.order)
+	return out
+}
+
+// TaskCount is THE counting function. Both admission and the executor call it.
+//
+// It is a length, not a text scan. The prototype counted source text —
+// strings.Count(body, "agent(") in admission and a regex in the compiler — so
+// `agent ("x")` with one space counted as zero and executed anyway. Counting a
+// parsed structure removes the class rather than fixing the regex.
+func (p Plan) TaskCount() int { return len(p.tasks) }
+
+// ParsePlan is the ONLY way to obtain a Plan. It parses and validates in one
+// step; there is no path from tool arguments to an executable plan that skips
+// it. Every check rejects by default.
+func ParsePlan(args map[string]any, limits Limits) (Plan, error) {
+	plan := Plan{
+		name:        planString(args, "name"),
+		description: planString(args, "description"),
+	}
+
+	rawTasks, err := planTaskList(args)
+	if err != nil {
+		return Plan{}, err
+	}
+	if len(rawTasks) == 0 {
+		return Plan{}, fmt.Errorf("plan requires at least one task")
+	}
+	if limits.MaxTasks > 0 && len(rawTasks) > limits.MaxTasks {
+		return Plan{}, fmt.Errorf("plan has %d tasks, which exceeds the limit of %d", len(rawTasks), limits.MaxTasks)
+	}
+
+	// DEPTH, at admission. A plan runs inside a child at limits.CurrentDepth, so
+	// its tasks are one level deeper. Checking here — with the remaining
+	// headroom named — turns an opaque mid-plan failure into a rejection the
+	// caller can act on.
+	taskDepth := limits.CurrentDepth + 1
+	if taskDepth >= maxSpecialistDepth {
+		return Plan{}, fmt.Errorf(
+			"a plan's tasks would run at depth %d, which reaches the maximum nesting depth of %d; this run is already at depth %d, leaving no headroom for plan tasks",
+			taskDepth, maxSpecialistDepth, limits.CurrentDepth)
+	}
+
+	seen := map[string]bool{}
+	for index, raw := range rawTasks {
+		task, err := planTask(raw, index)
+		if err != nil {
+			return Plan{}, err
+		}
+		if seen[task.ID] {
+			return Plan{}, fmt.Errorf("task id %q appears more than once; ids must be unique", task.ID)
+		}
+		seen[task.ID] = true
+		if err := validateTaskTools(task, limits); err != nil {
+			return Plan{}, err
+		}
+		plan.tasks = append(plan.tasks, task)
+	}
+
+	// Every DependsOn must resolve. An unknown edge is REJECTED, never skipped:
+	// skipping it would silently execute a task whose stated precondition never
+	// ran, which is worse than refusing the plan.
+	for _, task := range plan.tasks {
+		for _, dep := range task.DependsOn {
+			if !seen[dep] {
+				return Plan{}, fmt.Errorf("task %q depends on %q, which is not a task in this plan", task.ID, dep)
+			}
+			if dep == task.ID {
+				return Plan{}, fmt.Errorf("task %q depends on itself", task.ID)
+			}
+		}
+	}
+
+	order, cycle := topologicalOrder(plan.tasks)
+	if cycle != nil {
+		return Plan{}, fmt.Errorf("plan has a dependency cycle involving: %s", strings.Join(cycle, ", "))
+	}
+	plan.order = order
+
+	budget, err := planBudget(args, limits)
+	if err != nil {
+		return Plan{}, err
+	}
+	plan.budget = budget
+	return plan, nil
+}
+
+// topologicalOrder runs Kahn's algorithm. It returns the emitted order, or the
+// ids still carrying unmet dependencies when the queue drains early — which is
+// exactly the set involved in a cycle.
+//
+// There was no cycle detection anywhere in this tree to reuse. Audit U24: a
+// cyclic page tree hangs forever precisely because nothing checks.
+func topologicalOrder(tasks []Task) (order []string, cycle []string) {
+	indegree := map[string]int{}
+	dependents := map[string][]string{}
+	for _, task := range tasks {
+		if _, ok := indegree[task.ID]; !ok {
+			indegree[task.ID] = 0
+		}
+		for _, dep := range task.DependsOn {
+			indegree[task.ID]++
+			dependents[dep] = append(dependents[dep], task.ID)
+		}
+	}
+
+	// Seed with every zero-indegree node, in declaration order so the emitted
+	// order is deterministic for a given plan.
+	ready := []string{}
+	for _, task := range tasks {
+		if indegree[task.ID] == 0 {
+			ready = append(ready, task.ID)
+		}
+	}
+	for len(ready) > 0 {
+		id := ready[0]
+		ready = ready[1:]
+		order = append(order, id)
+		next := append([]string(nil), dependents[id]...)
+		sort.Strings(next)
+		for _, dependent := range next {
+			indegree[dependent]--
+			if indegree[dependent] == 0 {
+				ready = append(ready, dependent)
+			}
+		}
+	}
+	if len(order) == len(tasks) {
+		return order, nil
+	}
+	// The queue drained early: everything still carrying an indegree is part of
+	// a cycle or downstream of one. Name them — an unnamed "cycle detected" is
+	// not actionable on a twenty-task plan.
+	for _, task := range tasks {
+		if indegree[task.ID] > 0 {
+			cycle = append(cycle, task.ID)
+		}
+	}
+	sort.Strings(cycle)
+	return nil, cycle
+}
+
+// validateTaskTools enforces both Phase 2 rules: read-only, and never wider
+// than the parent's grant. Enforced AGAIN at dispatch — see planToolGrant.
+func validateTaskTools(task Task, limits Limits) error {
+	parent := map[string]bool{}
+	for _, name := range limits.ParentTools {
+		parent[name] = true
+	}
+	for _, name := range task.Tools {
+		// READ-ONLY, by allow-list. Phase 2 tasks cannot write, edit or run
+		// shell: granting that is an authority widening that needs its own
+		// decision, not a side effect of shipping plan capture.
+		if !planReadOnlyTools[name] {
+			return fmt.Errorf("task %q requests tool %q; plan tasks are read-only in this phase and may only use: %s",
+				task.ID, name, strings.Join(sortedReadOnlyTools(), ", "))
+		}
+		if len(limits.ParentTools) > 0 && !parent[name] {
+			return fmt.Errorf("task %q requests tool %q, which this run does not hold; a task may narrow the parent's grant, never widen it",
+				task.ID, name)
+		}
+	}
+	return nil
+}
+
+func sortedReadOnlyTools() []string {
+	names := make([]string, 0, len(planReadOnlyTools))
+	for name := range planReadOnlyTools {
+		names = append(names, name)
+	}
+	sort.Strings(names)
+	return names
+}
+
+func planBudget(args map[string]any, limits Limits) (Budget, error) {
+	raw, ok := args["budget"].(map[string]any)
+	if !ok {
+		return Budget{}, fmt.Errorf("plan requires a budget object with max_tokens and max_workers")
+	}
+	budget := Budget{
+		MaxWorkers: planInt(raw, "max_workers"),
+		MaxTokens:  planInt(raw, "max_tokens"),
+	}
+	if seconds := planInt(raw, "max_wall_seconds"); seconds > 0 {
+		budget.MaxWall = time.Duration(seconds) * time.Second
+	}
+	// MaxWorkers must be exactly 1. Rejecting rather than coercing keeps the
+	// field meaningful: a caller that asked for 8 and silently got 1 would have
+	// been told nothing, and Phase 3 would inherit a field nobody trusts.
+	if budget.MaxWorkers != 1 {
+		return Budget{}, fmt.Errorf(
+			"budget.max_workers must be 1: this phase executes plan tasks sequentially, and a plan asking for %d is rejected rather than quietly run with one worker",
+			budget.MaxWorkers)
+	}
+	if budget.MaxTokens <= 0 {
+		return Budget{}, fmt.Errorf("budget.max_tokens is required and must be positive")
+	}
+	if limits.MaxTokens > 0 && budget.MaxTokens > limits.MaxTokens {
+		return Budget{}, fmt.Errorf("budget.max_tokens %d exceeds the limit of %d for this run", budget.MaxTokens, limits.MaxTokens)
+	}
+	return budget, nil
+}
+
+func planTask(raw any, index int) (Task, error) {
+	fields, ok := raw.(map[string]any)
+	if !ok {
+		return Task{}, fmt.Errorf("task at position %d is not an object", index)
+	}
+	task := Task{
+		ID:        planString(fields, "id"),
+		Prompt:    planString(fields, "prompt"),
+		DependsOn: planStrings(fields, "depends_on"),
+		Tools:     planStrings(fields, "tools"),
+		Phase:     planString(fields, "phase"),
+	}
+	if task.ID == "" {
+		return Task{}, fmt.Errorf("task at position %d has no id", index)
+	}
+	if !planIDPattern.MatchString(task.ID) {
+		return Task{}, fmt.Errorf("task id %q must use only letters, digits, hyphen and underscore", task.ID)
+	}
+	if task.Prompt == "" {
+		return Task{}, fmt.Errorf("task %q has no prompt", task.ID)
+	}
+	return task, nil
+}
+
+func planTaskList(args map[string]any) ([]any, error) {
+	raw, ok := args["tasks"]
+	if !ok {
+		return nil, fmt.Errorf("plan requires a tasks array")
+	}
+	list, ok := raw.([]any)
+	if !ok {
+		return nil, fmt.Errorf("plan tasks must be an array")
+	}
+	return list, nil
+}
+
+func planString(args map[string]any, key string) string {
+	if args == nil {
+		return ""
+	}
+	value, _ := args[key].(string)
+	return strings.TrimSpace(value)
+}
+
+func planStrings(args map[string]any, key string) []string {
+	raw, ok := args[key].([]any)
+	if !ok {
+		return nil
+	}
+	out := []string{}
+	for _, item := range raw {
+		if text, ok := item.(string); ok {
+			if trimmed := strings.TrimSpace(text); trimmed != "" {
+				out = append(out, trimmed)
+			}
+		}
+	}
+	return out
+}
+
+// planInt accepts the float64 a JSON number decodes to, as well as an int.
+func planInt(args map[string]any, key string) int {
+	switch value := args[key].(type) {
+	case float64:
+		return int(value)
+	case int:
+		return value
+	default:
+		return 0
+	}
+}
diff --git a/dev/zero/internal/specialist/plan_exec.go b/dev/zero/internal/specialist/plan_exec.go
--- /dev/null
+++ b/dev/zero/internal/specialist/plan_exec.go
@@ @@
+package specialist
+
+import (
+	"context"
+	"fmt"
+	"sort"
+	"strings"
+	"time"
+)
+
+// PlanStatus is a plan's terminal state.
+//
+// PARTIAL IS ITS OWN STATUS, with its own exit code. This repo has repeatedly
+// reported failure as success (audit RC-F), and in a plan that is worse:
+// nineteen of twenty tasks failing must never surface as a completed run.
+type PlanStatus string
+
+const (
+	// PlanCompleted: every task succeeded.
+	PlanCompleted PlanStatus = "completed"
+	// PlanPartial: at least one task succeeded and at least one failed, was
+	// skipped, or was cut off by the budget. Maps to exit 4 (exitIncomplete).
+	PlanPartial PlanStatus = "partial"
+	// PlanFailed: no task succeeded.
+	PlanFailed PlanStatus = "failed"
+)
+
+// TaskOutcome is why a task ended the way it did.
+type TaskOutcome string
+
+const (
+	TaskSucceeded TaskOutcome = "succeeded"
+	TaskFailed    TaskOutcome = "failed"
+	// TaskSkippedDependency: a dependency failed, so this never ran. RECORDED,
+	// never silently dropped — a task that vanished from the report would be
+	// indistinguishable from one that was never planned.
+	TaskSkippedDependency TaskOutcome = "dependency_failed"
+	// TaskSkippedBudget: the plan's token budget was exhausted before this
+	// task could be dispatched.
+	TaskSkippedBudget TaskOutcome = "budget_exhausted"
+)
+
+// TaskResult is one task's record.
+type TaskResult struct {
+	ID       string
+	Outcome  TaskOutcome
+	Duration time.Duration
+	// Output is the task's FULL result, verbatim. Not truncated here: the tool
+	// boundary budgets and redacts it exactly like any other tool output.
+	Output    string
+	Err       string
+	SessionID string
+	Tokens    int
+}
+
+// PlanReport is the plan's terminal record, carried in plan_completed.
+type PlanReport struct {
+	Status    PlanStatus
+	Tasks     []TaskResult
+	Succeeded int
+	Failed    int
+	Skipped   int
+	// SequentialTotal is the sum of task durations — what this run actually
+	// spent.
+	SequentialTotal time.Duration
+	// CriticalPath is the longest dependency-weighted path through the DAG: the
+	// wall time a perfectly parallel run could not go below.
+	CriticalPath time.Duration
+	// MaxSpeedup is SequentialTotal / CriticalPath — the THEORETICAL ceiling on
+	// what fan-out could buy, measured from a sequential run with no writes.
+	//
+	// This number decides whether Phase 3 is built. The kill criterion is a
+	// median of >= 2.0 across >= 20 real plans: below that the ceiling is too
+	// low for real coordination overhead to fit underneath, and concurrency
+	// would cost more than it returns.
+	//
+	// It answers VALUE, not safety. Independence-violation would answer safety,
+	// but read-only tasks are always safe to parallelise, so that rate would be
+	// 0 regardless and would decide nothing.
+	MaxSpeedup float64
+	TokensUsed int
+}
+
+// PlanRunner runs one task. The executor depends on this seam rather than on
+// Executor directly so the budget, ordering and failure semantics are testable
+// without launching child processes.
+type PlanRunner func(ctx context.Context, task Task, tools []string) (TaskResult, error)
+
+// PlanRecorder receives plan lifecycle events. Recording is BEST-EFFORT and
+// must never fail the run — it mirrors execSessionRecorder.append's contract,
+// where a latched error is surfaced once but the run continues.
+type PlanRecorder interface {
+	TaskDispatched(task Task)
+	TaskCompleted(result TaskResult)
+	TaskFailed(result TaskResult)
+}
+
+// ExecutePlan runs a plan SEQUENTIALLY in its validated topological order.
+//
+// The order comes from the same Kahn pass that proved the graph acyclic, so
+// admission and execution cannot disagree about it.
+func ExecutePlan(ctx context.Context, plan Plan, parentTools []string, run PlanRunner, recorder PlanRecorder) PlanReport {
+	tasks := map[string]Task{}
+	for _, task := range plan.Tasks() {
+		tasks[task.ID] = task
+	}
+
+	report := PlanReport{}
+	results := map[string]TaskResult{}
+	failed := map[string]bool{}
+	// budgetLeft is decremented as tasks complete. Enforced HERE, at dispatch —
+	// validation alone would be a promise, not a bound. Under the zeromaxing
+	// posture every child inherits a 320-turn ceiling, so a twenty-task plan
+	// authorises 6,400 child turns from a single tool call; this is what stands
+	// between that number and the user's bill.
+	budgetLeft := plan.Budget().MaxTokens
+	budgetExhausted := false
+
+	deadline := time.Time{}
+	if wall := plan.Budget().MaxWall; wall > 0 {
+		deadline = time.Now().Add(wall)
+	}
+
+	for _, id := range plan.Order() {
+		task := tasks[id]
+
+		if blocker, blocked := firstFailedDependency(task, failed); blocked {
+			result := TaskResult{
+				ID:      id,
+				Outcome: TaskSkippedDependency,
+				Err:     fmt.Sprintf("skipped: dependency %q did not succeed", blocker),
+			}
+			results[id] = result
+			failed[id] = true // its own dependents are blocked too
+			report.Skipped++
+			recordFailed(recorder, result)
+			continue
+		}
+
+		// A budget-exhausted or timed-out plan SKIPS the rest rather than
+		// aborting: independent work already done still counts, and the record
+		// must show what was not attempted.
+		if budgetExhausted || budgetLeft <= 0 || (!deadline.IsZero() && time.Now().After(deadline)) {
+			budgetExhausted = true
+			result := TaskResult{
+				ID:      id,
+				Outcome: TaskSkippedBudget,
+				Err:     "skipped: the plan's budget was exhausted before this task ran",
+			}
+			results[id] = result
+			failed[id] = true
+			report.Skipped++
+			recordFailed(recorder, result)
+			continue
+		}
+
+		recordDispatched(recorder, task)
+		started := time.Now()
+		// BELT AND BRACES with the validator: the grant is intersected again
+		// here, so a validation bug cannot widen a task's authority. Same shape
+		// as Phase 1's forwardedReasoningEffort guard.
+		result, err := run(ctx, task, planToolGrant(task, parentTools))
+		result.ID = id
+		if result.Duration == 0 {
+			result.Duration = time.Since(started)
+		}
+		report.SequentialTotal += result.Duration
+		budgetLeft -= result.Tokens
+		report.TokensUsed += result.Tokens
+
+		if err != nil || result.Outcome == TaskFailed {
+			result.Outcome = TaskFailed
+			if result.Err == "" && err != nil {
+				result.Err = err.Error()
+			}
+			results[id] = result
+			failed[id] = true
+			report.Failed++
+			recordFailed(recorder, result)
+			continue
+		}
+		result.Outcome = TaskSucceeded
+		results[id] = result
+		report.Succeeded++
+		recordCompleted(recorder, result)
+	}
+
+	for _, id := range plan.Order() {
+		report.Tasks = append(report.Tasks, results[id])
+	}
+	report.CriticalPath = criticalPath(plan, results)
+	report.MaxSpeedup = speedup(report.SequentialTotal, report.CriticalPath)
+	report.Status = terminalStatus(report)
+	return report
+}
+
+// terminalStatus maps counts onto the three terminal states. Partial is its own
+// status precisely so a mostly-failed plan can never be reported as success.
+func terminalStatus(report PlanReport) PlanStatus {
+	switch {
+	case report.Succeeded == 0:
+		return PlanFailed
+	case report.Failed == 0 && report.Skipped == 0:
+		return PlanCompleted
+	default:
+		return PlanPartial
+	}
+}
+
+// firstFailedDependency names the dependency that blocked a task, so the record
+// says WHICH one rather than just that something upstream broke.
+func firstFailedDependency(task Task, failed map[string]bool) (string, bool) {
+	deps := append([]string(nil), task.DependsOn...)
+	sort.Strings(deps)
+	for _, dep := range deps {
+		if failed[dep] {
+			return dep, true
+		}
+	}
+	return "", false
+}
+
+// planToolGrant intersects a task's requested tools with the parent's grant.
+// An empty request inherits the parent's read-only grant; it never widens it.
+func planToolGrant(task Task, parentTools []string) []string {
+	parent := map[string]bool{}
+	for _, name := range parentTools {
+		parent[name] = true
+	}
+	if len(task.Tools) == 0 {
+		out := []string{}
+		for _, name := range parentTools {
+			if planReadOnlyTools[name] {
+				out = append(out, name)
+			}
+		}
+		sort.Strings(out)
+		return out
+	}
+	out := []string{}
+	for _, name := range task.Tools {
+		if !planReadOnlyTools[name] {
+			continue
+		}
+		if len(parentTools) > 0 && !parent[name] {
+			continue
+		}
+		out = append(out, name)
+	}
+	sort.Strings(out)
+	return out
+}
+
+// criticalPath is the longest dependency-weighted path through the DAG: for
+// each task, its own duration plus the longest path among its dependencies.
+// Computed over the validated topological order, so every dependency is already
+// resolved when a task is reached.
+func criticalPath(plan Plan, results map[string]TaskResult) time.Duration {
+	longest := map[string]time.Duration{}
+	tasks := map[string]Task{}
+	for _, task := range plan.Tasks() {
+		tasks[task.ID] = task
+	}
+	var best time.Duration
+	for _, id := range plan.Order() {
+		var upstream time.Duration
+		for _, dep := range tasks[id].DependsOn {
+			if longest[dep] > upstream {
+				upstream = longest[dep]
+			}
+		}
+		longest[id] = upstream + results[id].Duration
+		if longest[id] > best {
+			best = longest[id]
+		}
+	}
+	return best
+}
+
+// speedup is sequential / critical-path, guarded against a zero denominator (a
+// plan whose tasks all took no measurable time).
+func speedup(sequential, critical time.Duration) float64 {
+	if critical <= 0 {
+		return 0
+	}
+	return float64(sequential) / float64(critical)
+}
+
+// Summary renders the plan's result for the model, including max_speedup — the
+// number the Phase 3 decision rests on, surfaced rather than buried in an event.
+func (report PlanReport) Summary() string {
+	var b strings.Builder
+	fmt.Fprintf(&b, "Plan %s: %d succeeded, %d failed, %d skipped.\n", report.Status, report.Succeeded, report.Failed, report.Skipped)
+	fmt.Fprintf(&b, "sequential total: %s · critical path: %s · max_speedup: %.2fx\n",
+		report.SequentialTotal.Round(time.Millisecond), report.CriticalPath.Round(time.Millisecond), report.MaxSpeedup)
+	for _, task := range report.Tasks {
+		fmt.Fprintf(&b, "\n  - %s [%s] %s", task.ID, task.Outcome, task.Duration.Round(time.Millisecond))
+		if task.Output != "" {
+			b.WriteString("\n      result:\n" + task.Output)
+		}
+		if task.Err != "" {
+			b.WriteString("\n      error:\n" + task.Err)
+		}
+	}
+	return b.String()
+}
+
+func recordDispatched(recorder PlanRecorder, task Task) {
+	if recorder != nil {
+		recorder.TaskDispatched(task)
+	}
+}
+
+func recordCompleted(recorder PlanRecorder, result TaskResult) {
+	if recorder != nil {
+		recorder.TaskCompleted(result)
+	}
+}
+
+func recordFailed(recorder PlanRecorder, result TaskResult) {
+	if recorder != nil {
+		recorder.TaskFailed(result)
+	}
+}
diff --git a/dev/zero/internal/specialist/plan_test.go b/dev/zero/internal/specialist/plan_test.go
--- /dev/null
+++ b/dev/zero/internal/specialist/plan_test.go
@@ @@
+package specialist
+
+import (
+	"context"
+	"errors"
+	"strings"
+	"testing"
+	"time"
+
+	"github.com/Gitlawb/zero/internal/tools"
+)
+
+func planArgs(tasks []any, budget map[string]any) map[string]any {
+	return map[string]any{"name": "p", "tasks": tasks, "budget": budget}
+}
+
+func okBudget() map[string]any {
+	return map[string]any{"max_workers": float64(1), "max_tokens": float64(1000)}
+}
+
+func task(id, prompt string, deps ...string) map[string]any {
+	out := map[string]any{"id": id, "prompt": prompt}
+	if len(deps) > 0 {
+		raw := make([]any, len(deps))
+		for i, d := range deps {
+			raw[i] = d
+		}
+		out["depends_on"] = raw
+	}
+	return out
+}
+
+func readOnlyLimits() Limits {
+	return Limits{MaxTasks: 20, MaxTokens: 100_000, ParentTools: []string{"read_file", "grep", "glob"}}
+}
+
+// (e) ParsePlan is the ONLY constructor. A zero Plan is inert, so no exported
+// path can produce an executable plan that skipped validation.
+func TestParsePlanIsTheOnlyConstructor(t *testing.T) {
+	var zero Plan
+	if zero.TaskCount() != 0 || len(zero.Order()) != 0 || len(zero.Tasks()) != 0 {
+		t.Fatal("a zero Plan must carry no tasks and no order")
+	}
+	// Executing one runs nothing and reports failed — never success.
+	report := ExecutePlan(context.Background(), zero, nil, func(context.Context, Task, []string) (TaskResult, error) {
+		t.Fatal("a zero Plan must not dispatch anything")
+		return TaskResult{}, nil
+	}, nil)
+	if report.Status != PlanFailed {
+		t.Fatalf("a zero Plan must report failed, got %q", report.Status)
+	}
+	// Tasks() returns a copy: mutating it cannot corrupt a validated plan.
+	plan, err := ParsePlan(planArgs([]any{task("a", "do a")}, okBudget()), readOnlyLimits())
+	if err != nil {
+		t.Fatalf("ParsePlan: %v", err)
+	}
+	copied := plan.Tasks()
+	copied[0].ID = "mutated"
+	if plan.Tasks()[0].ID != "a" {
+		t.Fatal("Tasks() must return a copy; a validated plan is immutable")
+	}
+}
+
+// (f) A cycle is rejected AND the involved ids are named. Audit U24: a cyclic
+// graph hangs forever precisely because nothing checks.
+func TestParsePlanRejectsCyclesAndNamesThem(t *testing.T) {
+	cases := []struct {
+		name  string
+		tasks []any
+		want  []string
+	}{
+		{"two-node cycle", []any{task("a", "x", "b"), task("b", "y", "a")}, []string{"a", "b"}},
+		{"three-node cycle", []any{task("a", "x", "c"), task("b", "y", "a"), task("c", "z", "b")}, []string{"a", "b", "c"}},
+		{"cycle with an innocent bystander", []any{
+			task("free", "x"), task("a", "y", "b"), task("b", "z", "a"),
+		}, []string{"a", "b"}},
+	}
+	for _, tc := range cases {
+		t.Run(tc.name, func(t *testing.T) {
+			_, err := ParsePlan(planArgs(tc.tasks, okBudget()), readOnlyLimits())
+			if err == nil {
+				t.Fatal("a cyclic plan must be rejected")
+			}
+			if !strings.Contains(err.Error(), "cycle") {
+				t.Fatalf("the error must say it is a cycle: %v", err)
+			}
+			for _, id := range tc.want {
+				if !strings.Contains(err.Error(), id) {
+					t.Fatalf("the error must name %q so a 20-task plan is actionable: %v", id, err)
+				}
+			}
+			if tc.name == "cycle with an innocent bystander" && strings.Contains(err.Error(), "free") {
+				t.Fatalf("a task outside the cycle must not be named: %v", err)
+			}
+		})
+	}
+}
+
+// A self-edge is a cycle of one and must be rejected too.
+func TestParsePlanRejectsSelfDependency(t *testing.T) {
+	_, err := ParsePlan(planArgs([]any{task("a", "x", "a")}, okBudget()), readOnlyLimits())
+	if err == nil || !strings.Contains(err.Error(), "itself") {
+		t.Fatalf("a self-dependency must be rejected, got %v", err)
+	}
+}
+
+// (g) An unknown edge is REJECTED, never skipped: skipping would run a task
+// whose stated precondition never existed.
+func TestParsePlanRejectsUnknownDependency(t *testing.T) {
+	_, err := ParsePlan(planArgs([]any{task("a", "x", "ghost")}, okBudget()), readOnlyLimits())
+	if err == nil {
+		t.Fatal("an unknown dependency must be rejected")
+	}
+	for _, want := range []string{"a", "ghost"} {
+		if !strings.Contains(err.Error(), want) {
+			t.Fatalf("the error must name %q: %v", want, err)
+		}
+	}
+}
+
+// (h) Duplicate ids are rejected — otherwise the graph is ambiguous.
+func TestParsePlanRejectsDuplicateIDs(t *testing.T) {
+	_, err := ParsePlan(planArgs([]any{task("a", "x"), task("a", "y")}, okBudget()), readOnlyLimits())
+	if err == nil || !strings.Contains(err.Error(), "unique") {
+		t.Fatalf("duplicate ids must be rejected, got %v", err)
+	}
+}
+
+// IDs use an ALLOW-LIST charset. A deny-list here would leak, as every
+// deny-list in this repo has.
+func TestParsePlanRejectsIDsOutsideTheAllowList(t *testing.T) {
+	for _, bad := range []string{"a b", "a/b", "a.b", "../x", "a;b", "a\nb", "a$b", ""} {
+		_, err := ParsePlan(planArgs([]any{task(bad, "x")}, okBudget()), readOnlyLimits())
+		if err == nil {
+			t.Fatalf("id %q must be rejected", bad)
+		}
+	}
+	for _, good := range []string{"a", "A1", "read-file", "read_file", "a-b_c9"} {
+		if _, err := ParsePlan(planArgs([]any{task(good, "x")}, okBudget()), readOnlyLimits()); err != nil {
+			t.Fatalf("id %q must be accepted: %v", good, err)
+		}
+	}
+}
+
+// (i) MaxWorkers > 1 is REJECTED, not coerced. Coercion would let a caller
+// believe it got concurrency and would make the field meaningless for Phase 3.
+func TestParsePlanRejectsMoreThanOneWorker(t *testing.T) {
+	for _, workers := range []float64{0, 2, 8} {
+		budget := okBudget()
+		budget["max_workers"] = workers
+		_, err := ParsePlan(planArgs([]any{task("a", "x")}, budget), readOnlyLimits())
+		if err == nil {
+			t.Fatalf("max_workers %v must be rejected", workers)
+		}
+		if !strings.Contains(err.Error(), "sequentially") {
+			t.Fatalf("the error must say why: %v", err)
+		}
+	}
+}
+
+// (j) A budget is required, and max_tokens with it.
+func TestParsePlanRequiresABudget(t *testing.T) {
+	if _, err := ParsePlan(map[string]any{"tasks": []any{task("a", "x")}}, readOnlyLimits()); err == nil {
+		t.Fatal("a plan with no budget must be rejected")
+	}
+	budget := okBudget()
+	delete(budget, "max_tokens")
+	_, err := ParsePlan(planArgs([]any{task("a", "x")}, budget), readOnlyLimits())
+	if err == nil || !strings.Contains(err.Error(), "max_tokens") {
+		t.Fatalf("a missing max_tokens must be rejected, got %v", err)
+	}
+	over := okBudget()
+	over["max_tokens"] = float64(999_999_999)
+	if _, err := ParsePlan(planArgs([]any{task("a", "x")}, over), readOnlyLimits()); err == nil {
+		t.Fatal("a budget above the run's limit must be rejected")
+	}
+}
+
+// (k) Depth is checked AT ADMISSION, and the message names the headroom rather
+// than failing opaquely partway through a plan.
+func TestParsePlanRejectsInsufficientDepthHeadroom(t *testing.T) {
+	limits := readOnlyLimits()
+	limits.CurrentDepth = maxSpecialistDepth - 1 // tasks would be AT the cap
+	_, err := ParsePlan(planArgs([]any{task("a", "x")}, okBudget()), limits)
+	if err == nil {
+		t.Fatal("a plan with no depth headroom must be rejected at admission")
+	}
+	for _, want := range []string{"depth", "headroom"} {
+		if !strings.Contains(err.Error(), want) {
+			t.Fatalf("the error must explain the headroom: %v", err)
+		}
+	}
+	// One level shallower still fits.
+	limits.CurrentDepth = maxSpecialistDepth - 2
+	if _, err := ParsePlan(planArgs([]any{task("a", "x")}, okBudget()), limits); err != nil {
+		t.Fatalf("a plan with headroom must be accepted: %v", err)
+	}
+}
+
+// (l) ONE counting function, used by admission and the executor, agreeing on
+// every size. The prototype counted source text and `agent ("x")` counted zero.
+func TestTaskCountAgreesBetweenAdmissionAndExecution(t *testing.T) {
+	for _, size := range []int{1, 2, 20} {
+		raw := make([]any, size)
+		for i := range raw {
