 func (tool *OrchestrateTool) Run(ctx context.Context, args map[string]any) tools.Result {
 	return tool.RunWithOptions(ctx, args, tools.RunOptions{})
 }
+
+// runnerWithProgress attaches the caller's progress callback to every task
+// request.
+//
+// PER CALL, not captured at construction: RunTask is built once at
+// registration and holds only run-invariant state, while the progress callback
+// belongs to one tool call. Capturing it in NewPlanRunner is precisely the
+// mistake the runner's own doc comment warns about.
+//
+// The callback is shared by every task rather than keyed per task, because the
+// loop's callback carries only the parent's tool-call id and has no room for a
+// sub-key. That is sound HERE and only here: MaxWorkers is validated to be 1,
+// so exactly one task is in flight at any moment and the consumer can attribute
+// events to the task it last saw dispatched. Stage 2d must revisit this the
+// moment two tasks can run at once — see the note on the TUI plan recorder.
+func (tool *OrchestrateTool) runnerWithProgress(options tools.RunOptions) PlanRunner {
+	run := tool.RunTask
+	if run == nil || options.Progress == nil {
+		return run
+	}
+	return func(ctx context.Context, req PlanTaskRequest) (TaskResult, error) {
+		req.Progress = options.Progress
+		return run(ctx, req)
+	}
+}
diff --git a/dev/zero/internal/tui/plan_progress.go b/dev/zero/internal/tui/plan_progress.go
--- /dev/null
+++ b/dev/zero/internal/tui/plan_progress.go
@@ @@
+package tui
+
+import (
+	"fmt"
+	"strings"
+	"sync"
+
+	tea "github.com/charmbracelet/bubbletea"
+
+	"github.com/Gitlawb/zero/internal/specialist"
+)
+
+// PlanProgressBridge turns plan lifecycle events into TUI messages.
+//
+// LIFETIME, and it is the PostureGate problem again: the registry is built once
+// per session and the orchestrate tool holds this recorder for the process's
+// life, while the run id changes on every run. So this is a POINTER with
+// mutable state that the model re-attaches per run, not a closure over a
+// value-typed model that would freeze the first run's id forever.
+//
+// THREAD SAFETY: every method here is called from the tool's goroutine, never
+// from the Bubble Tea event loop. It takes a mutex, builds a message, and hands
+// it to the sink — which is the same asynchronous path OnToolProgress already
+// uses. Nothing here renders, blocks, or touches model state.
+//
+// BEST EFFORT, like every other recorder on this path: a nil bridge, a nil sink
+// or an unattached run is a silent no-op. Recording must never be the thing
+// that fails a plan (execSessionRecorder.append's contract).
+type PlanProgressBridge struct {
+	mu    sync.Mutex
+	sink  func(tea.Msg)
+	runID int
+	// dispatched counts tasks so each gets a unique temporary card key. The
+	// child's real session id is not known until the child process creates it,
+	// so the card is keyed by this and reconciled on completion — exactly how
+	// the Task tool's card works.
+	dispatched int
+}
+
+// NewPlanProgressBridge returns a bridge that is inert until Attach is called.
+func NewPlanProgressBridge() *PlanProgressBridge { return &PlanProgressBridge{} }
+
+// Attach binds the bridge to the run that is about to start. Called on every
+// run so a plan's cards belong to the run that produced them; the stale-run
+// guard in the message handlers does the rest.
+func (bridge *PlanProgressBridge) Attach(sink func(tea.Msg), runID int) {
+	if bridge == nil {
+		return
+	}
+	bridge.mu.Lock()
+	defer bridge.mu.Unlock()
+	bridge.sink = sink
+	bridge.runID = runID
+	bridge.dispatched = 0
+}
+
+// send posts a message if the bridge is attached. Nil-safe at every level.
+func (bridge *PlanProgressBridge) send(build func(runID int) tea.Msg) {
+	if bridge == nil {
+		return
+	}
+	bridge.mu.Lock()
+	sink, runID := bridge.sink, bridge.runID
+	bridge.mu.Unlock()
+	if sink == nil {
+		return
+	}
+	sink(build(runID))
+}
+
+// planTaskKey is the temporary card key for the nth dispatched task. Namespaced
+// so it can never collide with a tool call id.
+func planTaskKey(n int) string { return fmt.Sprintf("plantask_%d", n) }
+
+// PlanAdmitted announces the plan so the transcript can show that N tasks are
+// about to run rather than going silent until the first one finishes.
+func (bridge *PlanProgressBridge) PlanAdmitted(plan specialist.Plan) {
+	name := plan.Name()
+	count := plan.TaskCount()
+	bridge.send(func(runID int) tea.Msg {
+		return planAdmittedMsg{runID: runID, name: name, taskCount: count}
+	})
+}
+
+// TaskDispatched opens a card for the task that is about to run.
+func (bridge *PlanProgressBridge) TaskDispatched(task specialist.Task) {
+	if bridge == nil {
+		return
+	}
+	bridge.mu.Lock()
+	bridge.dispatched++
+	key := planTaskKey(bridge.dispatched)
+	bridge.mu.Unlock()
+
+	id, summary := task.ID, planTaskSummary(task)
+	bridge.send(func(runID int) tea.Msg {
+		return planTaskStartMsg{runID: runID, taskID: id, summary: summary, cardKey: key}
+	})
+}
+
+// TaskCompleted closes the card and reconciles it to the child's real session
+// id so the user can drill into it.
+func (bridge *PlanProgressBridge) TaskCompleted(result specialist.TaskResult) {
+	bridge.finish(result, specialistCompleted)
+}
+
+// TaskFailed closes the card with the outcome's own status. A cancelled or
+// skipped task is NOT rendered as an error: nothing broke.
+func (bridge *PlanProgressBridge) TaskFailed(result specialist.TaskResult) {
+	bridge.finish(result, planOutcomeStatus(result.Outcome))
+}
+
+func (bridge *PlanProgressBridge) finish(result specialist.TaskResult, status specialistStatus) {
+	if bridge == nil {
+		return
+	}
+	bridge.mu.Lock()
+	key := planTaskKey(bridge.dispatched)
+	bridge.mu.Unlock()
+
+	// A task that was never dispatched (dependency-skipped, budget-skipped,
+	// cancelled before it ran) has no card. Reporting it against the LAST
+	// dispatched task's key would close the wrong card, so those carry their
+	// own key and the handler creates the card on demand.
+	dispatched := result.Outcome == specialist.TaskSucceeded || result.Outcome == specialist.TaskFailed
+	taskID, sessionID, reason := result.ID, result.SessionID, result.Err
+	outcome := result.Outcome
+	bridge.send(func(runID int) tea.Msg {
+		return planTaskDoneMsg{
+			runID:      runID,
+			taskID:     taskID,
+			cardKey:    key,
+			dispatched: dispatched,
+			sessionID:  sessionID,
+			status:     status,
+			outcome:    string(outcome),
+			reason:     reason,
+		}
+	})
+}
+
+// PlanCompleted reports the plan's terminal state.
+func (bridge *PlanProgressBridge) PlanCompleted(plan specialist.Plan, report specialist.PlanReport) {
+	name := plan.Name()
+	status := string(report.Status)
+	succeeded, failed := report.Succeeded, report.Succeeded
+	failed, skipped, cancelled := report.Failed, report.Skipped, report.Cancelled
+	tokens, limit := report.TokensUsed, plan.Budget().MaxTokens
+	speedup := report.MaxSpeedup
+	bridge.send(func(runID int) tea.Msg {
+		return planCompletedMsg{
+			runID: runID, name: name, status: status,
+			succeeded: succeeded, failed: failed, skipped: skipped, cancelled: cancelled,
+			tokensUsed: tokens, tokenLimit: limit, maxSpeedup: speedup,
+		}
+	})
+}
+
+// planOutcomeStatus maps a task outcome onto the card status. Cancelled and
+// skipped are deliberately NOT specialistError: a user who stopped a plan did
+// not break it, and a task skipped because its dependency failed is not itself
+// a failure.
+func planOutcomeStatus(outcome specialist.TaskOutcome) specialistStatus {
+	switch outcome {
+	case specialist.TaskSucceeded:
+		return specialistCompleted
+	case specialist.TaskFailed:
+		return specialistError
+	default:
+		// Cancelled, dependency-skipped, budget-skipped: ended without running
+		// to completion, but not an error.
+		return specialistCancelled
+	}
+}
+
+// planTaskSummary is a SHORT label for the card. The full prompt stays in the
+// tool output; a display surface never becomes the data path.
+func planTaskSummary(task specialist.Task) string {
+	summary := strings.TrimSpace(task.Prompt)
+	if summary == "" {
+		return ""
+	}
+	if index := strings.IndexAny(summary, "\r\n"); index >= 0 {
+		summary = summary[:index]
+	}
+	return truncateRunes(summary, planTaskSummaryWidth)
+}
+
+const planTaskSummaryWidth = 60
+
+// truncateRunes cuts on RUNE boundaries, never bytes — slicing a multi-byte
+// string by byte index produces mojibake, which this repo has shipped before.
+func truncateRunes(text string, limit int) string {
+	if limit <= 0 {
+		return ""
+	}
+	runes := []rune(text)
+	if len(runes) <= limit {
+		return text
+	}
+	if limit == 1 {
+		return "…"
+	}
+	return string(runes[:limit-1]) + "…"
+}
diff --git a/dev/zero/internal/tui/plan_messages.go b/dev/zero/internal/tui/plan_messages.go
--- /dev/null
+++ b/dev/zero/internal/tui/plan_messages.go
@@ @@
+package tui
+
+import (
+	"fmt"
+	"strings"
+)
+
+// Plan lifecycle messages, posted from the tool goroutine by
+// PlanProgressBridge and consumed on the Bubble Tea event loop. Each carries
+// runID so the stale-run guard can drop messages from a superseded run, exactly
+// like specialistStartMsg.
+
+// planAdmittedMsg announces a validated plan before its first task runs, so a
+// plan does not read as a frozen session until the first task finishes.
+type planAdmittedMsg struct {
+	runID     int
+	name      string
+	taskCount int
+}
+
+// planTaskStartMsg opens a card for a dispatched task. cardKey is a temporary
+// id (the child session does not exist yet) reconciled on completion.
+type planTaskStartMsg struct {
+	runID   int
+	taskID  string
+	summary string
+	cardKey string
+}
+
+// planTaskDoneMsg closes a task's card.
+//
+// dispatched distinguishes a task that ran from one that never started
+// (dependency-skipped, budget-skipped, cancelled before dispatch). A task that
+// never started has no card, and closing the last dispatched task's card for it
+// would mark the wrong task — the specialist-card collision defect in a new
+// costume.
+type planTaskDoneMsg struct {
+	runID      int
+	taskID     string
+	cardKey    string
+	dispatched bool
+	sessionID  string
+	status     specialistStatus
+	outcome    string
+	reason     string
+}
+
+// planCompletedMsg carries the plan's terminal record.
+type planCompletedMsg struct {
+	runID      int
+	name       string
+	status     string
+	succeeded  int
+	failed     int
+	skipped    int
+	cancelled  int
+	tokensUsed int
+	tokenLimit int
+	maxSpeedup float64
+}
+
+// planNoticeLine renders the one-line plan notices shown in the transcript.
+// Kept here beside the messages so the wording and the data stay together.
+func planAdmittedLine(name string, taskCount int) string {
+	label := "tasks"
+	if taskCount == 1 {
+		label = "task"
+	}
+	if strings.TrimSpace(name) == "" {
+		return fmt.Sprintf("plan: %d %s", taskCount, label)
+	}
+	return fmt.Sprintf("plan %q: %d %s", name, taskCount, label)
+}
+
+func planCompletedLine(msg planCompletedMsg) string {
+	var b strings.Builder
+	fmt.Fprintf(&b, "plan %s: %d succeeded", msg.status, msg.succeeded)
+	if msg.failed > 0 {
+		fmt.Fprintf(&b, ", %d failed", msg.failed)
+	}
+	if msg.skipped > 0 {
+		fmt.Fprintf(&b, ", %d skipped", msg.skipped)
+	}
+	if msg.cancelled > 0 {
+		fmt.Fprintf(&b, ", %d cancelled", msg.cancelled)
+	}
+	if msg.tokenLimit > 0 {
+		fmt.Fprintf(&b, " · %d/%d tokens", msg.tokensUsed, msg.tokenLimit)
+	}
+	if msg.maxSpeedup > 0 {
+		fmt.Fprintf(&b, " · max_speedup %.2fx", msg.maxSpeedup)
+	}
+	return b.String()
+}
diff --git a/dev/zero/internal/agent/child_progress_test.go b/dev/zero/internal/agent/child_progress_test.go
--- /dev/null
+++ b/dev/zero/internal/agent/child_progress_test.go
@@ @@
+package agent
+
+import (
+	"context"
+	"testing"
+
+	"github.com/Gitlawb/zero/internal/streamjson"
+	"github.com/Gitlawb/zero/internal/tools"
+)
+
+// progressProbeTool records whether the loop handed it a progress callback.
+// streams mirrors what a real tool declares via tools.ChildProgressStreamer.
+type progressProbeTool struct {
+	name     string
+	streams  bool
+	declares bool
+	got      *bool
+}
+
+func (t *progressProbeTool) Name() string        { return t.name }
+func (t *progressProbeTool) Description() string { return "probe" }
+func (t *progressProbeTool) Parameters() tools.Schema {
+	return tools.Schema{Type: "object", Properties: map[string]tools.PropertySchema{}}
+}
+func (t *progressProbeTool) Safety() tools.Safety {
+	return tools.Safety{SideEffect: tools.SideEffectReadOnly, Permission: tools.PermissionAllow}
+}
+func (t *progressProbeTool) Run(context.Context, map[string]any) tools.Result {
+	*t.got = false
+	return tools.Result{Status: tools.StatusOK, Output: "ok"}
+}
+func (t *progressProbeTool) RunWithOptions(_ context.Context, _ map[string]any, options tools.RunOptions) tools.Result {
+	*t.got = options.Progress != nil
+	return tools.Result{Status: tools.StatusOK, Output: "ok"}
+}
+
+// StreamsChildProgress is only defined when declares is true — but Go has no
+// conditional method sets, so the type always implements the interface and the
+// flag drives the answer. A tool that never declares is modelled by
+// silentProbeTool below, which genuinely does not implement it.
+func (t *progressProbeTool) StreamsChildProgress() bool { return t.streams }
+
+// silentProbeTool does NOT implement tools.ChildProgressStreamer at all — the
+// state every tool in the tree is in today except Task and orchestrate.
+type silentProbeTool struct {
+	name string
+	got  *bool
+}
+
+func (t *silentProbeTool) Name() string        { return t.name }
+func (t *silentProbeTool) Description() string { return "probe" }
+func (t *silentProbeTool) Parameters() tools.Schema {
+	return tools.Schema{Type: "object", Properties: map[string]tools.PropertySchema{}}
+}
+func (t *silentProbeTool) Safety() tools.Safety {
+	return tools.Safety{SideEffect: tools.SideEffectReadOnly, Permission: tools.PermissionAllow}
+}
+func (t *silentProbeTool) Run(context.Context, map[string]any) tools.Result {
+	*t.got = false
+	return tools.Result{Status: tools.StatusOK, Output: "ok"}
+}
+func (t *silentProbeTool) RunWithOptions(_ context.Context, _ map[string]any, options tools.RunOptions) tools.Result {
+	*t.got = options.Progress != nil
+	return tools.Result{Status: tools.StatusOK, Output: "ok"}
+}
+
+func runProbe(t *testing.T, tool tools.Tool, got *bool, withSink bool) bool {
+	t.Helper()
+	registry := tools.NewRegistry()
+	registry.Register(tool)
+	options := Options{}
+	if withSink {
+		options.OnToolProgress = func(string, streamjson.Event) {}
+	}
+	result, err := executeToolCall(context.Background(),
+		registry,
+		ToolCall{ID: "call_1", Name: tool.Name(), Arguments: "{}"},
+		PermissionModeUnsafe,
+		options)
+	if err != nil {
+		t.Fatalf("executeToolCall: %v", err)
+	}
+	if result.Status == "" {
+		t.Fatalf("probe produced no result")
+	}
+	return *got
+}
+
+// THE PARITY OBLIGATION for un-gating the progress path.
+//
+// The relationship asserted here is EQUALITY, per RULES.md §3: a tool's
+// progress wiring before and after this change must be the same for every tool
+// that already had it and every tool that already lacked it. Only a tool that
+// newly DECLARES the interface may change.
+//
+// The name gate is gone, so the guarantee cannot be "Task still works" — it has
+// to be stated in terms of the declaration, which is what these cases do.
+func TestProgressCallbackFollowsTheDeclarationNotTheName(t *testing.T) {
+	t.Run("a declaring tool receives it (Task's behaviour, preserved)", func(t *testing.T) {
+		var got bool
+		// Named something other than "Task" ON PURPOSE: under the old name gate
+		// this case failed, which is the whole point of the change.
+		if !runProbe(t, &progressProbeTool{name: "spawner", streams: true, got: &got}, &got, true) {
+			t.Fatal("a tool declaring StreamsChildProgress must receive the callback")
+		}
+	})
+
+	t.Run("a tool named Task that does NOT declare gets nothing", func(t *testing.T) {
+		var got bool
+		// The inverse of the old behaviour, and the reason a name is the wrong
+		// key: identity is not capability.
+		if runProbe(t, &silentProbeTool{name: "Task", got: &got}, &got, true) {
+			t.Fatal("the callback must follow the declaration, not the name")
+		}
+	})
+
+	t.Run("a non-declaring tool receives nothing (every other tool, unchanged)", func(t *testing.T) {
+		var got bool
+		if runProbe(t, &silentProbeTool{name: "read_file", got: &got}, &got, true) {
+			t.Fatal("un-gating must not start handing a callback to tools that never had one")
+		}
+	})
+
+	t.Run("a declaring tool that answers false gets nothing", func(t *testing.T) {
+		var got bool
+		if runProbe(t, &progressProbeTool{name: "spawner", streams: false, got: &got}, &got, true) {
+			t.Fatal("StreamsChildProgress() == false must be honoured")
+		}
+	})
+
+	t.Run("no sink means no callback, whatever the tool declares", func(t *testing.T) {
+		var got bool
+		if runProbe(t, &progressProbeTool{name: "spawner", streams: true, got: &got}, &got, false) {
+			t.Fatal("without OnToolProgress there is nothing to forward to")
+		}
+	})
+}

diff --git a/dev/zero/internal/tui/orchestrate_panel.go b/dev/zero/internal/tui/orchestrate_panel.go
--- /dev/null
+++ b/dev/zero/internal/tui/orchestrate_panel.go
@@ @@
+package tui
+
+import (
+	"fmt"
+	"strings"
+	"time"
+)
+
+// orchestrateTaskStatus is a plan task's state in the panel.
+type orchestrateTaskStatus int
+
+const (
+	orchestratePending orchestrateTaskStatus = iota
+	orchestrateRunning
+	orchestrateDone
+	orchestrateFailed
+	orchestrateSkipped
+	orchestrateCancelled
+)
+
+func (s orchestrateTaskStatus) label() string {
+	switch s {
+	case orchestrateRunning:
+		return "running"
+	case orchestrateDone:
+		return "done"
+	case orchestrateFailed:
+		return "failed"
+	case orchestrateSkipped:
+		return "skipped"
+	case orchestrateCancelled:
+		return "cancelled"
+	default:
+		return "pending"
+	}
+}
+
+// orchestrateTask is one row of the panel.
+type orchestrateTask struct {
+	id        string
+	dependsOn []string
+	phase     string
+	status    orchestrateTaskStatus
+	summary   string
+	startedAt time.Time
+	endedAt   time.Time
+	// depth is the task's rank in the dependency graph: 0 for a task with no
+	// dependencies, otherwise one more than its deepest dependency. This is what
+	// makes a diamond LOOK like a diamond — tasks at the same depth ran from the
+	// same fan-out and are drawn on the same rung.
+	depth int
+}
+
+// elapsed is the task's duration: live while running, frozen once ended.
+func (t orchestrateTask) elapsed(now time.Time) time.Duration {
+	if t.startedAt.IsZero() {
+		return 0
+	}
+	if t.endedAt.IsZero() {
+		return now.Sub(t.startedAt)
+	}
+	return t.endedAt.Sub(t.startedAt)
+}
+
+// orchestratePanelState is the live view of one orchestrate plan.
+//
+// Distinct from planPanelState, which belongs to the update_plan tool (the
+// model's own TODO list). Two different things called "plan" is a real
+// collision risk, so this type, its command and its state are named
+// ORCHESTRATE throughout, and only the user-facing command says "plans".
+type orchestratePanelState struct {
+	name       string
+	tasks      []orchestrateTask
+	byID       map[string]int
+	status     string
+	tokensUsed int
+	tokenLimit int
+	maxSpeedup float64
+	startedAt  time.Time
+	completedAt time.Time
+	expanded   bool
+}
+
+func (s *orchestratePanelState) clear() { *s = orchestratePanelState{} }
+
+func (s orchestratePanelState) isEmpty() bool { return len(s.tasks) == 0 }
+
+func (s orchestratePanelState) isComplete() bool { return s.status != "" }
+
+// admit installs the shape. Called once per plan, before any task runs.
+func (s *orchestratePanelState) admit(msg planAdmittedMsg, now time.Time) {
+	s.clear()
+	s.name = msg.name
+	s.tokenLimit = msg.tokenLimit
+	s.startedAt = now
+	s.byID = make(map[string]int, len(msg.tasks))
+	s.tasks = make([]orchestrateTask, 0, len(msg.tasks))
+	for _, task := range msg.tasks {
+		s.byID[task.id] = len(s.tasks)
+		s.tasks = append(s.tasks, orchestrateTask{
+			id:        task.id,
+			dependsOn: task.dependsOn,
+			phase:     task.phase,
+			status:    orchestratePending,
+		})
+	}
+	s.computeDepths()
+}
+
+// computeDepths ranks tasks by dependency depth. The message carries them in
+// the validated topological order, so every dependency is already ranked when a
+// task is reached — the same property criticalPath relies on.
+func (s *orchestratePanelState) computeDepths() {
+	for index := range s.tasks {
+		depth := 0
+		for _, dep := range s.tasks[index].dependsOn {
+			position, ok := s.byID[dep]
+			if !ok || position >= index {
+				continue
+			}
+			if next := s.tasks[position].depth + 1; next > depth {
+				depth = next
+			}
+		}
+		s.tasks[index].depth = depth
+	}
+}
+
+func (s *orchestratePanelState) markStarted(taskID, summary string, now time.Time) {
+	index, ok := s.byID[taskID]
+	if !ok {
+		return
+	}
+	s.tasks[index].status = orchestrateRunning
+	s.tasks[index].summary = summary
+	s.tasks[index].startedAt = now
+}
+
+func (s *orchestratePanelState) markDone(taskID, outcome string, now time.Time) {
+	index, ok := s.byID[taskID]
+	if !ok {
+		return
+	}
+	task := &s.tasks[index]
+	task.status = orchestrateStatusFromOutcome(outcome)
+	task.endedAt = now
+	if task.startedAt.IsZero() {
+		// Never dispatched: it has no duration, and pretending otherwise would
+		// put time against work that did not happen.
+		task.startedAt = now
+	}
+}
+
+// orchestrateStatusFromOutcome maps the executor's terminal outcomes onto panel
+// statuses. The string values are specialist's TaskOutcome constants; matching
+// on them here rather than importing keeps the panel free of the executor.
+func orchestrateStatusFromOutcome(outcome string) orchestrateTaskStatus {
+	switch outcome {
+	case "succeeded":
+		return orchestrateDone
+	case "failed":
+		return orchestrateFailed
+	case "cancelled":
+		return orchestrateCancelled
+	case "dependency_failed", "budget_exhausted":
+		return orchestrateSkipped
+	default:
+		return orchestrateFailed
+	}
+}
+
+func (s *orchestratePanelState) complete(msg planCompletedMsg, now time.Time) {
+	s.status = msg.status
+	s.tokensUsed = msg.tokensUsed
+	if msg.tokenLimit > 0 {
+		s.tokenLimit = msg.tokenLimit
+	}
+	s.maxSpeedup = msg.maxSpeedup
+	s.completedAt = now
+}
+
+// visible mirrors planPanelState.visible: nothing to show when empty, and a
+// finished plan stops pinning itself after a grace period unless expanded.
+//
+// THIS IS THE MOUNT-POINT ANSWER. With no plan admitted the state is empty and
+// this returns false, so the panel contributes nothing to the view — the
+// posture-off, no-plan TUI is unchanged because the panel never renders, not
+// because it renders something empty.
+func (s orchestratePanelState) visible(now time.Time) bool {
+	if s.isEmpty() {
+		return false
+	}
+	if s.isComplete() && !s.expanded && !s.completedAt.IsZero() && now.Sub(s.completedAt) > completedHideAfter {
+		return false
+	}
+	return true
+}
+
+func (s orchestratePanelState) counts() (done, failed, skipped, cancelled, running int) {
+	for _, task := range s.tasks {
+		switch task.status {
+		case orchestrateDone:
+			done++
+		case orchestrateFailed:
+			failed++
+		case orchestrateSkipped:
+			skipped++
+		case orchestrateCancelled:
+			cancelled++
+		case orchestrateRunning:
+			running++
+		}
+	}
+	return
+}
+
+const (
+	// orchestrateMaxRows bounds what the pinned panel draws. A plan may hold up
+	// to defaultPlanMaxTasks tasks and the panel must never push the composer
+	// off screen; beyond this the panel says how many it is not showing rather
+	// than silently dropping them.
+	orchestrateMaxRows = 12
+	// orchestrateSummaryWidth bounds a task's one-line summary.
+	orchestrateSummaryWidth = 48
+	// orchestrateMinWidth is the narrowest sensible render.
+	orchestrateMinWidth = 24
+)
+
+// renderOrchestratePanel draws the plan: one row per task, indented by
+// dependency depth so the shape is legible.
+func (m model) renderOrchestratePanel(width int) string {
+	state := m.orchestrate
+	now := m.orchestrateNow()
+	if !state.visible(now) {
+		return ""
+	}
+	if width < orchestrateMinWidth {
+		width = orchestrateMinWidth
+	}
+
+	var b strings.Builder
+	b.WriteString(zeroTheme.ink.Render(orchestrateHeaderLine(state, now)))
+
+	rows := state.tasks
+	hidden := 0
+	if len(rows) > orchestrateMaxRows {
+		hidden = len(rows) - orchestrateMaxRows
+		rows = rows[:orchestrateMaxRows]
+	}
+	for _, task := range rows {
+		b.WriteString("\n")
+		b.WriteString(m.renderOrchestrateTaskLine(task, now, width))
+	}
+	if hidden > 0 {
+		b.WriteString("\n")
+		b.WriteString(zeroTheme.faint.Render(fmt.Sprintf("  … %d more task(s) not shown", hidden)))
+	}
+	if footer := orchestrateFooterLine(state); footer != "" {
+		b.WriteString("\n")
+		b.WriteString(zeroTheme.faint.Render(footer))
+	}
+	return b.String()
+}
+
+func orchestrateHeaderLine(state orchestratePanelState, now time.Time) string {
+	done, failed, skipped, cancelled, running := state.counts()
+	var b strings.Builder
+	b.WriteString("PLAN")
+	if name := strings.TrimSpace(state.name); name != "" {
+		fmt.Fprintf(&b, " %s", truncateRunes(name, 24))
+	}
+	fmt.Fprintf(&b, "  %d/%d done", done, len(state.tasks))
+	if running > 0 {
+		fmt.Fprintf(&b, " · %d running", running)
+	}
+	if failed > 0 {
+		fmt.Fprintf(&b, " · %d failed", failed)
+	}
+	if skipped > 0 {
+		fmt.Fprintf(&b, " · %d skipped", skipped)
+	}
+	if cancelled > 0 {
+		fmt.Fprintf(&b, " · %d cancelled", cancelled)
+	}
+	if !state.startedAt.IsZero() {
+		fmt.Fprintf(&b, " · %s", formatShortDuration(now.Sub(state.startedAt)))
+	}
+	return b.String()
+}
+
+func orchestrateFooterLine(state orchestratePanelState) string {
+	var parts []string
+	if state.tokenLimit > 0 {
+		parts = append(parts, fmt.Sprintf("budget %d/%d tokens", state.tokensUsed, state.tokenLimit))
+	}
+	if state.isComplete() {
+		parts = append(parts, "status "+state.status)
+		if state.maxSpeedup > 0 {
+			parts = append(parts, fmt.Sprintf("max_speedup %.2fx", state.maxSpeedup))
+		}
+	}
+	if len(parts) == 0 {
+		return ""
+	}
+	return "  " + strings.Join(parts, " · ")
+}
+
+func (m model) renderOrchestrateTaskLine(task orchestrateTask, now time.Time, width int) string {
+	// Indent by dependency depth: tasks that fan out from the same parent share
+	// a rung, so a diamond reads as one node, two beside each other, one node.
+	indent := strings.Repeat("  ", task.depth+1)
+
+	glyph := orchestrateGlyph(task.status)
+	if task.status == orchestrateRunning {
+		glyph = zeroTheme.accent.Render(m.spinnerGlyph())
+	}
+
+	head := fmt.Sprintf("%s%s %s", indent, glyph, truncateRunes(task.id, 24))
+	meta := task.status.label()
+	if elapsed := task.elapsed(now); elapsed > 0 {
+		meta += " " + formatShortDuration(elapsed)
+	}
+
+	// The summary is what is left after the fixed parts, and it is a SUMMARY:
+	// the task's full result stays in the tool output. A display formatter on
+	// the data path is how a 583-rune work product became 200 mangled runes.
+	remaining := width - len([]rune(head)) - len([]rune(meta)) - 3
+	line := head + " " + zeroTheme.faint.Render(meta)
+	if remaining > 8 && strings.TrimSpace(task.summary) != "" {
+		limit := remaining
+		if limit > orchestrateSummaryWidth {
+			limit = orchestrateSummaryWidth
+		}
+		line += " " + zeroTheme.faint.Render(truncateRunes(task.summary, limit))
+	}
+	return line
+}
+
+func orchestrateGlyph(status orchestrateTaskStatus) string {
+	switch status {
+	case orchestrateDone:
+		return zeroTheme.green.Render("✓")
+	case orchestrateFailed:
+		return zeroTheme.red.Render("✗")
+	case orchestrateSkipped, orchestrateCancelled:
+		// Neutral: a skipped or stopped task is not a defect.
+		return zeroTheme.faint.Render("⊘")
+	default:
+		return zeroTheme.faint.Render("·")
+	}
+}
+
+// orchestrateNow freezes the plan clock while no run is in flight, mirroring
+// planNow — a task left mid-flight when the agent yields must stop ticking up
+// against a turn that is no longer running.
+func (m model) orchestrateNow() time.Time {
+	if m.activeRunID == 0 && !m.orchestrate.completedAt.IsZero() {
+		return m.orchestrate.completedAt
+	}
+	return m.now()
+}
diff --git a/dev/zero/internal/tui/orchestrate_panel_test.go b/dev/zero/internal/tui/orchestrate_panel_test.go
--- /dev/null
+++ b/dev/zero/internal/tui/orchestrate_panel_test.go
@@ @@
+package tui
+
+import (
+	"strings"
+	"testing"
+	"time"
+)
+
+// diamondAdmitted is the plan the whole feature is measured against: a -> (b,c)
+// -> d. It has to LOOK like a diamond, not like a flat list.
+func diamondAdmitted() planAdmittedMsg {
+	return planAdmittedMsg{
+		runID:      1,
+		name:       "diamond",
+		taskCount:  4,
+		tokenLimit: 100000,
+		tasks: []planGraphTask{
+			{id: "a"},
+			{id: "b", dependsOn: []string{"a"}},
+			{id: "c", dependsOn: []string{"a"}},
+			{id: "d", dependsOn: []string{"b", "c"}},
+		},
+	}
+}
+
+func admittedModel(t *testing.T, msg planAdmittedMsg) model {
+	t.Helper()
+	m := model{now: func() time.Time { return time.Unix(1000, 0) }}
+	m.orchestrate.admit(msg, m.now())
+	return m
+}
+
+// THE POINT OF THE PANEL. A dependency graph rendered as a flat list is just
+// the cards again; the shape is the thing cards cannot show.
+func TestDiamondRendersAsADiamond(t *testing.T) {
+	m := admittedModel(t, diamondAdmitted())
+
+	depth := map[string]int{}
+	for _, task := range m.orchestrate.tasks {
+		depth[task.id] = task.depth
+	}
+	if depth["a"] != 0 {
+		t.Fatalf("the root must sit at depth 0, got %d", depth["a"])
+	}
+	if depth["b"] != 1 || depth["c"] != 1 {
+		t.Fatalf("b and c fan out from the same parent and must share a rung: b=%d c=%d", depth["b"], depth["c"])
+	}
+	if depth["d"] != 2 {
+		t.Fatalf("the join must sit below both branches, got %d", depth["d"])
+	}
+
+	rendered := m.renderOrchestratePanel(100)
+	indent := func(id string) int {
+		for _, line := range strings.Split(rendered, "\n") {
+			if strings.Contains(line, " "+id+" ") {
+				return len(line) - len(strings.TrimLeft(line, " "))
+			}
+		}
+		t.Fatalf("task %q missing from the panel:\n%s", id, rendered)
+		return -1
+	}
+	if indent("b") != indent("c") {
+		t.Fatalf("b and c must be drawn on the same rung:\n%s", rendered)
+	}
+	if indent("a") >= indent("b") || indent("d") <= indent("a") {
+		t.Fatalf("the diamond is drawn flat:\n%s", rendered)
+	}
+}
+
+// A chain is not a diamond: each task must step in one further, or the panel
+// draws every shape the same way.
+func TestAChainStepsInOncePerLink(t *testing.T) {
+	m := admittedModel(t, planAdmittedMsg{
+		runID: 1, name: "chain", taskCount: 3,
+		tasks: []planGraphTask{
+			{id: "a"},
+			{id: "b", dependsOn: []string{"a"}},
+			{id: "c", dependsOn: []string{"b"}},
+		},
+	})
+	got := []int{}
+	for _, task := range m.orchestrate.tasks {
+		got = append(got, task.depth)
+	}
+	if len(got) != 3 || got[0] != 0 || got[1] != 1 || got[2] != 2 {
+		t.Fatalf("chain depths = %v, want 0,1,2", got)
+	}
+}
+
+// Independent tasks all sit on the same rung — a fan-out reads as a fan-out.
+func TestIndependentTasksShareOneRung(t *testing.T) {
+	m := admittedModel(t, planAdmittedMsg{
+		runID: 1, name: "fan", taskCount: 3,
+		tasks: []planGraphTask{{id: "a"}, {id: "b"}, {id: "c"}},
+	})
+	for _, task := range m.orchestrate.tasks {
+		if task.depth != 0 {
+			t.Fatalf("task %q has no dependencies but sits at depth %d", task.id, task.depth)
+		}
+	}
+}
+
+// THE MOUNT-POINT INVARIANT. With no plan the panel contributes nothing —
+// not an empty box, not a blank line. That is what keeps a posture-off session
+// unchanged.
+func TestPanelRendersNothingWithoutAPlan(t *testing.T) {
+	m := model{now: func() time.Time { return time.Unix(1000, 0) }}
+	if got := m.renderOrchestratePanel(100); got != "" {
+		t.Fatalf("with no plan the panel must render nothing, got %q", got)
+	}
+	if m.orchestrate.visible(m.now()) {
+		t.Fatal("an empty plan must not be visible")
+	}
+}
+
+// A finished plan stops pinning itself, matching the update_plan panel, so a
+// completed plan does not occupy the footer forever.
+func TestCompletedPlanStopsPinningItself(t *testing.T) {
+	m := admittedModel(t, diamondAdmitted())
+	m.orchestrate.complete(planCompletedMsg{status: "completed", maxSpeedup: 1.33}, m.now())
+
+	if !m.orchestrate.visible(m.now()) {
+		t.Fatal("a just-completed plan should still be visible")
+	}
+	later := m.now().Add(completedHideAfter + time.Second)
+	if m.orchestrate.visible(later) {
+		t.Fatal("a long-finished plan must stop pinning itself")
+	}
+	m.orchestrate.expanded = true
+	if !m.orchestrate.visible(later) {
+		t.Fatal("an expanded plan stays visible however long ago it finished")
+	}
+}
+
+// Status transitions must survive to the panel, and a skipped or cancelled task
+// must not be shown as a failure.
+func TestPanelTracksEveryOutcome(t *testing.T) {
+	m := admittedModel(t, diamondAdmitted())
+	now := m.now()
+
+	m.orchestrate.markStarted("a", "root", now)
+	m.orchestrate.markDone("a", "succeeded", now.Add(time.Second))
+	m.orchestrate.markStarted("b", "left", now.Add(time.Second))
+	m.orchestrate.markDone("b", "failed", now.Add(2*time.Second))
+	m.orchestrate.markDone("c", "cancelled", now.Add(2*time.Second))
+	m.orchestrate.markDone("d", "dependency_failed", now.Add(2*time.Second))
+
+	want := map[string]orchestrateTaskStatus{
+		"a": orchestrateDone, "b": orchestrateFailed,
+		"c": orchestrateCancelled, "d": orchestrateSkipped,
+	}
+	for _, task := range m.orchestrate.tasks {
+		if task.status != want[task.id] {
+			t.Errorf("task %q status = %v, want %v", task.id, task.status, want[task.id])
+		}
+	}
+	done, failed, skipped, cancelled, running := m.orchestrate.counts()
+	if done != 1 || failed != 1 || skipped != 1 || cancelled != 1 || running != 0 {
+		t.Fatalf("counts = done %d failed %d skipped %d cancelled %d running %d", done, failed, skipped, cancelled, running)
+	}
+}
+
+// A cancelled plan must not read as a wall of failures — the whole reason
+// TaskCancelled exists.
+func TestCancelledPlanIsNotShownAsFailures(t *testing.T) {
+	m := admittedModel(t, diamondAdmitted())
+	now := m.now()
+	m.orchestrate.markStarted("a", "root", now)
+	m.orchestrate.markDone("a", "succeeded", now)
+	for _, id := range []string{"b", "c", "d"} {
+		m.orchestrate.markDone(id, "cancelled", now)
+	}
+	m.orchestrate.complete(planCompletedMsg{status: "partial", succeeded: 1, cancelled: 3}, now)
+
+	_, failed, _, cancelled, _ := m.orchestrate.counts()
+	if failed != 0 {
+		t.Fatalf("a cancelled plan reported %d failures", failed)
+	}
+	if cancelled != 3 {
+		t.Fatalf("cancelled = %d, want 3", cancelled)
+	}
+	rendered := m.renderOrchestratePanel(100)
+	if strings.Contains(rendered, "failed") {
+		t.Fatalf("the panel calls a cancelled plan failed:\n%s", rendered)
+	}
+	if !strings.Contains(rendered, "cancelled") {
+		t.Fatalf("the panel must say what actually happened:\n%s", rendered)
+	}
+}
+
+// A plan at the task cap must not push the composer off screen, and what it
+// leaves out has to be stated — a silently truncated list reads as a complete
+// one.
+func TestALargePlanIsBoundedAndSaysWhatItHid(t *testing.T) {
+	msg := planAdmittedMsg{runID: 1, name: "big", taskCount: 20}
+	for index := 0; index < 20; index++ {
+		msg.tasks = append(msg.tasks, planGraphTask{id: string(rune('a' + index))})
+	}
+	msg.taskCount = len(msg.tasks)
+	m := admittedModel(t, msg)
+
+	rendered := m.renderOrchestratePanel(100)
+	lines := strings.Count(rendered, "\n") + 1
+	if lines > orchestrateMaxRows+3 {
+		t.Fatalf("the panel drew %d lines for a 20-task plan; it must stay bounded", lines)
+	}
+	if !strings.Contains(rendered, "more task(s) not shown") {
+		t.Fatalf("a truncated panel must say so:\n%s", rendered)
+	}
+	// /plans is where the whole plan can still be read.
+	full := m.orchestratePlansText()
+	for _, task := range msg.tasks {
+		if !strings.Contains(full, task.id) {
+			t.Fatalf("/plans omitted task %q; it is the surface that shows everything", task.id)
+		}
+	}
+}
+
+// Narrow terminals must not panic or produce garbage.
+func TestPanelSurvivesNarrowWidths(t *testing.T) {
+	m := admittedModel(t, diamondAdmitted())
+	m.orchestrate.markStarted("a", strings.Repeat("verbose ", 40), m.now())
+	for _, width := range []int{0, 1, 10, 24, 40, 200} {
+		rendered := m.renderOrchestratePanel(width)
+		if rendered == "" {
+			t.Fatalf("width %d rendered nothing for a live plan", width)
+		}
+		for _, r := range rendered {
+			if r == '�' {
+				t.Fatalf("width %d cut mid-rune:\n%s", width, rendered)
+			}
+		}
+	}
+}
+
+// A task with no output must still render — the panel shows status, not results.
+func TestATaskWithNoSummaryStillRenders(t *testing.T) {
+	m := admittedModel(t, diamondAdmitted())
+	m.orchestrate.markStarted("a", "", m.now())
+	rendered := m.renderOrchestratePanel(100)
+	if !strings.Contains(rendered, " a ") {
+		t.Fatalf("a task with no summary vanished from the panel:\n%s", rendered)
+	}
+}
+
+// The panel SUMMARISES. The full result stays in the tool output; a display
+// formatter on the data path is how a 583-rune work product became 200 mangled
+// runes.
+func TestPanelTruncatesSummariesOnRuneBoundaries(t *testing.T) {
+	m := admittedModel(t, diamondAdmitted())
+	m.orchestrate.markStarted("a", strings.Repeat("日", 300), m.now())
+	rendered := m.renderOrchestratePanel(100)
+	for _, line := range strings.Split(rendered, "\n") {
+		if len([]rune(line)) > 140 {
+			t.Fatalf("a panel line ran to %d runes:\n%s", len([]rune(line)), line)
+		}
+	}
+	if strings.Contains(rendered, "�") {
+		t.Fatalf("summary was cut mid-rune:\n%s", rendered)
+	}
+}
+
+// /plans answers even with no plan, and never claims one ran.
+func TestPlansCommandWithNoPlan(t *testing.T) {
+	m := model{now: func() time.Time { return time.Unix(1000, 0) }}
+	text := m.orchestratePlansText()
+	if !strings.Contains(text, "No plan has run") {
+		t.Fatalf("/plans must say plainly that nothing ran: %q", text)
+	}
+}
+
+// /plans shows the dependency edges explicitly, so the shape survives even
+// where indentation does not (copied text, narrow terminals, screen readers).
+func TestPlansCommandNamesTheEdges(t *testing.T) {
+	m := admittedModel(t, diamondAdmitted())
+	text := m.orchestratePlansText()
+	if !strings.Contains(text, "d [pending] ← b, c") {
+		t.Fatalf("/plans must name each task's dependencies:\n%s", text)
+	}
