+	m.specialists.start("b", "read the left branch", "plantask_2", now)
+	m.specialists.incrementToolCount("plantask_2")
+	m.specialists.setCurrentTool("plantask_2", "read_file", "internal/agent/loop.go")
+	m.orchestrate.linkCard("b", "plantask_2")
+	return m
+}
+
+// THE MOUNT-POINT INVARIANT. Closed, and with no plan at all, the view
+// contributes nothing — which is what keeps a posture-off session unchanged.
+func TestTheDetailViewRendersNothingWhenClosed(t *testing.T) {
+	m := detailModel(t)
+	if got := m.renderOrchestrateDetailOverlay(120); got != "" {
+		t.Fatalf("a closed view must render nothing, got %q", got)
+	}
+
+	empty := model{now: func() time.Time { return time.Unix(1000, 0) }}
+	empty.orchestrateDetail = true
+	if got := empty.renderOrchestrateDetailOverlay(120); got != "" {
+		t.Fatalf("with no plan there is nothing to open, got %q", got)
+	}
+}
+
+// Opening lands on the task worth looking at: the one running.
+func TestOpeningSelectsTheRunningTask(t *testing.T) {
+	m := detailModel(t).openOrchestrateDetail()
+	if !m.orchestrateDetailOpen() {
+		t.Fatal("the view did not open")
+	}
+	if got := m.orchestrate.tasks[m.orchestrateSelected].id; got != "b" {
+		t.Fatalf("selected %q, want the running task", got)
+	}
+}
+
+// ...and on the first failure when nothing is running, since that is what a
+// user opens the view to read.
+func TestOpeningSelectsTheFirstFailureWhenIdle(t *testing.T) {
+	m := admittedModel(t, diamondAdmitted())
+	now := m.now()
+	m.orchestrate.markStarted("a", "root", "k1", now)
+	m.orchestrate.markDone("a", "succeeded", 0, now)
+	m.orchestrate.markStarted("b", "left", "k2", now)
+	m.orchestrate.markDone("b", "failed", 0, now)
+
+	m = m.openOrchestrateDetail()
+	if got := m.orchestrate.tasks[m.orchestrateSelected].id; got != "b" {
+		t.Fatalf("selected %q, want the failed task", got)
+	}
+}
+
+// Both panes render: the phase list on the left, the selected task's live
+// detail on the right.
+func TestTheViewShowsPhasesAndTheSelectedTasksDetail(t *testing.T) {
+	m := detailModel(t).openOrchestrateDetail()
+	rendered := ansi.Strip(m.renderOrchestrateDetailOverlay(120))
+
+	if !strings.Contains(rendered, "diamond") {
+		t.Fatalf("the plan's name is missing:\n%s", rendered)
+	}
+	for _, id := range []string{"a", "b", "c", "d"} {
+		if !strings.Contains(rendered, id) {
+			t.Fatalf("phase %q missing from the list:\n%s", id, rendered)
+		}
+	}
+	// The running task's live agent state.
+	for _, want := range []string{"Prompt", "read the left branch", "Activity", "read_file", "Outcome", "still running"} {
+		if !strings.Contains(rendered, want) {
+			t.Errorf("the detail pane does not show %q:\n%s", want, rendered)
+		}
+	}
+	if !strings.Contains(rendered, "1 tool calls") {
+		t.Errorf("the detail pane does not show the live tool count:\n%s", rendered)
+	}
+}
+
+// Moving the selection changes what the right pane shows — the whole point of
+// the two panes.
+func TestMovingTheSelectionChangesTheDetail(t *testing.T) {
+	m := detailModel(t).openOrchestrateDetail()
+	before := ansi.Strip(m.renderOrchestrateDetailOverlay(120))
+
+	m = m.moveOrchestrateSelection(-1)
+	after := ansi.Strip(m.renderOrchestrateDetailOverlay(120))
+	if before == after {
+		t.Fatal("moving the selection did not change the detail pane")
+	}
+	if !strings.Contains(after, "survey the packages") {
+		t.Fatalf("the pane does not show the newly selected task:\n%s", after)
+	}
+	if !strings.Contains(after, "16,470 tokens") && !strings.Contains(after, "16470 tokens") {
+		t.Fatalf("the pane does not show the selected task's spend:\n%s", after)
+	}
+}
+
+// The selection clamps at both ends rather than wrapping onto an unrelated
+// task.
+func TestTheSelectionClampsAtBothEnds(t *testing.T) {
+	m := detailModel(t).openOrchestrateDetail()
+	for range 10 {
+		m = m.moveOrchestrateSelection(-1)
+	}
+	if m.orchestrateSelected != 0 {
+		t.Fatalf("selection = %d, want it clamped at the first task", m.orchestrateSelected)
+	}
+	for range 20 {
+		m = m.moveOrchestrateSelection(1)
+	}
+	if want := len(m.orchestrate.tasks) - 1; m.orchestrateSelected != want {
+		t.Fatalf("selection = %d, want it clamped at %d", m.orchestrateSelected, want)
+	}
+}
+
+// Esc closes it and the arrows move within it, through the real key handler —
+// a keypress meant for the view must never fall through to the transcript.
+func TestTheViewOwnsItsKeysWhileOpen(t *testing.T) {
+	m := detailModel(t).openOrchestrateDetail()
+	m.width, m.height = 120, 40
+
+	press := func(m model, key tea.KeyMsg) model {
+		t.Helper()
+		updated, _ := m.Update(key)
+		return updated.(model)
+	}
+
+	selected := m.orchestrateSelected
+	m = press(m, tea.KeyPressMsg{Code: tea.KeyUp})
+	if m.orchestrateSelected == selected {
+		t.Fatal("up did not move the selection")
+	}
+	m = press(m, tea.KeyPressMsg{Code: tea.KeyDown})
+	if m.orchestrateSelected != selected {
+		t.Fatal("down did not move the selection back")
+	}
+	m = press(m, tea.KeyPressMsg{Code: tea.KeyEscape})
+	if m.orchestrateDetailOpen() {
+		t.Fatal("esc did not close the view")
+	}
+}
+
+// A task that never started has no agent card, so the pane says what it knows
+// rather than showing a row of zeroes.
+func TestAPendingTaskShowsWhatItIsWaitingOn(t *testing.T) {
+	m := detailModel(t).openOrchestrateDetail()
+	for m.orchestrate.tasks[m.orchestrateSelected].id != "d" {
+		m = m.moveOrchestrateSelection(1)
+	}
+	rendered := ansi.Strip(m.renderOrchestrateDetailOverlay(120))
+	if !strings.Contains(rendered, "waiting on b, c") {
+		t.Fatalf("a pending task must say what it is waiting on:\n%s", rendered)
+	}
+	if strings.Contains(rendered, "0 tool calls") {
+		t.Fatalf("a task that never started has no tool count to report:\n%s", rendered)
+	}
+}
+
+// Narrow terminals drop the phase list rather than crushing both columns, and
+// never cut mid-rune.
+func TestTheViewSurvivesNarrowWidths(t *testing.T) {
+	m := detailModel(t).openOrchestrateDetail()
+	for _, width := range []int{20, 40, 55, 56, 80, 200} {
+		rendered := m.renderOrchestrateDetailOverlay(width)
+		if rendered == "" {
+			t.Fatalf("width %d rendered nothing", width)
+		}
+		if strings.Contains(rendered, "\ufffd") {
+			t.Fatalf("width %d cut mid-rune:\n%s", width, rendered)
+		}
+	}
+}
+
+// A long prompt is summarised and says it was cut. The full text stays in the
+// tool output — a display surface is never the data path.
+func TestALongPromptIsTruncatedAndSaysSo(t *testing.T) {
+	m := admittedModel(t, diamondAdmitted())
+	m.orchestrate.markStarted("a", strings.Repeat("verbose ", 200), "k", m.now())
+	m = m.openOrchestrateDetail()
+
+	rendered := ansi.Strip(m.renderOrchestrateDetailOverlay(100))
+	if !strings.Contains(rendered, "…") {
+		t.Fatalf("a truncated prompt must say so:\n%s", rendered)
+	}
+	if strings.Count(rendered, "verbose") > 60 {
+		t.Fatalf("the prompt was dumped rather than summarised:\n%s", rendered)
+	}
+}

diff --git a/dev/zero/internal/tui/sidebar_plan_detail.go b/dev/zero/internal/tui/sidebar_plan_detail.go
--- /dev/null
+++ b/dev/zero/internal/tui/sidebar_plan_detail.go
@@ @@
+package tui
+
+import (
+	"fmt"
+	"strings"
+
+	tea "charm.land/bubbletea/v2"
+)
+
+// The plan's detail lives in the SIDEBAR, in the space below ACTIVITY that was
+// otherwise padded with blank lines to the token floor.
+//
+// It was an overlay over the chat, and that was wrong: an overlay composited
+// into the transcript column collided with the conversation mid-render, so a
+// twelve-task plan drew its phase list straight through the user's own prompt.
+// The right column already owns "what is happening" — agents, files, activity —
+// and had half a screen of dead space under it.
+//
+// Clicking a task row selects it; clicking the PLAN header collapses the whole
+// section. Both are reachable by keyboard too, since the sidebar is not
+// focusable and a mouse-only affordance is not an affordance.
+
+// orchestrateTaskHit is one clickable plan row in the sidebar.
+type orchestrateTaskHit struct {
+	lineOffset int
+	taskIndex  int
+}
+
+// sidebarOrchestrateSelectables returns the clickable plan rows with their line
+// offsets, mirroring sidebarPlanSelectables' accounting exactly: AGENTS header +
+// body, then a blank line and the PLAN header, then one line per rendered task.
+//
+// Derived from the SAME slice the renderer draws, so a row the renderer dropped
+// (the live-task filter, the six-line cap) is never clickable — an offset table
+// built from the full task list would map clicks onto rows that are not there.
+func (m model) sidebarOrchestrateSelectables(width int) []orchestrateTaskHit {
+	if m.orchestrate.isEmpty() || !m.plan.isEmpty() {
+		// update_plan's steps own the section when it has any, and they have
+		// their own hit table.
+		return nil
+	}
+	agentBody := len(m.sidebarAgentLines(width))
+	if agentBody == 0 {
+		agentBody = 1
+	}
+	base := 1 + agentBody + 2
+
+	rows := m.sidebarOrchestrateRows()
+	hits := make([]orchestrateTaskHit, 0, len(rows))
+	for offset, index := range rows {
+		hits = append(hits, orchestrateTaskHit{lineOffset: base + offset, taskIndex: index})
+	}
+	return hits
+}
+
+// sidebarOrchestrateRows returns the task INDICES the sidebar draws, in order.
+// One source for the renderer and the hit table, so they cannot disagree about
+// which row is which.
+func (m model) sidebarOrchestrateRows() []int {
+	state := m.orchestrate
+	if state.isEmpty() || state.sidebarCollapsed {
+		return nil
+	}
+	live := state.liveTasks(m.orchestrateNow())
+	if len(live) == 0 {
+		live = state.tasks
+		if len(live) > maxSidebarOrchestrateLines {
+			live = live[len(live)-maxSidebarOrchestrateLines:]
+		}
+	}
+	if len(live) > maxSidebarOrchestrateLines {
+		live = live[:maxSidebarOrchestrateLines]
+	}
+	rows := make([]int, 0, len(live))
+	for _, task := range live {
+		if index, ok := state.byID[task.id]; ok {
+			rows = append(rows, index)
+		}
+	}
+	return rows
+}
+
+// orchestrateTaskAtMouse maps a left-click in the sidebar to a plan task,
+// mirroring planStepAtMouse's column and x gate.
+func (m model) orchestrateTaskAtMouse(msg tea.MouseMsg) (int, bool) {
+	if !m.sidebarActive() || m.orchestrate.isEmpty() {
+		return 0, false
+	}
+	if m.setup.visible || m.providerWizard != nil || m.mcpAddWizard != nil ||
+		m.mcpManager != nil || m.picker != nil || m.suggestionsActive() {
+		return 0, false
+	}
+	sidebarW := sidebarWidth(m.width)
+	if sidebarW <= 0 {
+		return 0, false
+	}
+	x0 := m.chatColumnWidth() + 3 // " │ " divider between the columns
+	x, y := mouseX(msg), mouseY(msg)
+	if x < x0 || x >= x0+sidebarW {
+		return 0, false
+	}
+	for _, hit := range m.sidebarOrchestrateSelectables(sidebarW) {
+		if hit.lineOffset == y {
+			return hit.taskIndex, true
+		}
+	}
+	return 0, false
+}
+
+// orchestrateHeaderAtMouse reports a click on the sidebar's PLAN header, which
+// collapses and expands the whole section.
+func (m model) orchestrateHeaderAtMouse(msg tea.MouseMsg) bool {
+	if !m.sidebarActive() || m.orchestrate.isEmpty() || !m.plan.isEmpty() {
+		return false
+	}
+	sidebarW := sidebarWidth(m.width)
+	if sidebarW <= 0 {
+		return false
+	}
+	x0 := m.chatColumnWidth() + 3
+	x, y := mouseX(msg), mouseY(msg)
+	if x < x0 || x >= x0+sidebarW {
+		return false
+	}
+	agentBody := len(m.sidebarAgentLines(sidebarW))
+	if agentBody == 0 {
+		agentBody = 1
+	}
+	// AGENTS header + body + blank line, then the PLAN header.
+	return y == 1+agentBody+1
+}
+
+// sidebarPlanDetailLines renders the selected task into the space left between
+// ACTIVITY and the token floor. Returns nothing when there is no room — the
+// detail is the first thing to give way, since the task list above it is what
+// the section is for.
+func (m model) sidebarPlanDetailLines(width, budget int) []string {
+	state := m.orchestrate
+	if state.isEmpty() || state.sidebarCollapsed || budget < 4 {
+		return nil
+	}
+	if m.orchestrateSelected < 0 || m.orchestrateSelected >= len(state.tasks) {
+		return nil
+	}
+	task := state.tasks[m.orchestrateSelected]
+	now := m.orchestrateNow()
+	room := maxInt(6, width-3)
+
+	lines := []string{
+		"",
+		sidebarHeaderWithCount("TASK", task.id, orchestrateStatusStyle(task.status), width),
+	}
+
+	head := task.status.label()
+	if elapsed := task.elapsed(now); elapsed > 0 {
+		head += " · " + formatElapsedSeconds(elapsed)
+	}
+	lines = append(lines, " "+zeroTheme.muted.Render(truncateStep(head, room)))
+
+	info, hasCard := m.specialists.getBySessionID(task.cardKey)
+	if hasCard {
+		meta := fmt.Sprintf("%d tool calls", info.toolCount)
+		if info.toolCount == 1 {
+			meta = "1 tool call"
+		}
+		if info.tokenCount > 0 {
+			meta += " · " + formatTokenCount(info.tokenCount) + " tok"
+		}
+		lines = append(lines, " "+zeroTheme.faint.Render(truncateStep(meta, room)))
+	}
+
+	if len(task.dependsOn) > 0 {
+		lines = append(lines, " "+zeroTheme.faint.Render(truncateStep("after "+strings.Join(task.dependsOn, ", "), room)))
+	}
+
+	// What it is doing right now, or where it ended up. One or the other — the
+	// column has no room for both, and a running task's activity is the more
+	// useful of the two.
+	if hasCard && strings.TrimSpace(info.currentTool) != "" && task.status == orchestrateRunning {
+		activity := info.currentTool
+		if detail := strings.TrimSpace(info.currentDetail); detail != "" {
+			activity += " " + detail
+		}
+		lines = append(lines, " "+zeroTheme.accent.Render("↳ ")+zeroTheme.faint.Render(truncateStep(activity, room-2)))
+	} else if outcome := m.orchestrateOutcomeLine(task, hasCard, info); outcome != "" {
+		lines = append(lines, " "+zeroTheme.faint.Render(truncateStep(outcome, room)))
+	}
+
+	// The prompt last: it is the least urgent and the first thing worth losing
+	// when the column is short.
+	if summary := strings.TrimSpace(task.summary); summary != "" && len(lines) < budget {
+		lines = append(lines, " "+zeroTheme.faint.Render(truncateStep(summary, room)))
+	}
+
+	if len(lines) > budget {
+		lines = lines[:budget]
+	}
+	return lines
+}
+
+// orchestrateStatusStyle is the header colour for a task's state, matching the
+// glyph palette the task list uses.
+func orchestrateStatusStyle(status orchestrateTaskStatus) lipglossStyle {
+	switch status {
+	case orchestrateDone:
+		return zeroTheme.green
+	case orchestrateFailed:
+		return zeroTheme.red
+	case orchestrateRunning:
+		return zeroTheme.accent
+	default:
+		return zeroTheme.faint
+	}
+}

diff --git a/dev/zero/internal/tui/permission_detail.go b/dev/zero/internal/tui/permission_detail.go
--- /dev/null
+++ b/dev/zero/internal/tui/permission_detail.go
@@ @@
+package tui
+
+import (
+	"fmt"
+	"sort"
+	"strings"
+
+	"github.com/Gitlawb/zero/internal/agent"
+)
+
+// What a permission prompt SHOWS about the thing it is approving.
+//
+// PermissionRequest has carried an Args map since it was written and no renderer
+// has ever read it — verified across permission_prompt.go, transcript.go and
+// rendering.go. So the card can name a tool and state a static reason, and
+// nothing more. That is survivable for a one-file write, where the path is
+// already surfaced as the grant scope, and it is not survivable for a plan: a
+// twenty-task plan and a one-task plan produce the identical card.
+//
+// This is STEP 1 OF THREE. On its own it renders a plan into a decision surface
+// that does not yet gate plans — orchestrate returns PermissionAllow, because
+// today its tasks are read-only and a prompt that adds friction without adding
+// safety trains click-through. Step 2 is worktree isolation; step 3 flips plan
+// tasks to allow write tools with both as preconditions. The order is forced:
+// an approval gate that cannot show the plan is the thing plan_tool.go argues
+// against, so the renderer has to exist before the gate can be justified.
+//
+// UNTRUSTED INPUT. Every value here came from the model. It is truncated on
+// RUNE boundaries, stripped of anything that could move the cursor, and bounded
+// in row count — a card that a plan can make taller than the terminal is a card
+// an attacker can use to push the options off screen.
+
+// permissionDetailRenderer turns a tool's arguments into card lines.
+type permissionDetailRenderer func(args map[string]any, width int) []string
+
+// permissionDetailRenderers is keyed by tool name. A tool with no entry renders
+// EXACTLY as before — that is what keeps every existing prompt byte-identical,
+// and it is asserted rather than assumed.
+var permissionDetailRenderers = map[string]permissionDetailRenderer{
+	"orchestrate": planPermissionDetail,
+}
+
+// permissionDetailLines returns the tool-specific detail for a request, or
+// nothing when the tool has no renderer.
+func permissionDetailLines(request agent.PermissionRequest, width int) []string {
+	render := permissionDetailRenderers[strings.TrimSpace(request.ToolName)]
+	if render == nil || len(request.Args) == 0 {
+		return nil
+	}
+	return render(request.Args, width)
+}
+
+// permissionDetailMaxRows bounds the detail. The options must stay on screen:
+// a prompt whose choices have been pushed past the bottom is a prompt that can
+// only be answered by the one key still visible.
+const permissionDetailMaxRows = 12
+
+// planPermissionDetail renders an orchestrate plan: what it will run, in what
+// order, and what it may spend.
+func planPermissionDetail(args map[string]any, width int) []string {
+	room := maxInt(16, width-4)
+
+	if saved := permissionString(args, "saved"); saved != "" {
+		// A saved plan's tasks are on disk, not in the arguments — there is
+		// nothing here to render, and inventing a summary would describe a plan
+		// this card never saw.
+		return []string{
+			"  " + zeroTheme.muted.Render(truncateRunes("saved plan: "+saved, room)),
+			"  " + zeroTheme.faint.Render(truncateRunes("run /plans show "+saved+" to read it", room)),
+		}
+	}
+
+	rawTasks, _ := args["tasks"].([]any)
+	lines := []string{}
+
+	head := fmt.Sprintf("%d task(s)", len(rawTasks))
+	if name := permissionString(args, "name"); name != "" {
+		head = name + " · " + head
+	}
+	if budget := planBudgetSummary(args); budget != "" {
+		head += " · " + budget
+	}
+	lines = append(lines, "  "+zeroTheme.ink.Render(truncateRunes(head, room)))
+
+	if description := permissionString(args, "description"); description != "" {
+		lines = append(lines, "  "+zeroTheme.muted.Render(truncateRunes(description, room)))
+	}
+
+	shown := 0
+	for _, raw := range rawTasks {
+		if shown >= permissionDetailMaxRows {
+			break
+		}
+		task, ok := raw.(map[string]any)
+		if !ok {
+			// A malformed entry is SHOWN as malformed, not skipped. A task the
+			// card silently drops is a task the user approved without seeing.
+			lines = append(lines, "  "+zeroTheme.faint.Render("· (unreadable task entry)"))
+			shown++
+			continue
+		}
+		lines = append(lines, "  "+zeroTheme.faint.Render(truncateRunes(planTaskDetailLine(task), room)))
+		shown++
+	}
+	if hidden := len(rawTasks) - shown; hidden > 0 {
+		lines = append(lines, "  "+zeroTheme.faint.Render(fmt.Sprintf("… and %d more not shown", hidden)))
+	}
+	return lines
+}
+
+// planTaskDetailLine renders one task: its id, what it waits on, and the first
+// line of its prompt.
+func planTaskDetailLine(task map[string]any) string {
+	id := permissionString(task, "id")
+	if id == "" {
+		id = "(no id)"
+	}
+	line := "· " + id
+	if deps := permissionStrings(task, "depends_on"); len(deps) > 0 {
+		sort.Strings(deps)
+		line += " after " + strings.Join(deps, ",")
+	}
+	// The task's TOOLS are shown when it names any, because "which tools" is
+	// half of what an approval is deciding.
+	if granted := permissionStrings(task, "tools"); len(granted) > 0 {
+		sort.Strings(granted)
+		line += " [" + strings.Join(granted, " ") + "]"
+	}
+	if prompt := permissionString(task, "prompt"); prompt != "" {
+		line += " — " + prompt
+	}
+	return line
+}
+
+// planBudgetSummary renders the bounds a plan asked for, naming the unbounded
+// case rather than omitting it: "no token limit" is the thing worth seeing.
+func planBudgetSummary(args map[string]any) string {
+	budget, ok := args["budget"].(map[string]any)
+	if !ok {
+		return ""
+	}
+	parts := []string{}
+	if tokens := permissionInt(budget, "max_tokens"); tokens > 0 {
+		parts = append(parts, fmt.Sprintf("%d tokens", tokens))
+	} else {
+		parts = append(parts, "no token limit")
+	}
+	if wall := permissionInt(budget, "max_wall_seconds"); wall > 0 {
+		parts = append(parts, fmt.Sprintf("%ds wall", wall))
+	}
+	if background, _ := budget["background"].(bool); background {
+		parts = append(parts, "background")
+	}
+	return strings.Join(parts, ", ")
+}
+
+// permissionString reads a string argument and makes it SAFE TO DRAW: one line,
+// no control characters, no escape sequences. The value came from the model, and
+// a card is a place where a stray \r or an ANSI reset rewrites the screen around
+// it.
+func permissionString(args map[string]any, key string) string {
+	raw, _ := args[key].(string)
+	return sanitizeCardText(raw)
+}
+
+// sanitizeCardText collapses a value to a single printable line.
+func sanitizeCardText(raw string) string {
+	if raw == "" {
+		return ""
+	}
+	if index := strings.IndexAny(raw, "\r\n"); index >= 0 {
+		raw = raw[:index]
+	}
+	var out strings.Builder
+	for _, r := range raw {
+		switch {
+		case r == '\t':
+			out.WriteRune(' ')
+		case r < 0x20 || r == 0x7f:
+			// Control characters, including ESC — the one that starts an ANSI
+			// sequence. Dropped rather than escaped: nothing here needs them.
+			continue
+		default:
+			out.WriteRune(r)
+		}
+	}
+	return strings.TrimSpace(out.String())
+}
+
+func permissionStrings(args map[string]any, key string) []string {
+	raw, _ := args[key].([]any)
+	out := make([]string, 0, len(raw))
+	for _, item := range raw {
