+
+// A range the edit OVERLAPS is dropped: after rewriting those lines the earlier
+// read no longer describes what is there.
+func TestARangeTheEditOverlapsIsDropped(t *testing.T) {
+	path, tracker, tool := editTrackerFixture(t, numberedLines(100, map[int]string{
+		20: "alpha",
+		21: "beta",
+		22: "gamma",
+	}))
