diff --git a/dev/zero/internal/specialist/plan_params.go b/dev/zero/internal/specialist/plan_params.go
--- /dev/null
+++ b/dev/zero/internal/specialist/plan_params.go
@@ @@
+package specialist
+
+import (
+	"fmt"
+	"regexp"
+	"sort"
+	"strings"
+)
+
+// Parameters for a saved plan: the difference between a plan you re-run and one
+// you re-author.
+//
+// A saved plan is stored args and re-admitted through ParsePlan, which makes it
+// exactly repeatable and completely fixed. "Audit internal/tui" cannot be run
+// against internal/cli without opening the file and editing the prompt of every
+// task — so in practice a plan gets copied per target and the copies drift.
+//
+// WHAT MAY BE SUBSTITUTED IS DELIBERATELY NARROW. Only prose the model reads:
+// each task's prompt, and the plan's description. Not `tools`, which is the
+// authority grant; not `id` or `depends_on`, which are the graph; not `model` or
+// the budget. A parameter that could reach the grant would turn "run the sweep
+// plan with scope=x" into a way to widen what the plan may do, and a parameter
+// that could reach an id would let one argument silently detach a dependency
+// edge. Those are fixed when the plan is saved and reviewed, and they stay fixed.
+//
+// Expansion happens BEFORE ParsePlan, so validation, tool-grant narrowing, depth
+// and budget checks all run against the plan that will actually execute rather
+// than against a template of it.
+
+// planParamPattern matches ${name} with no nesting and no expressions. A
+// template language here would be a second thing to validate and a second place
+// for authority to leak; substitution is all this needs to be.
+var planParamPattern = regexp.MustCompile(`\$\{([a-zA-Z][a-zA-Z0-9_-]*)\}`)
+
+// planParamFields are the keys whose values a parameter may reach. Everything
+// absent from this list is structure or authority — see the file comment.
+var planParamTaskFields = []string{"prompt"}
+
+// expandPlanParams substitutes params into a saved plan's args.
+//
+// FAILS CLOSED IN BOTH DIRECTIONS. A placeholder with no argument is an error
+// rather than a prompt containing a literal "${scope}", which reads to the model
+// as an instruction about a directory that does not exist. An argument with no
+// placeholder is an error too: it is almost always a typo, and silently ignoring
+// it runs the plan against the wrong target while reporting success.
+func expandPlanParams(args map[string]any, params map[string]string) (map[string]any, error) {
+	declared := planParamPlaceholders(args)
+	if len(declared) == 0 && len(params) == 0 {
+		return args, nil
+	}
+
+	var missing []string
+	for _, name := range declared {
+		if _, ok := params[name]; !ok {
+			missing = append(missing, name)
+		}
+	}
+	if len(missing) > 0 {
+		return nil, fmt.Errorf("this plan needs %s: supply %s in params",
+			pluralParams(missing), strings.Join(quoteAll(missing), ", "))
+	}
+
+	known := map[string]bool{}
+	for _, name := range declared {
+		known[name] = true
+	}
+	var unused []string
+	for name := range params {
+		if !known[name] {
+			unused = append(unused, name)
+		}
+	}
+	if len(unused) > 0 {
+		sort.Strings(unused)
+		return nil, fmt.Errorf("this plan has no %s: %s appears nowhere in it%s",
+			pluralParams(unused), strings.Join(quoteAll(unused), ", "), declaredHint(declared))
+	}
+
+	return substitutePlanParams(args, params), nil
+}
+
+// planParamPlaceholders lists every ${name} the plan uses, deduplicated and
+// sorted so an error message reads the same way twice.
+//
+// Scanned ONLY where substitution is allowed. A ${name} inside a tool grant is
+// not a parameter this plan takes; it is a literal that will fail tool
+// validation, which is the correct outcome and a clearer error than anything
+// this could say about it.
+func planParamPlaceholders(args map[string]any) []string {
+	found := map[string]bool{}
+	collect := func(text string) {
+		for _, match := range planParamPattern.FindAllStringSubmatch(text, -1) {
+			found[match[1]] = true
+		}
+	}
+	collect(planString(args, "description"))
+	if tasks, ok := args["tasks"].([]any); ok {
+		for _, raw := range tasks {
+			entry, ok := raw.(map[string]any)
+			if !ok {
+				continue
+			}
+			for _, field := range planParamTaskFields {
+				collect(planString(entry, field))
+			}
+		}
+	}
+	out := make([]string, 0, len(found))
+	for name := range found {
+		out = append(out, name)
+	}
+	sort.Strings(out)
+	return out
+}
+
+// substitutePlanParams returns a COPY with the substitutions applied. The stored
+// plan is never mutated: LoadPlans caches by path, and rewriting a cached plan
+// would leave the next run of it carrying the previous run's arguments.
+func substitutePlanParams(args map[string]any, params map[string]string) map[string]any {
+	replace := func(text string) string {
+		return planParamPattern.ReplaceAllStringFunc(text, func(match string) string {
+			name := planParamPattern.FindStringSubmatch(match)[1]
+			if value, ok := params[name]; ok {
+				return value
+			}
+			return match
+		})
+	}
+
+	out := make(map[string]any, len(args))
+	for key, value := range args {
+		out[key] = value
+	}
+	if description := planString(args, "description"); description != "" {
+		out["description"] = replace(description)
+	}
+	tasks, ok := args["tasks"].([]any)
+	if !ok {
+		return out
+	}
+	expanded := make([]any, 0, len(tasks))
+	for _, raw := range tasks {
+		entry, ok := raw.(map[string]any)
+		if !ok {
+			expanded = append(expanded, raw)
+			continue
+		}
+		copied := make(map[string]any, len(entry))
+		for key, value := range entry {
+			copied[key] = value
+		}
+		for _, field := range planParamTaskFields {
+			if text := planString(entry, field); text != "" {
+				copied[field] = replace(text)
+			}
+		}
+		expanded = append(expanded, copied)
+	}
+	out["tasks"] = expanded
+	return out
+}
+
+// planParamsFromArgs reads the caller's params map, rejecting a shape that would
+// otherwise substitute something like "map[]" into a prompt.
+func planParamsFromArgs(args map[string]any) (map[string]string, error) {
+	raw, present := args["params"]
+	if !present {
+		return nil, nil
+	}
+	entries, ok := raw.(map[string]any)
+	if !ok {
+		return nil, fmt.Errorf("params must be an object of name/value pairs")
+	}
+	out := make(map[string]string, len(entries))
+	for name, value := range entries {
+		text, ok := value.(string)
+		if !ok {
+			return nil, fmt.Errorf("params[%q] must be a string; a plan parameter is substituted into a prompt as written", name)
+		}
+		if strings.TrimSpace(name) == "" {
+			return nil, fmt.Errorf("a plan parameter must be named")
+		}
+		out[name] = text
+	}
+	return out, nil
+}
+
+func quoteAll(names []string) []string {
+	out := make([]string, 0, len(names))
+	for _, name := range names {
+		out = append(out, `"`+name+`"`)
+	}
+	return out
+}
+
+func pluralParams(names []string) string {
+	if len(names) == 1 {
+		return "parameter"
+	}
+	return "parameters"
+}
+
+func declaredHint(declared []string) string {
+	if len(declared) == 0 {
+		return " (it takes none)"
+	}
+	return " (it takes " + strings.Join(quoteAll(declared), ", ") + ")"
+}

diff --git a/dev/zero/internal/specialist/capabilities.go b/dev/zero/internal/specialist/capabilities.go
--- /dev/null
+++ b/dev/zero/internal/specialist/capabilities.go
@@ @@
+package specialist
+
+import "context"
+
+// What this run may RELY ON for one model.
+//
+// WHY A RESOLVED RECORD RATHER THAN FOUR LOOKUPS. Capability knowledge is
+// scattered by construction: DiscoveredModel carries what the provider listed,
+// ModelProber carries whether it will actually serve, and the context window
+// lives in a catalogue this package cannot import. Every feature that needs to
+// know "can I do X with this model" therefore invents its own guess, and a guess
+// keyed on the model id is wrong for most of this catalogue — twenty-one of its
+// providers are OpenAI-compatible gateways whose ids are some upstream vendor's
+// ids, and ModelFamilyFor returns "" for nearly all of them.
+//
+// THE RULE: capability is REPORTED, never inferred from a provider or vendor
+// name. When nothing reported it, the answer is unknown and the caller degrades
+// to the behaviour that works everywhere.
+//
+// There is already a precedent for that shape in this tree and this mirrors it
+// deliberately: agent.ContextMeasurement documents "0 when unknown" and the loop
+// makes compaction a no-op at 0. Unknown disables an optimisation; it never
+// guesses and never fails.
+
+// Tri is a three-valued answer: reported yes, reported no, or nothing reported.
+//
+// NOT A BOOL, and that is the whole point of this file. A bool collapses "the
+// provider said no" into "the provider said nothing", and those two call for
+// OPPOSITE responses — refuse versus degrade. ModelProbeVerdict already made
+// this exact distinction for probing ("we could not ask" and "it said no" call
+// for opposite responses and conflating them would drop a working model on a
+// flaky network); this generalises it to the rest of a model's capabilities.
+type Tri uint8
+
+const (
+	// TriUnknown is the ZERO VALUE, so a Capabilities nobody filled in claims
+	// nothing rather than claiming everything is absent.
+	TriUnknown Tri = iota
+	TriYes
+	TriNo
+)
+
+func (t Tri) String() string {
+	switch t {
+	case TriYes:
+		return "yes"
+	case TriNo:
+		return "no"
+	default:
+		return "unknown"
+	}
+}
+
+// Known reports whether anything was actually reported.
+func (t Tri) Known() bool { return t != TriUnknown }
+
+// Denied reports the ONLY case a caller may refuse on. Written as its own method
+// so a caller cannot spell the refusal as `!yes` — which is the bug this type
+// exists to prevent, since `!yes` is true for unknown.
+func (t Tri) Denied() bool { return t == TriNo }
+
+// Capabilities is one model's resolved answer set.
+type Capabilities struct {
+	// ToolCall is whether the model can call tools at all. A plan task that
+	// cannot is not a plan task.
+	ToolCall Tri
+	// Reasoning is whether a reasoning effort may be sent.
+	Reasoning Tri
+	// TextOutput is whether it emits text. A real run assigned
+	// grok-imagine-video-1.5 to a verify stage purely because it was the most
+	// expensive thing on the account, and every task depending on it was doomed
+	// before it started.
+	TextOutput Tri
+	// ContextWindow is the model's window in tokens, 0 when unknown — the same
+	// spelling and the same meaning as agent.ContextMeasurement.ContextWindow,
+	// so the two cannot drift into disagreeing about what 0 means.
+	ContextWindow int
+	// Runnable is whether the provider will actually serve it, as opposed to
+	// merely listing it.
+	Runnable Tri
+}
+
+// ContextWindowFunc reports a model's context window, 0 when unknown.
+//
+// A HOOK, not an import, for the same reason ModelDiscoverer and ModelProber are
+// hooks: this package runs on the child-execution path and must not drag the
+// provider stack in behind it. The surface that owns the catalogue supplies it;
+// nil means no window is knowable here, which is the honest default for a run
+// that never wired one.
+type ContextWindowFunc func(modelID string) int
+
+// CapabilityResolver answers capability questions for the active provider.
+//
+// EVERY SEAM IS OPTIONAL. A resolver with nothing wired returns all-unknown for
+// every model, and the degrade rules below make that a working configuration
+// rather than a broken one — which is what lets the same code run against a
+// local Ollama, a headless exec with no discovery, and a fully-featured gateway.
+type CapabilityResolver struct {
+	Discover ModelDiscoverer
+	Probe    ModelProber
+	Window   ContextWindowFunc
+}
+
+// Resolve answers for one model.
+//
+// RESOLUTION ORDER, most trustworthy first: the prober (it asked and got an
+// answer), then discovery (the provider described it), then the window hook.
+// Never the model id, never the provider name.
+//
+// A nil resolver resolves to all-unknown rather than panicking, so a caller that
+// never wired one keeps working.
+func (resolver *CapabilityResolver) Resolve(ctx context.Context, modelID string) Capabilities {
+	caps := Capabilities{}
+	if resolver == nil || modelID == "" {
+		return caps
+	}
+	if resolver.Probe != nil {
+		switch resolver.Probe(ctx, modelID).Verdict {
+		case ProbeServes:
+			caps.Runnable = TriYes
+		case ProbeRefuses:
+			caps.Runnable = TriNo
+		}
+		// ProbeUnknown leaves TriUnknown, deliberately: the probe's own comment
+		// says a timeout is "NOT a refusal".
+	}
+	if resolver.Discover != nil {
+		if model, found := findDiscoveredModel(ctx, resolver.Discover, modelID); found {
+			caps.ToolCall = triFromClaim(model.ToolCall)
+			caps.Reasoning = triFromClaim(model.Reasoning)
+			caps.TextOutput = textOutputTri(model)
+		}
+	}
+	if resolver.Window != nil {
+		if window := resolver.Window(modelID); window > 0 {
+			caps.ContextWindow = window
+		}
+	}
+	return caps
+}
+
+// triFromClaim converts a discovery boolean, and ONLY A TRUE IS INFORMATIVE.
+//
+// THIS IS THE ASYMMETRY THAT MAKES THE TYPE WORTH HAVING. DiscoveredModel's
+// booleans are false both when the provider said "no" and when it said nothing —
+// and a minimal gateway listing `{"id": "..."}` and nothing else produces false
+// for every field. Reading that false as TriNo would refuse to schedule models
+// that work perfectly well, on exactly the providers that report least: most of
+// this catalogue.
+//
+// So a positive claim is trusted and an absent one is unknown. The cost of being
+// wrong is then a capability we decline to rely on, never a working model
+// refused — the same direction emitsText already chose, where the heuristic "can
+// only ever EXCLUDE a candidate".
+func triFromClaim(claimed bool) Tri {
+	if claimed {
+		return TriYes
+	}
+	return TriUnknown
+}
+
+// textOutputTri is emitsText's answer, keeping the distinction emitsText has to
+// throw away.
+//
+// ONE AUTHORITY, NOT TWO. emitsText decides which models auto-assign may pick
+// and must keep returning a bool; this needs to tell "the provider listed
+// modalities and text was not among them" (TriNo — decisive) apart from "the
+// provider listed nothing and the name looks fine" (TriUnknown — a guess). Both
+// read the same fields in the same order, and a test asserts they never
+// disagree about exclusion.
+func textOutputTri(model DiscoveredModel) Tri {
+	if len(model.OutputModalities) > 0 {
+		if emitsText(model) {
+			return TriYes
+		}
+		return TriNo
+	}
+	// No declared modalities: emitsText falls back to a name heuristic. A marker
+	// hit is worth acting on; its absence is not a claim about anything.
+	if !emitsText(model) {
+		return TriNo
+	}
+	return TriUnknown
+}
+
+// findDiscoveredModel looks one model up in the provider's list.
+func findDiscoveredModel(ctx context.Context, discover ModelDiscoverer, modelID string) (DiscoveredModel, bool) {
+	models, err := discover(ctx)
+	if err != nil {
+		// A DISCOVERY FAILURE IS UNKNOWN, NOT ABSENT. Treating an unreachable
+		// provider as "this model has no capabilities" would degrade every task
+		// on a flaky network instead of leaving them alone.
+		return DiscoveredModel{}, false
+	}
+	for _, model := range models {
+		if model.ID == modelID {
+			return model, true
+		}
+	}
+	return DiscoveredModel{}, false
+}
+
+// The degrade rules. Each is a NAMED FUNCTION rather than an inline comparison
+// so that the behaviour for unknown is stated once, tested once, and cannot be
+// spelled differently by the next caller.
+
+// MayCarryReasoningEffort reports whether an effort may be sent with this model.
+//
+// UNKNOWN MEANS DO NOT SEND. This is the one rule that fails CLOSED, and the
+// asymmetry is the reason: an unsupported effort is a provider-specific 400 that
+// kills the task outright, while omitting a supported one merely runs it at the
+// provider's default. A dead task is worse than a cheaper one.
+func (caps Capabilities) MayCarryReasoningEffort() bool { return caps.Reasoning == TriYes }
+
+// MayRunPlanTask reports whether a task may be assigned this model.
+//
+// UNKNOWN MEANS YES, and this rule fails OPEN — opposite to the one above,
+// deliberately. Refusing to schedule on unknown would refuse every model on
+// every provider that reports nothing, which is most of this catalogue; a model
+// that genuinely cannot call tools fails loudly on its first tool call, which is
+// a clearer error than a plan that will not start. Only an explicit no, or a
+// prober's explicit refusal, removes a candidate.
+func (caps Capabilities) MayRunPlanTask() bool {
+	return !caps.ToolCall.Denied() && !caps.TextOutput.Denied() && !caps.Runnable.Denied()
+}
+
+// RefusalReason says WHY a model was excluded, for a report that must not just
+// say a task was not assigned.
+func (caps Capabilities) RefusalReason() string {
+	switch {
+	case caps.Runnable.Denied():
+		return "the provider will not serve this model"
+	case caps.ToolCall.Denied():
+		return "this model does not support tool calls, and a plan task needs them"
+	case caps.TextOutput.Denied():
+		return "this model does not emit text"
+	default:
+		return ""
+	}
+}
diff --git a/dev/zero/internal/specialist/capabilities_test.go b/dev/zero/internal/specialist/capabilities_test.go
--- /dev/null
+++ b/dev/zero/internal/specialist/capabilities_test.go
@@ @@
+package specialist
+
+import (
+	"context"
+	"errors"
+	"testing"
+)
+
+// UNKNOWN IS THE MAJORITY CASE IN THIS CATALOGUE, so it is tested first and
+// tested hardest. Twenty-one of the catalogue's providers are OpenAI-compatible
+// gateways, ModelFamilyFor returns "" for nearly all of them, and a minimal
+// gateway lists {"id": "..."} with no capability fields at all.
+
+func TestAResolverWithNothingWiredClaimsNothing(t *testing.T) {
+	var resolver *CapabilityResolver
+	caps := resolver.Resolve(context.Background(), "glm-5.2")
+	if caps.ToolCall.Known() || caps.Reasoning.Known() || caps.TextOutput.Known() || caps.Runnable.Known() {
+		t.Fatalf("a nil resolver reported a capability: %+v", caps)
+	}
+	if caps.ContextWindow != 0 {
+		t.Fatalf("a nil resolver reported a window of %d", caps.ContextWindow)
+	}
+	// And all-unknown must be a WORKING configuration, not a broken one.
+	if !caps.MayRunPlanTask() {
+		t.Fatal("all-unknown refuses to run a task: every provider that reports nothing would be unusable")
+	}
+}
+
+// THE ASYMMETRY THAT JUSTIFIES Tri. DiscoveredModel's booleans are false both
+// when the provider said no and when it said nothing. A minimal gateway entry
+// therefore looks identical to a deliberate denial, and reading it as denial
+// refuses working models on exactly the providers that report least.
+func TestAnUnreportedCapabilityIsNotADenial(t *testing.T) {
+	resolver := &CapabilityResolver{
+		Discover: staticDiscovery(DiscoveredModel{ID: "mimo-v2.5-pro"}),
+	}
+	caps := resolver.Resolve(context.Background(), "mimo-v2.5-pro")
+
+	if caps.ToolCall.Denied() {
+		t.Fatal("a minimal gateway listing was read as 'this model cannot call tools'")
+	}
+	if caps.ToolCall.Known() {
+		t.Fatalf("an absent claim was reported as %s; it is not a claim", caps.ToolCall)
+	}
+	if !caps.MayRunPlanTask() {
+		t.Fatalf("refused a model the provider simply did not describe: %s", caps.RefusalReason())
+	}
+}
+
+func TestAPositiveClaimIsTrusted(t *testing.T) {
+	resolver := &CapabilityResolver{
+		Discover: staticDiscovery(DiscoveredModel{
+			ID: "gpt-4.1", ToolCall: true, Reasoning: true, OutputModalities: []string{"text"},
+		}),
+	}
+	caps := resolver.Resolve(context.Background(), "gpt-4.1")
+	if caps.ToolCall != TriYes || caps.Reasoning != TriYes || caps.TextOutput != TriYes {
+		t.Fatalf("a fully-described model was not believed: %+v", caps)
+	}
+	if !caps.MayCarryReasoningEffort() {
+		t.Fatal("a model that reports reasoning may carry an effort")
+	}
+}
+
+// The two rules fail in OPPOSITE directions, and that is the design.
+func TestTheTwoDegradeRulesFailInOppositeDirections(t *testing.T) {
+	unknown := Capabilities{}
+	// Fails CLOSED: an unsupported effort is a provider-specific 400 that kills
+	// the task; omitting a supported one merely runs at the default.
+	if unknown.MayCarryReasoningEffort() {
+		t.Fatal("an effort would be sent to a model that never claimed to support one")
+	}
+	// Fails OPEN: refusing on unknown would refuse most of this catalogue.
+	if !unknown.MayRunPlanTask() {
+		t.Fatal("an undescribed model may still run a task")
+	}
+}
+
+// Only an explicit denial removes a candidate — and each denial names itself, so
+// a report can say why rather than only that a task was not assigned.
+func TestOnlyAnExplicitDenialRemovesACandidate(t *testing.T) {
+	for _, tc := range []struct {
+		name string
+		caps Capabilities
+		want string
+	}{
+		{"provider refuses to serve it", Capabilities{Runnable: TriNo}, "will not serve"},
+		{"declares no tool calls", Capabilities{ToolCall: TriNo}, "does not support tool calls"},
+		{"emits no text", Capabilities{TextOutput: TriNo}, "does not emit text"},
+	} {
+		t.Run(tc.name, func(t *testing.T) {
+			if tc.caps.MayRunPlanTask() {
+				t.Fatal("an explicit denial did not remove the candidate")
+			}
+			if reason := tc.caps.RefusalReason(); reason == "" {
+				t.Fatal("a refusal with no reason: the report cannot say why")
+			}
+		})
+	}
+	if reason := (Capabilities{}).RefusalReason(); reason != "" {
+		t.Fatalf("an all-unknown model was given a refusal reason: %q", reason)
+	}
+}
+
+// A PROBE TIMEOUT IS NOT A REFUSAL. plan_model_probe.go says so in as many
+// words; this asserts the resolver honours it rather than restating it.
+func TestAProbeThatCouldNotAskDoesNotRemoveTheModel(t *testing.T) {
+	for verdict, want := range map[ModelProbeVerdict]Tri{
+		ProbeUnknown: TriUnknown,
+		ProbeServes:  TriYes,
+		ProbeRefuses: TriNo,
+	} {
+		resolver := &CapabilityResolver{
+			Probe: func(context.Context, string) ModelProbeResult { return ModelProbeResult{Verdict: verdict} },
+		}
+		caps := resolver.Resolve(context.Background(), "m")
+		if caps.Runnable != want {
+			t.Fatalf("verdict %v resolved to %s, want %s", verdict, caps.Runnable, want)
+		}
+	}
+	unreachable := &CapabilityResolver{
+		Probe: func(context.Context, string) ModelProbeResult { return ModelProbeResult{Verdict: ProbeUnknown} },
+	}
+	if !unreachable.Resolve(context.Background(), "m").MayRunPlanTask() {
+		t.Fatal("a flaky network dropped a working model")
+	}
+}
+
+// A DISCOVERY FAILURE IS UNKNOWN, NOT ABSENT. Treating an unreachable provider
+// as "this model has no capabilities" would degrade every task at once.
+func TestAnUnreachableProviderLeavesCapabilitiesAlone(t *testing.T) {
+	resolver := &CapabilityResolver{
+		Discover: func(context.Context) ([]DiscoveredModel, error) { return nil, errors.New("connection refused") },
+	}
+	caps := resolver.Resolve(context.Background(), "gpt-4.1")
+	if caps.ToolCall.Known() || caps.TextOutput.Known() {
+		t.Fatalf("an unreachable provider produced claims: %+v", caps)
+	}
+	if !caps.MayRunPlanTask() {
+		t.Fatal("a network blip refused a model")
+	}
+}
+
+// ONE AUTHORITY, NOT TWO. textOutputTri and emitsText read the same fields; they
+// may differ in precision but never in whether a model is EXCLUDED.
+func TestTheTextRulesNeverDisagreeAboutExclusion(t *testing.T) {
+	for _, model := range []DiscoveredModel{
+		{ID: "gpt-4.1", OutputModalities: []string{"text"}},
+		{ID: "grok-imagine-video-1.5", OutputModalities: []string{"video"}},
+		{ID: "grok-imagine-video-1.5"},
+		{ID: "some-embedding-model"},
+		{ID: "mimo-v2.5-pro"},
+		{ID: "whisper-large"},
+	} {
+		excludedByTri := textOutputTri(model).Denied()
+		excludedByBool := !emitsText(model)
+		if excludedByTri != excludedByBool {
+			t.Errorf("%q: Tri excludes=%v, emitsText excludes=%v — two rules, one question",
+				model.ID, excludedByTri, excludedByBool)
+		}
+	}
+}
+
+// The window carries the same meaning as agent.ContextMeasurement's: 0 is
+// unknown, and unknown disables an optimisation rather than guessing.
+func TestAnUnknownWindowIsZeroRatherThanAGuess(t *testing.T) {
+	resolver := &CapabilityResolver{Window: func(string) int { return 0 }}
+	if got := resolver.Resolve(context.Background(), "m").ContextWindow; got != 0 {
+		t.Fatalf("an unknown window became %d", got)
+	}
+	sized := &CapabilityResolver{Window: func(string) int { return 204_800 }}
+	if got := sized.Resolve(context.Background(), "m").ContextWindow; got != 204_800 {
+		t.Fatalf("a reported window became %d", got)
+	}
+	// A negative or nonsensical window must not propagate as one.
+	broken := &CapabilityResolver{Window: func(string) int { return -1 }}
+	if got := broken.Resolve(context.Background(), "m").ContextWindow; got != 0 {
+		t.Fatalf("a negative window became %d rather than unknown", got)
+	}
+}
+
+func staticDiscovery(models ...DiscoveredModel) ModelDiscoverer {
+	return func(context.Context) ([]DiscoveredModel, error) { return models, nil }
+}
diff --git a/dev/zero/internal/specialist/plan_exec.go b/dev/zero/internal/specialist/plan_exec.go
--- a/dev/zero/internal/specialist/plan_exec.go
+++ b/dev/zero/internal/specialist/plan_exec.go
@@ @@
 const (
 	dependencyBriefingPerTask = 4000
 	dependencyBriefingTotal   = 12000
 )
+
+// SIZED TO THE READER'S CONTEXT WINDOW when one is known.
+//
+// The constants above are provider-blind, and this catalogue is not: its models
+// run from an 8k local Ollama to a 1M-context gateway. 12,000 characters is
+// most of a small model's context and a rounding error in a large one's. A
+// measured case: a code-review child produced 18,349 characters and a dependent
+// task would have seen 4,000 of them — 78% discarded — whether it had room for
+// the rest or not.
+//
+// THE BUDGET BELONGS TO THE TASK THAT READS THE BRIEFING, never the one that
+// wrote it. With per-task models a 1M-context synthesiser routinely depends on a
+// 32k finder, and sizing by the producer would starve the reader for no reason.
+//
+// UNKNOWN KEEPS TODAY'S NUMBERS EXACTLY. A window of 0 means nothing reported
+// one — the majority case in this catalogue — and returns the two constants
+// unchanged, so every provider that describes nothing behaves byte-identically
+// to before this existed. Same contract as agent.ContextMeasurement: unknown
+// disables the adjustment rather than guessing at it.
+const (
+	// briefingWindowFraction is how much of a reader's context the inherited
+	// findings may occupy. A tenth leaves the task its own prompt, its tools and
+	// room to actually work — the briefing is an input to the job, not the job.
+	briefingWindowFraction = 0.10
+	// briefingCharsPerToken converts the window (tokens) to the budget
+	// (characters). Four is the usual English approximation and it only has to be
+	// the right order of magnitude: this decides a budget, not an invoice.
+	briefingCharsPerToken = 4
+	// briefingFloorTotal keeps a briefing worth reading on a very small model.
+	// Below this a dependent learns nothing and re-derives everything, which
+	// costs more than the characters saved.
+	briefingFloorTotal = 4000
+	// briefingCeilingTotal stops a 1M-context model from inheriting an entire
+	// plan. The bound the original constants existed for does not go away just
+	// because the window is large: a twenty-task chain still must not accumulate.
+	briefingCeilingTotal = 96_000
+	// briefingPerTaskShare is the total divided among dependencies. Three,
+	// because 12,000/4,000 is exactly the ratio the constants above already
+	// chose; deriving it keeps a 30k-window model on today's numbers rather than
+	// silently re-tuning every existing plan.
+	briefingPerTaskShare = 3
+)
+
+// dependencyBriefingBudget returns the per-dependency and whole-briefing caps
+// for a reader with the given context window, 0 meaning unknown.
+func dependencyBriefingBudget(contextWindow int) (perTask, total int) {
+	if contextWindow <= 0 {
+		return dependencyBriefingPerTask, dependencyBriefingTotal
+	}
+	total = int(float64(contextWindow) * briefingCharsPerToken * briefingWindowFraction)
+	if total < briefingFloorTotal {
+		total = briefingFloorTotal
+	}
+	if total > briefingCeilingTotal {
+		total = briefingCeilingTotal
+	}
+	return total / briefingPerTaskShare, total
+}
--- a/dev/zero/internal/specialist/plan_exec.go
+++ b/dev/zero/internal/specialist/plan_exec.go
@@ @@
-func ExecutePlan(ctx context.Context, plan Plan, parentTools []string, run PlanRunner, recorder PlanRecorder) PlanReport {
-	return ExecutePlanIn(ctx, plan, PlanWorkspace{}, parentTools, run, recorder)
+func ExecutePlan(ctx context.Context, plan Plan, parentTools []string, run PlanRunner, recorder PlanRecorder, opts ...ExecOption) PlanReport {
+	return ExecutePlanIn(ctx, plan, PlanWorkspace{}, parentTools, run, recorder, opts...)
 }
+
+// ExecOption tunes one plan execution.
+//
+// VARIADIC because ExecutePlanIn has seventy-five call sites, seventy-three of
+// them tests. A seventh positional parameter would rewrite every one of them to
+// pass a value they do not care about, and a test that had to be edited to keep
+// compiling is a test nobody re-read. An option they omit means "as before",
+// which is exactly what those tests are asserting.
+type ExecOption func(*execOptions)
+
+type execOptions struct {
+	// contextWindow reports the window of the model a TASK will run on, 0 when
+	// unknown. Called with the task's own model id, or "" when the task named
+	// none — the supplier knows what the run itself is using, and this package
+	// deliberately does not.
+	contextWindow ContextWindowFunc
+}
+
+// WithContextWindows sizes each task's dependency briefing to the context window
+// of the model that will READ it. Omitted, or supplied nil, every briefing keeps
+// the fixed caps it had before.
+func WithContextWindows(window ContextWindowFunc) ExecOption {
+	return func(o *execOptions) { o.contextWindow = window }
+}
+
+// windowFor is the resolved window for one task, and the nil-safe path that
+// makes every existing caller behave as it did.
+func (o execOptions) windowFor(task Task) int {
+	if o.contextWindow == nil {
+		return 0
+	}
+	return o.contextWindow(task.Model)
+}
