@@ @@
+package tui
+
+import (
+	"fmt"
+	"strings"
+	"time"
+
+	"github.com/Gitlawb/zero/internal/specialist"
+)
+
+// /workers — what this session has set going.
+//
+// READ FROM THE EVENT LOG, not from the sidebar's tracker. The tracker holds
+// what is on screen: it drops finished agents past their linger and it starts
+// empty on a resumed session. The event log is what actually happened, so a
+// session resumed after a crash still answers "what did I start, and what did it
+// cost". specialist.ReduceWorkers does the fold; this only renders it.
+
+func (m model) workersText() string {
+	if m.sessionStore == nil || m.activeSession.SessionID == "" {
+		return planControlNotice("warning",
+			"This session has no event log, so there is no record of what it started.")
+	}
+	events, err := m.sessionStore.ReadEvents(m.activeSession.SessionID)
+	if err != nil {
+		return planControlNotice("warning", "Could not read this session's events: "+err.Error())
+	}
+	summary := specialist.ReduceWorkers(events)
+	if summary.Started == 0 {
+		return planControlNotice("info",
+			"This session has started no sub-agents. Delegated work and plan tasks both appear here once they run.")
+	}
+
+	var b strings.Builder
+	fmt.Fprintf(&b, "%d sub-agent(s): %d running, %d done, %d failed\n",
+		summary.Started, summary.Running, summary.Done, summary.Failed)
+	// TOKENS ALWAYS, COST NEVER. Tokens are the one number every provider in this
+	// catalogue reports; rates are absent for most of its gateways, so a cost
+	// figure here would be right for some sessions and silently wrong for the
+	// rest. What it CANNOT account for is named instead of hidden.
+	fmt.Fprintf(&b, "%s tokens across the ones that reported usage", formatWorkerTokens(summary.Tokens))
+	if summary.Unmeasured > 0 {
+		fmt.Fprintf(&b, "; %d reported none, so this total does not cover %s",
+			summary.Unmeasured, pluralWorkers(summary.Unmeasured))
+	}
+	b.WriteString("\n\n")
+
+	now := m.now()
+	for _, worker := range summary.Workers {
+		b.WriteString("  " + workerStatusGlyph(worker.Status) + " ")
+		b.WriteString(workerLabel(worker))
+		if worker.Background {
+			b.WriteString(" · background")
+		}
+		fmt.Fprintf(&b, "\n      %s", worker.Duration(now).Round(time.Second))
+		if worker.TokensReported {
+			fmt.Fprintf(&b, " · %s tokens", formatWorkerTokens(worker.Tokens))
+		} else {
+			b.WriteString(" · usage not reported")
+		}
+		if worker.Model != "" {
+			b.WriteString(" · " + worker.Model)
+		}
+		if worker.Err != "" {
+			b.WriteString("\n      " + worker.Err)
+		}
+		b.WriteString("\n")
+	}
+	return planControlNotice("info", strings.TrimRight(b.String(), "\n"))
+}
+
+func workerLabel(worker specialist.Worker) string {
+	label := strings.TrimSpace(worker.Description)
+	if label == "" {
+		label = strings.TrimSpace(worker.Specialist)
+	}
+	if label == "" {
+		label = worker.SessionID
+	}
+	if worker.Kind == specialist.WorkerPlanTask {
+		return label
+	}
+	if specialistName := strings.TrimSpace(worker.Specialist); specialistName != "" && specialistName != label {
+		return label + " (" + specialistName + ")"
+	}
+	return label
+}
+
+func workerStatusGlyph(status specialist.WorkerStatus) string {
+	switch status {
+	case specialist.WorkerCompleted:
+		return "✓"
+	case specialist.WorkerFailed:
+		return "✗"
+	default:
+		return "•"
+	}
+}
+
+func pluralWorkers(n int) string {
+	if n == 1 {
+		return "one of them"
+	}
+	return fmt.Sprintf("%d of them", n)
+}
+
+// formatWorkerTokens groups thousands, because the numbers here run to millions
+// and an ungrouped one cannot be read at a glance.
+func formatWorkerTokens(n int) string {
+	text := fmt.Sprintf("%d", n)
+	if n < 0 {
+		return text
+	}
+	var out []byte
+	for i, digit := range []byte(text) {
+		if i > 0 && (len(text)-i)%3 == 0 {
+			out = append(out, ',')
+		}
+		out = append(out, digit)
+	}
+	return string(out)
+}
diff --git a/dev/zero/internal/specialist/plan_scratchpad.go b/dev/zero/internal/specialist/plan_scratchpad.go
--- /dev/null
+++ b/dev/zero/internal/specialist/plan_scratchpad.go
@@ @@
+package specialist
+
+import (
+	"fmt"
+	"os"
+	"path/filepath"
+	"regexp"
+	"strings"
+)
+
+// Where a plan's tasks leave their full answers for each other.
+//
+// THE PROBLEM IT SOLVES. A dependent task is handed an EXCERPT of what its
+// dependencies found — bounded, because a twenty-task chain inheriting every
+// ancestor's full output is a context-overflow machine. Measured: a code-review
+// child produced 18,349 characters and a dependent saw 4,000 of them. The other
+// 78% existed, was paid for, and was unreachable.
+//
+// THE DESIGN THAT AVOIDS EVERY TRAP. The obvious build — give tasks a shared
+// directory and let them write to it — fails twice over in this codebase:
+//
+//   - A READ-ONLY PLAN TASK HAS NO WRITE TOOL. planReadOnlyTools is read_file,
+//     grep, glob, list_directory, lsp_navigate. Handing those tasks a scratchpad
+//     to write into hands them something they cannot use, and the plans that most
+//     need this — parallel finders feeding a synthesiser — are exactly the
+//     read-only ones.
+//   - GRANTING THEM ONE CHANGES WHAT A READ-ONLY PLAN IS. RequiresIsolation()
+//     keys on precisely `!planReadOnlyTools[name]`, so adding a write tool would
+//     silently make every scratchpad-using plan demand a git worktree.
+//
+// So NO TASK WRITES HERE. The EXECUTOR does, single-threaded, as each result
+// comes back — and dependents read with the read_file they already hold. Write
+// contention is not locked against; it cannot arise, because there is exactly
+// one writer. The excerpt stops being lossy and becomes a summary with the whole
+// thing one tool call behind it.
+//
+// DISPOSABLE, and deliberately not memory: memory is durable, user-facing and
+// believed by later sessions. This is one plan's working notes and it is deleted
+// when the plan ends.
+
+// scratchpadTaskIDPattern is an ALLOW-LIST, because a task id becomes a
+// filename. Enumerating what is permitted is the rule this repo already applies
+// to plan names and memory names; a deny-list of traversal sequences is the
+// pattern that has leaked here repeatedly.
+var scratchpadTaskIDPattern = regexp.MustCompile(`^[a-zA-Z0-9_-]{1,64}$`)
+
+// Scratchpad is one plan run's directory of task outputs.
+//
+// A nil *Scratchpad is a working value: every method tolerates it and does
+// nothing, so a plan that never got one behaves exactly as it did before this
+// existed.
+type Scratchpad struct {
+	root string
+}
+
+// NewScratchpad creates a plan's directory.
+//
+// UNDER THE OS TEMP DIR, which is already a default sandbox write root on every
+// platform (defaultTempWriteRootCandidatesForGOOS: /tmp and $TMPDIR on unix,
+// TEMP/TMP on Windows). So the executor can write here without the plan holding
+// any grant it did not already have — and the tasks still need the root added to
+// their own scope to READ it, which is what PlanTaskRequest.ScratchpadRoot is
+// for.
+func NewScratchpad(planName string) (*Scratchpad, error) {
+	root, err := os.MkdirTemp("", "zero-plan-"+sanitizeScratchpadName(planName)+"-")
+	if err != nil {
+		return nil, fmt.Errorf("create a scratchpad for plan %q: %w", planName, err)
+	}
+	return &Scratchpad{root: root}, nil
+}
+
+// Root is the directory, or "" when there is none.
+func (pad *Scratchpad) Root() string {
+	if pad == nil {
+		return ""
+	}
+	return pad.root
+}
+
+// Record persists one task's FULL output and returns the path to it.
+//
+// Returns "" with no error when there is no scratchpad or nothing to record —
+// the caller then simply mentions nothing, rather than pointing a dependent at a
+// file that does not exist.
+func (pad *Scratchpad) Record(taskID, output string) (string, error) {
+	if pad == nil || pad.root == "" || strings.TrimSpace(output) == "" {
+		return "", nil
+	}
+	if !scratchpadTaskIDPattern.MatchString(taskID) {
+		// A task id that cannot be spelled as a filename is not an error worth
+		// failing the plan for — the task still ran and its excerpt still
+		// reaches its dependents. It simply gets no file.
+		return "", nil
+	}
+	path := filepath.Join(pad.root, taskID+".md")
+	if err := os.WriteFile(path, []byte(output), 0o600); err != nil {
+		return "", fmt.Errorf("record task %q output: %w", taskID, err)
+	}
+	return path, nil
+}
+
+// Release deletes the whole directory. Safe to call twice and on nil, because
+// it runs from a defer on a path that also has an error return.
+func (pad *Scratchpad) Release() {
+	if pad == nil || pad.root == "" {
+		return
+	}
+	_ = os.RemoveAll(pad.root)
+	pad.root = ""
+}
+
+// sanitizeScratchpadName keeps a plan's name out of the path unless it is
+// obviously safe. The temp-file suffix guarantees uniqueness either way, so
+// dropping an awkward name costs only readability.
+func sanitizeScratchpadName(name string) string {
+	cleaned := strings.Map(func(r rune) rune {
+		switch {
+		case r >= 'a' && r <= 'z', r >= 'A' && r <= 'Z', r >= '0' && r <= '9', r == '-', r == '_':
+			return r
+		default:
+			return -1
+		}
+	}, name)
+	if len(cleaned) > 32 {
+		cleaned = cleaned[:32]
+	}
+	if cleaned == "" {
+		return "plan"
+	}
+	return cleaned
+}
+
+// scratchpadPointer is the line appended to a truncated excerpt.
+//
+// ONLY WHEN TRUNCATED. A dependent that already received the whole answer has
+// nothing to go and read, and a path in every briefing is noise that trains the
+// reader to ignore the one that matters.
+func scratchpadPointer(path string, fullLength int) string {
+	if path == "" {
+		return ""
+	}
+	return fmt.Sprintf(
+		"[The excerpt above is truncated. The COMPLETE output of this task — %d characters — is at %s. "+
+			"Read that file if you need more than the excerpt, rather than re-deriving it.]",
+		fullLength, path)
+}
diff --git a/dev/zero/internal/specialist/plan_scratchpad_test.go b/dev/zero/internal/specialist/plan_scratchpad_test.go
--- /dev/null
+++ b/dev/zero/internal/specialist/plan_scratchpad_test.go
@@ @@
+package specialist
+
+import (
+	"context"
+	"os"
+	"path/filepath"
+	"strings"
+	"testing"
+)
+
+// THE MEASURED LOSS THIS CLOSES. A code-review child produced 18,349 characters
+// and a dependent task received 4,000 of them. The rest existed, was paid for,
+// and was unreachable.
+const measuredChildReport = 18_349
+
+func TestATruncatedExcerptNowPointsAtTheWholeAnswer(t *testing.T) {
+	pad, err := NewScratchpad("audit")
+	if err != nil {
+		t.Fatal(err)
+	}
+	defer pad.Release()
+
+	full := strings.Repeat("E", measuredChildReport)
+	path, err := pad.Record("by_name", full)
+	if err != nil {
+		t.Fatal(err)
+	}
+	if path == "" {
+		t.Fatal("nothing was recorded")
+	}
+
+	results := map[string]TaskResult{
+		"by_name": {ID: "by_name", Outcome: TaskSucceeded, Output: full, ScratchpadPath: path},
+	}
+	brief := withDependencyBriefingBudget(Task{ID: "synth", DependsOn: []string{"by_name"}}, results, 4000, 12000)
+
+	if !strings.Contains(brief, path) {
+		t.Fatalf("the dependent was truncated and never told where the rest is:\n%s", brief)
+	}
+	if !strings.Contains(brief, "18349") {
+		t.Fatalf("the briefing does not say how much it is holding back:\n%s", brief)
+	}
+	// And the file really holds the whole thing.
+	onDisk, err := os.ReadFile(path)
+	if err != nil {
+		t.Fatal(err)
+	}
+	if len(onDisk) != measuredChildReport {
+		t.Fatalf("recorded %d characters, the task produced %d", len(onDisk), measuredChildReport)
+	}
+}
+
+// A briefing that was NOT truncated has nothing to point at, and a path in every
+// briefing trains the reader to ignore the one that matters.
+func TestAnUntruncatedBriefingCarriesNoPointer(t *testing.T) {
+	pad, err := NewScratchpad("small")
+	if err != nil {
+		t.Fatal(err)
+	}
+	defer pad.Release()
+	path, err := pad.Record("find", "short answer")
+	if err != nil {
+		t.Fatal(err)
+	}
+	results := map[string]TaskResult{
+		"find": {ID: "find", Outcome: TaskSucceeded, Output: "short answer", ScratchpadPath: path},
+	}
+	brief := withDependencyBriefingBudget(Task{ID: "s", DependsOn: []string{"find"}}, results, 4000, 12000)
+	if strings.Contains(brief, path) {
+		t.Fatalf("an untruncated briefing carried a pointer:\n%s", brief)
+	}
+}
+
+// WITHOUT A SCRATCHPAD, THE OLD SENTENCE. Every existing plan must be unchanged.
+func TestWithoutAScratchpadTheBriefingIsExactlyWhatItWas(t *testing.T) {
+	results := map[string]TaskResult{
+		"find": {ID: "find", Outcome: TaskSucceeded, Output: strings.Repeat("E", 9000)},
+	}
+	brief := withDependencyBriefingBudget(Task{ID: "s", DependsOn: []string{"find"}}, results, 4000, 12000)
+	if !strings.Contains(brief, "[truncated — re-read the files named above if you need more]") {
+		t.Fatalf("the pre-existing truncation notice is gone:\n%s", brief)
+	}
+}
+
+// A nil scratchpad is a working value on every method — the path every caller
+// that never asked for one takes.
+func TestANilScratchpadIsAWorkingValue(t *testing.T) {
+	var pad *Scratchpad
+	if root := pad.Root(); root != "" {
+		t.Fatalf("nil scratchpad reported root %q", root)
+	}
+	path, err := pad.Record("t", "output")
+	if err != nil || path != "" {
+		t.Fatalf("nil scratchpad recorded %q (err %v)", path, err)
+	}
+	pad.Release()
+	pad.Release()
+	if roots := scratchpadReadRoots(pad); roots != nil {
+		t.Fatalf("nil scratchpad granted %v", roots)
+	}
+}
+
+// A TASK ID BECOMES A FILENAME, so it is allow-listed. Model-supplied ids reach
+// this, and a deny-list of traversal sequences is the pattern that has leaked
+// here repeatedly.
+func TestATaskIDThatCannotBeAFilenameIsRefusedNotEscaped(t *testing.T) {
+	pad, err := NewScratchpad("p")
+	if err != nil {
+		t.Fatal(err)
+	}
+	defer pad.Release()
+	for _, id := range []string{
+		"../escape", "a/b", "..", ".", "with space", "semi;colon",
+		strings.Repeat("x", 65), "", "nul\x00byte",
+	} {
+		path, err := pad.Record(id, "payload")
+		if err != nil {
+			t.Fatalf("id %q returned an error rather than declining: %v", id, err)
+		}
+		if path != "" {
+			t.Fatalf("id %q was accepted as a filename: %q", id, path)
+		}
+	}
+	// Nothing escaped the directory.
+	entries, err := os.ReadDir(pad.Root())
+	if err != nil {
+		t.Fatal(err)
+	}
+	if len(entries) != 0 {
+		t.Fatalf("refused ids still wrote %d file(s)", len(entries))
+	}
+}
+
+// Release actually deletes it — a plan's working notes are disposable, and a
+// directory per plan run that never went away would accumulate silently.
+func TestReleaseDeletesTheWholeDirectory(t *testing.T) {
+	pad, err := NewScratchpad("p")
+	if err != nil {
+		t.Fatal(err)
+	}
+	root := pad.Root()
+	if _, err := pad.Record("a", "x"); err != nil {
+		t.Fatal(err)
+	}
+	pad.Release()
+	if _, err := os.Stat(root); !os.IsNotExist(err) {
+		t.Fatalf("the scratchpad survived release: %v", err)
+	}
+	if pad.Root() != "" {
+		t.Fatal("a released scratchpad still reports a root")
+	}
+}
+
+// THE GRANT MUST REACH ARGV. A read root on a struct that never becomes
+// --add-dir is a directory the child cannot open — the exact "layer B does not
+// carry it" defect this branch has produced repeatedly.
+func TestTheScratchpadReadRootReachesTheChildsArgv(t *testing.T) {
+	pad, err := NewScratchpad("p")
+	if err != nil {
+		t.Fatal(err)
+	}
+	defer pad.Release()
+
+	executor := Executor{
+		BinaryPath:   "/bin/true",
+		NewSessionID: func() (string, error) { return "specialist_00000000000000000000000a", nil },
+		Load:         func(LoadOptions) (LoadResult, error) { return LoadResult{}, nil },
+	}
+	built, err := executor.BuildArgs(BuildArgsInput{
+		Prompt:         "look",
+		Cwd:            t.TempDir(),
+		CurrentDepth:   0,
+		PermissionMode: "auto",
+		ExtraReadRoots: []string{pad.Root()},
+	})
+	if err != nil {
+		t.Fatalf("BuildArgs: %v", err)
+	}
+	joined := strings.Join(built.Args, " ")
+	if !strings.Contains(joined, pad.Root()) {
+		t.Fatalf("the scratchpad never reached argv, so the child cannot read it:\n%s", joined)
+	}
+	if !strings.Contains(joined, "--add-dir") {
+		t.Fatalf("no --add-dir in argv:\n%s", joined)
+	}
+}
+
+// END TO END: a real plan, a real executor seam, and a dependent that can open
+// what its dependency wrote.
+func TestAPlanRunLeavesEachTasksFullOutputReadableByItsDependent(t *testing.T) {
+	plan := mustParsePlan(t, map[string]any{
+		"name": "research",
+		"tasks": []any{
+			map[string]any{"id": "find", "prompt": "look"},
+			map[string]any{"id": "synth", "prompt": "combine", "depends_on": []any{"find"}},
+		},
+		"budget": map[string]any{"max_workers": float64(1)},
+	}, Limits{MaxTasks: 20, ParentTools: PlanReadOnlyToolNames()})
+
+	full := strings.Repeat("E", measuredChildReport)
+	var synthPrompt string
+	var synthRoots []string
+	run := func(_ context.Context, req PlanTaskRequest) (TaskResult, error) {
+		if req.Task.ID == "synth" {
+			synthPrompt = req.Task.Prompt
+			synthRoots = req.ReadRoots
+			return TaskResult{ID: "synth", Outcome: TaskSucceeded, Output: "done"}, nil
+		}
+		return TaskResult{ID: req.Task.ID, Outcome: TaskSucceeded, Output: full}, nil
+	}
+
+	report := ExecutePlan(context.Background(), plan, PlanReadOnlyToolNames(), run, nil, WithScratchpad())
+	if report.Failed != 0 {
+		t.Fatalf("plan failed: %+v", report)
+	}
+	if len(synthRoots) != 1 {
+		t.Fatalf("the dependent was granted %v, want exactly the scratchpad", synthRoots)
+	}
+	// The prompt names a real file, and that file holds the whole answer.
+	var named string
+	for _, field := range strings.Fields(synthPrompt) {
+		if strings.HasSuffix(field, "find.md") {
+			named = strings.Trim(field, ".,")
+		}
+	}
+	if named == "" {
+		t.Fatalf("the dependent was never told where the full output is:\n%s", synthPrompt)
+	}
+	if !strings.HasPrefix(named, synthRoots[0]) {
+		t.Fatalf("the named path %q is outside the granted root %q", named, synthRoots[0])
+	}
+	body, err := os.ReadFile(named)
+	if err != nil {
+		t.Fatalf("the dependent cannot open what it was pointed at: %v", err)
+	}
+	if len(body) != measuredChildReport {
+		t.Fatalf("the file holds %d characters, the task produced %d", len(body), measuredChildReport)
+	}
+}
+
+// The plan's directory does not outlive the plan.
+func TestAFinishedPlanLeavesNoScratchpadBehind(t *testing.T) {
+	plan := mustParsePlan(t, map[string]any{
+		"name":   "research",
+		"tasks":  []any{map[string]any{"id": "find", "prompt": "look"}},
+		"budget": map[string]any{"max_workers": float64(1)},
+	}, Limits{MaxTasks: 20, ParentTools: PlanReadOnlyToolNames()})
+
+	var root string
+	run := func(_ context.Context, req PlanTaskRequest) (TaskResult, error) {
+		if len(req.ReadRoots) == 1 {
+			root = req.ReadRoots[0]
+		}
+		return TaskResult{ID: req.Task.ID, Outcome: TaskSucceeded, Output: "x"}, nil
+	}
+	ExecutePlan(context.Background(), plan, PlanReadOnlyToolNames(), run, nil, WithScratchpad())
+
+	if root == "" {
+		t.Fatal("no scratchpad was created, so this proves nothing")
+	}
+	if _, err := os.Stat(root); !os.IsNotExist(err) {
+		t.Fatalf("the scratchpad outlived the plan at %s", root)
+	}
+}
+
+// A cancelled task's partial findings are evidence — plan_exec already says so
+// where it briefs dependents — so they are kept for the same reason.
+func TestACancelledTasksPartialOutputIsStillRecorded(t *testing.T) {
+	pad, err := NewScratchpad("p")
+	if err != nil {
+		t.Fatal(err)
+	}
+	defer pad.Release()
+	path, err := pad.Record("cut-short", "found three things before I was stopped")
+	if err != nil {
+		t.Fatal(err)
+	}
+	if path == "" {
+		t.Fatal("a cut-short task's findings were discarded")
+	}
+	if filepath.Dir(path) != pad.Root() {
+		t.Fatalf("recorded outside the scratchpad: %s", path)
+	}
+}
diff --git a/dev/zero/internal/specialist/plan_template.go b/dev/zero/internal/specialist/plan_template.go
--- /dev/null
+++ b/dev/zero/internal/specialist/plan_template.go
@@ @@
+package specialist
+
+import (
+	"fmt"
+	"sort"
+	"strings"
+)
+
+// Plan shapes a model can ask for by name instead of composing from scratch.
+//
+// THE FAILURE THIS REMOVES. The model deciding to run a plan is not the problem
+// — system_prompt.go already tells it when to delegate, and a measured run
+// spawned a background sub-agent with the words "sub-agent", "spawn" and
+// "parallel" appearing nowhere in the prompt. The problem is what happens next:
+// it emits plan JSON that admission refuses, and a turn and a model call are
+// spent learning a rule. A real run emitted budget.max_tokens_per_task: 5000 and
+// was refused for sitting below the floor.
+//
+// SO THIS IS A GENERATOR, NOT A CLASSIFIER. Nothing here decides WHETHER to
+// plan. It only turns "audit this" into a task graph that admission accepts.
+//
+// DETERMINISTIC, AND THAT IS THE MULTI-PROVIDER ARGUMENT. An LLM generator needs
+// reliable structured output, which across this catalogue means JSON mode on
+// some providers, forced tool-use on others and prose-with-fences on the rest —
+// twenty-one of its entries are OpenAI-compatible gateways whose capabilities
+// are whatever the upstream vendor supports that day. A template needs nothing
+// from the provider, so it behaves identically on all of them, including a local
+// Ollama that reports no capabilities at all.
+//
+// EVERY TEMPLATE IS RE-VALIDATED THROUGH ParsePlan before it runs. These emit
+// the same args a model would; they are not a second admission path.
+
+// PlanTemplate is one named shape.
+type PlanTemplate struct {
+	// Name is what a caller asks for.
+	Name string
+	// WhenToUse is one line, for the tool description. Templates a model cannot
+	// tell apart are templates it picks at random.
+	WhenToUse string
+	// Params are the values it needs, in the order a caller would give them.
+	Params []string
+	// build emits orchestrate arguments. Never called with a missing param —
+	// BuildTemplatePlan checks first, so this cannot silently produce a plan
+	// with an empty subject.
+	build func(params map[string]string) map[string]any
+}
+
+// planTemplates are the shapes that recur. DELIBERATELY FEW: a template exists
+// here when its task graph is genuinely reusable, and inventing one per phrasing
+// would leave a list nobody can choose from.
+var planTemplates = []PlanTemplate{
+	{
+		Name:      "audit",
+		WhenToUse: "Examine one subject from several independent angles, then verify the findings before reporting them.",
+		Params:    []string{"subject"},
+		build: func(params map[string]string) map[string]any {
+			subject := params["subject"]
+			return map[string]any{
+				"name":        "audit",
+				"description": "Hostile audit of " + subject,
+				"tasks": []any{
+					templateTask("correctness", "find", "Find CORRECTNESS defects in "+subject+
+						". Report each as file:line, what is wrong, and a concrete reproduction. Prove it from the code; do not report what you suspect.", nil),
+					templateTask("safety", "find", "Find SAFETY and authority defects in "+subject+
+						": missing checks, trust placed in untrusted input, anything that fails open. Report each as file:line with the path that reaches it.", nil),
+					templateTask("tests", "find", "Find what TESTS "+subject+
+						", and name any test that asserts nothing meaningful. A behaviour with no test is itself a finding.", nil),
+					templateTask("refute", "verify", "Try to REFUTE every finding above. Default to refuted when uncertain. "+
+						"For each: open the cited file:line and check the claim is what the code actually does. Report VERIFIED with the line that proves it, or REFUTED with the line that disproves it.",
+						[]string{"correctness", "safety", "tests"}),
+					templateTask("report", "answer", "Report the findings that SURVIVED refutation, most severe first, each with its file:line and reproduction. "+
+						"Say plainly how many were refuted and dropped — a reader who is not told the count cannot tell a clean audit from a shallow one.",
+						[]string{"refute"}),
+				},
+				"budget": map[string]any{"max_workers": float64(3)},
+			}
+		},
+	},
+	{
+		Name:      "compare",
+		WhenToUse: "Establish how two things differ, by examining each on its own before comparing them.",
+		Params:    []string{"before", "after"},
+		build: func(params map[string]string) map[string]any {
+			before, after := params["before"], params["after"]
+			return map[string]any{
+				"name":        "compare",
+				"description": "Compare " + before + " against " + after,
+				"tasks": []any{
+					// EACH SIDE EXAMINED BLIND. A single task told to compare
+					// reads one side, forms a view, and reads the second looking
+					// for confirmation of it.
+					templateTask("left", "examine", "Describe "+before+" on its own terms: what it does, how, and with what limits. Cite file:line. Do NOT compare it to anything.", nil),
+					templateTask("right", "examine", "Describe "+after+" on its own terms: what it does, how, and with what limits. Cite file:line. Do NOT compare it to anything.", nil),
+					templateTask("diff", "answer", "Using the two descriptions above, state how "+before+" and "+after+
+						" differ, and where they agree. Where the two descriptions conflict, say which you believe and open the code to settle it — do not average them.",
+						[]string{"left", "right"}),
+				},
+				"budget": map[string]any{"max_workers": float64(2)},
+			}
+		},
+	},
+	{
+		Name:      "sweep",
+		WhenToUse: "Ask the same question of several targets independently, then combine the answers.",
+		Params:    []string{"question", "targets"},
+		build: func(params map[string]string) map[string]any {
+			// A VARIABLE TASK COUNT is the shape a model most often gets wrong by
+			// hand: it has to invent one id per target, keep them unique, and
+			// list every one of them in the synthesis task's depends_on. Getting
+			// any of that wrong is a refusal at admission.
+			targets := splitTemplateList(params["targets"])
+			tasks := make([]any, 0, len(targets)+1)
+			ids := make([]string, 0, len(targets))
+			for index, target := range targets {
+				id := templateTaskID("t", index, target)
+				ids = append(ids, id)
+				tasks = append(tasks, templateTask(id, "examine",
+					params["question"]+"\n\nAnswer this for exactly one target: "+target+
+						". Cite file:line. If the answer is 'this does not apply here', say so plainly rather than stretching for one.", nil))
+			}
+			tasks = append(tasks, templateTask("combine", "answer",
+				"Answer the question across every target above: "+params["question"]+
+					"\n\nState what holds everywhere, what holds only somewhere — naming which — and what contradicts. A target whose answer was empty is itself a result; do not drop it.",
+				ids))
+			return map[string]any{
+				"name":        "sweep",
+				"description": params["question"],
+				"tasks":       tasks,
+				"budget":      map[string]any{"max_workers": float64(templateWorkers(len(targets)))},
+			}
+		},
+	},
+}
+
+// PlanTemplates lists the shapes, sorted, for a tool description.
+func PlanTemplates() []PlanTemplate {
+	out := append([]PlanTemplate(nil), planTemplates...)
+	sort.Slice(out, func(i, j int) bool { return out[i].Name < out[j].Name })
+	return out
+}
+
+// BuildTemplatePlan emits the orchestrate arguments for one template.
+//
+// FAILS CLOSED IN BOTH DIRECTIONS, exactly as expandPlanParams does for saved
+// plans: a missing value is refused rather than substituted as empty prose, and
+// a value the template does not take is refused rather than dropped — a caller
+// who supplied it meant it, and ignoring it runs a different plan than the one
+// asked for while reporting success.
+func BuildTemplatePlan(name string, params map[string]string) (map[string]any, error) {
+	template, found := findPlanTemplate(name)
+	if !found {
+		return nil, fmt.Errorf("no plan template named %q; the templates are %s",
+			name, strings.Join(planTemplateNames(), ", "))
+	}
+	var missing []string
+	for _, param := range template.Params {
+		if strings.TrimSpace(params[param]) == "" {
+			missing = append(missing, param)
+		}
+	}
+	if len(missing) > 0 {
+		return nil, fmt.Errorf("the %q template needs %s: %s",
+			name, pluralParams(missing), strings.Join(quoteAll(missing), ", "))
+	}
+	known := map[string]bool{}
+	for _, param := range template.Params {
+		known[param] = true
+	}
+	var unused []string
+	for supplied := range params {
+		if !known[supplied] {
+			unused = append(unused, supplied)
+		}
+	}
+	if len(unused) > 0 {
+		sort.Strings(unused)
+		return nil, fmt.Errorf("the %q template takes no %s: %s (it takes %s)",
+			name, pluralParams(unused), strings.Join(quoteAll(unused), ", "),
+			strings.Join(quoteAll(template.Params), ", "))
+	}
+	return template.build(params), nil
+}
+
+func findPlanTemplate(name string) (PlanTemplate, bool) {
+	wanted := strings.ToLower(strings.TrimSpace(name))
+	for _, template := range planTemplates {
+		if template.Name == wanted {
+			return template, true
+		}
+	}
+	return PlanTemplate{}, false
+}
+
+func planTemplateNames() []string {
+	out := make([]string, 0, len(planTemplates))
+	for _, template := range PlanTemplates() {
+		out = append(out, template.Name)
+	}
+	return out
+}
+
+func templateTask(id, phase, prompt string, dependsOn []string) map[string]any {
+	task := map[string]any{"id": id, "phase": phase, "prompt": prompt}
+	if len(dependsOn) > 0 {
+		deps := make([]any, 0, len(dependsOn))
+		for _, dep := range dependsOn {
+			deps = append(deps, dep)
+		}
+		task["depends_on"] = deps
+	}
+	return task
+}
+
+// templateTaskID builds an id from a target that is ALREADY UNIQUE by its index,
+// so two targets that sanitise to the same string cannot collide — a collision
+// would silently drop one target's task and its dependency edge.
+func templateTaskID(prefix string, index int, target string) string {
+	var cleaned strings.Builder
+	for _, r := range strings.ToLower(target) {
+		switch {
+		case r >= 'a' && r <= 'z', r >= '0' && r <= '9':
+			cleaned.WriteRune(r)
+		case r == '_' || r == '-':
+			cleaned.WriteRune('_')
+		}
+		if cleaned.Len() >= 20 {
+			break
+		}
+	}
+	id := fmt.Sprintf("%s%d", prefix, index+1)
+	if cleaned.Len() > 0 {
+		id += "_" + cleaned.String()
+	}
+	return id
+}
+
+// splitTemplateList reads a comma-separated list, dropping blanks so a trailing
+// comma does not become a task with no target.
+func splitTemplateList(raw string) []string {
+	var out []string
+	for _, part := range strings.Split(raw, ",") {
+		if trimmed := strings.TrimSpace(part); trimmed != "" {
+			out = append(out, trimmed)
+		}
+	}
+	return out
+}
+
+// templateWorkers keeps a generated plan inside the range max_workers accepts,
+// so a sweep over thirty targets is refused by nothing. Never below 1: a plan
+// with zero workers cannot run and the schema forbids it.
+func templateWorkers(targets int) int {
+	switch {
+	case targets < 1:
+		return 1
+	case targets > maxPlanWorkers:
+		return maxPlanWorkers
+	default:
+		return targets
+	}
+}
diff --git a/dev/zero/internal/specialist/plan_template_test.go b/dev/zero/internal/specialist/plan_template_test.go
--- /dev/null
+++ b/dev/zero/internal/specialist/plan_template_test.go
@@ @@
+package specialist
+
+import (
+	"fmt"
+	"strings"
+	"testing"
+)
+
+// EVERY TEMPLATE MUST ADMIT. The whole point is that a model asking for a shape
+// by name cannot produce plan JSON that admission refuses — which is the turn a
+// real run spent discovering budget.max_tokens_per_task: 5000 was too low.
+func TestEveryTemplateProducesAPlanThatAdmits(t *testing.T) {
+	samples := map[string]map[string]string{
+		"audit":   {"subject": "the retry watchdog"},
+		"compare": {"before": "the old scheduler", "after": "the new scheduler"},
+		"sweep":   {"question": "does this package validate its input?", "targets": "internal/tui, internal/cli, internal/sandbox"},
+	}
+	limits := Limits{MaxTasks: 50, ParentTools: PlanReadOnlyToolNames()}
+
+	for _, template := range PlanTemplates() {
+		t.Run(template.Name, func(t *testing.T) {
+			params, ok := samples[template.Name]
+			if !ok {
+				t.Fatalf("template %q has no sample here: a template nothing exercises is untested", template.Name)
+			}
+			args, err := BuildTemplatePlan(template.Name, params)
+			if err != nil {
+				t.Fatalf("build: %v", err)
+			}
+			plan, err := ParsePlan(args, limits)
+			if err != nil {
+				t.Fatalf("the template emitted a plan admission refuses: %v", err)
+			}
+			if plan.TaskCount() < 2 {
+				t.Fatalf("a %d-task plan is not worth a plan", plan.TaskCount())
+			}
+			// No placeholder survived into a prompt.
+			for _, task := range plan.Tasks() {
+				if strings.Contains(task.Prompt, "${") || strings.TrimSpace(task.Prompt) == "" {
+					t.Fatalf("task %q has an unfilled or empty prompt: %q", task.ID, task.Prompt)
+				}
+			}
+			// And the parameters actually reached the prompts, rather than the
+			// template emitting a generic graph that ignores its input.
+			joined := strings.ToLower(renderPlanPrompts(plan))
+			for _, value := range params {
+				first := strings.ToLower(strings.Fields(value)[0])
+				if !strings.Contains(joined, first) {
+					t.Errorf("parameter value %q never reached any prompt", value)
+				}
+			}
+		})
+	}
+}
+
+// FAILS CLOSED IN BOTH DIRECTIONS, the same contract expandPlanParams holds for
+// saved plans.
+func TestATemplateRefusesMissingAndUnknownParameters(t *testing.T) {
+	if _, err := BuildTemplatePlan("audit", nil); err == nil {
+		t.Fatal("audit built a plan with no subject: five tasks would examine an empty string")
+	}
+	if _, err := BuildTemplatePlan("audit", map[string]string{"subject": "   "}); err == nil {
+		t.Fatal("whitespace was accepted as a subject")
+	}
+	if _, err := BuildTemplatePlan("audit", map[string]string{"subject": "x", "scope": "y"}); err == nil {
+		t.Fatal("an unknown parameter was silently dropped: the caller meant it")
+	}
+	if _, err := BuildTemplatePlan("nosuchtemplate", nil); err == nil {
+		t.Fatal("an unknown template name produced a plan")
+	}
+	// And the refusal names the alternatives, or the model cannot recover.
+	_, err := BuildTemplatePlan("nosuchtemplate", nil)
+	for _, name := range []string{"audit", "compare", "sweep"} {
+		if !strings.Contains(err.Error(), name) {
+			t.Errorf("the refusal does not name %q: %v", name, err)
+		}
+	}
+}
+
+// A VARIABLE TASK COUNT is the shape a model most often gets wrong by hand: one
+// unique id per target, every one of them listed in the synthesis dependency.
+func TestSweepWiresEveryTargetIntoTheSynthesis(t *testing.T) {
+	args, err := BuildTemplatePlan("sweep", map[string]string{
+		"question": "does this validate input?",
+		"targets":  "internal/tui, internal/cli, internal/sandbox, internal/agent",
+	})
+	if err != nil {
+		t.Fatal(err)
+	}
+	plan, err := ParsePlan(args, Limits{MaxTasks: 50, ParentTools: PlanReadOnlyToolNames()})
+	if err != nil {
+		t.Fatalf("sweep does not admit: %v", err)
+	}
+	if plan.TaskCount() != 5 {
+		t.Fatalf("4 targets produced %d tasks, want 4 + 1 synthesis", plan.TaskCount())
+	}
+	var combine Task
+	ids := map[string]bool{}
+	for _, task := range plan.Tasks() {
+		ids[task.ID] = true
+		if task.ID == "combine" {
+			combine = task
+		}
+	}
+	if len(ids) != plan.TaskCount() {
+		t.Fatal("two tasks share an id, so one target's work is lost")
+	}
+	if len(combine.DependsOn) != 4 {
+		t.Fatalf("the synthesis waits on %d of 4 targets: the rest are read before they finish", len(combine.DependsOn))
+	}
+	for _, dep := range combine.DependsOn {
+		if !ids[dep] {
+			t.Fatalf("the synthesis depends on %q, which is not a task", dep)
+		}
+	}
+}
+
+// TARGETS THAT SANITISE TO THE SAME STRING MUST NOT COLLIDE. A collision drops
+// one target's task and its dependency edge, silently.
+func TestSweepTargetsThatLookAlikeStillGetDistinctTasks(t *testing.T) {
+	args, err := BuildTemplatePlan("sweep", map[string]string{
+		"question": "q",
+		"targets":  "internal/tui, internal/TUI, internal-tui, internal tui",
+	})
+	if err != nil {
+		t.Fatal(err)
+	}
+	plan, err := ParsePlan(args, Limits{MaxTasks: 50, ParentTools: PlanReadOnlyToolNames()})
+	if err != nil {
+		t.Fatalf("look-alike targets do not admit: %v", err)
+	}
+	if plan.TaskCount() != 5 {
+		t.Fatalf("4 look-alike targets produced %d tasks: ids collided", plan.TaskCount())
+	}
+}
+
+// A sweep over more targets than the worker ceiling must still admit — the plan
+// runs them in waves rather than being refused.
+func TestALargeSweepStaysInsideTheWorkerCeiling(t *testing.T) {
+	var targets []string
+	for i := 0; i < 30; i++ {
+		targets = append(targets, fmt.Sprintf("pkg%d", i))
+	}
+	args, err := BuildTemplatePlan("sweep", map[string]string{
+		"question": "q", "targets": strings.Join(targets, ","),
+	})
+	if err != nil {
+		t.Fatal(err)
+	}
+	plan, err := ParsePlan(args, Limits{MaxTasks: 50, ParentTools: PlanReadOnlyToolNames()})
+	if err != nil {
+		t.Fatalf("a 30-target sweep does not admit: %v", err)
+	}
+	if workers := plan.Budget().MaxWorkers; workers < 1 || workers > maxPlanWorkers {
+		t.Fatalf("max_workers = %d, outside 1..%d", workers, maxPlanWorkers)
+	}
+	// A trailing comma must not become a task with no target.
+	trailing, err := BuildTemplatePlan("sweep", map[string]string{"question": "q", "targets": "a,b,"})
+	if err != nil {
+		t.Fatal(err)
+	}
+	if plan, err := ParsePlan(trailing, Limits{MaxTasks: 50, ParentTools: PlanReadOnlyToolNames()}); err != nil {
+		t.Fatalf("a trailing comma broke the plan: %v", err)
+	} else if plan.TaskCount() != 3 {
+		t.Fatalf("'a,b,' produced %d tasks, want 2 + 1", plan.TaskCount())
+	}
+}
+
+// A generated plan is READ-ONLY. It names no tools, so it inherits the
+// read-only grant and never trips RequiresIsolation — a template that quietly
+// demanded a git worktree would refuse to run wherever one is unavailable.
+func TestGeneratedPlansAreReadOnlyAndNeedNoWorktree(t *testing.T) {
+	for _, sample := range []struct {
+		name   string
+		params map[string]string
+	}{
+		{"audit", map[string]string{"subject": "s"}},
+		{"compare", map[string]string{"before": "a", "after": "b"}},
+		{"sweep", map[string]string{"question": "q", "targets": "a,b"}},
+	} {
+		args, err := BuildTemplatePlan(sample.name, sample.params)
+		if err != nil {
+			t.Fatal(err)
+		}
+		plan, err := ParsePlan(args, Limits{MaxTasks: 50, ParentTools: PlanReadOnlyToolNames()})
+		if err != nil {
+			t.Fatal(err)
+		}
+		if plan.RequiresIsolation() {
+			t.Errorf("template %q requires a worktree: it cannot run where git is unavailable", sample.name)
+		}
+	}
+}
+
+// Each template must be distinguishable, or the model picks at random.
+func TestEveryTemplateSaysWhatItIsFor(t *testing.T) {
+	seen := map[string]bool{}
+	for _, template := range PlanTemplates() {
+		if strings.TrimSpace(template.WhenToUse) == "" {
+			t.Errorf("template %q says nothing about when to use it", template.Name)
+		}
+		if seen[template.Name] {
+			t.Errorf("two templates named %q", template.Name)
+		}
+		seen[template.Name] = true
+		if len(template.Params) == 0 {
+			t.Errorf("template %q takes no parameters, so it cannot be about anything", template.Name)
+		}
+	}
+}
+
+func renderPlanPrompts(plan Plan) string {
+	var b strings.Builder
+	for _, task := range plan.Tasks() {
+		b.WriteString(task.Prompt)
+		b.WriteString("\n")
+	}
+	b.WriteString(plan.Description())
+	return b.String()
+}

diff --git a/dev/zero/internal/specialist/plan_router_spend_test.go b/dev/zero/internal/specialist/plan_router_spend_test.go
--- /dev/null
+++ b/dev/zero/internal/specialist/plan_router_spend_test.go
@@ @@
+package specialist
+
+import (
+	"context"
+	"strings"
+	"testing"
+)
+
+// ROUTER SPEND IS THE PLAN'S SPEND.
+//
+// auto_assign makes a frontier-model call to decide which model runs each task,
+// BEFORE any task starts and outside the executor entirely — plan_tool routes at
+// its own call site and only then reaches ExecutePlanIn. Its tokens therefore
+// reached neither the budget nor the report, and the code said so in as many
+// words: "the plan's reported spend is under its real spend by exactly this
+// much, every run, invisibly."
+//
+// Measured across 17 real sessions: 7,860 to 10,513 tokens per plan.
+const measuredRouterTokens = 10_513
+
+func routerSpendPlan(t *testing.T) Plan {
+	t.Helper()
+	return mustParsePlan(t, map[string]any{
+		"name":   "p",
+		"tasks":  []any{map[string]any{"id": "a", "prompt": "look"}},
+		"budget": map[string]any{"max_workers": float64(1)},
+	}, Limits{MaxTasks: 20, ParentTools: PlanReadOnlyToolNames()})
+}
+
+func succeedingRun(tokens int) PlanRunner {
+	return func(_ context.Context, req PlanTaskRequest) (TaskResult, error) {
+		return TaskResult{ID: req.Task.ID, Outcome: TaskSucceeded, Output: "done", Tokens: tokens}, nil
+	}
+}
+
+// THE REPORTED TOTAL MUST INCLUDE IT. This is the number a person reads to
+// decide whether a plan was worth what it cost.
+func TestTheReportedSpendIncludesWhatRoutingCost(t *testing.T) {
+	const taskTokens = 500_000
+
+	without := ExecutePlan(context.Background(), routerSpendPlan(t),
+		PlanReadOnlyToolNames(), succeedingRun(taskTokens), nil)
+	if without.TokensUsed != taskTokens {
+		t.Fatalf("an unrouted plan reported %d, want %d", without.TokensUsed, taskTokens)
+	}
+
+	with := ExecutePlan(context.Background(), routerSpendPlan(t),
+		PlanReadOnlyToolNames(), succeedingRun(taskTokens), nil,
+		WithPreSpentTokens(measuredRouterTokens))
+	if want := taskTokens + measuredRouterTokens; with.TokensUsed != want {
+		t.Fatalf("a routed plan reported %d, want %d — routing is still invisible",
+			with.TokensUsed, want)
+	}
+}
+
+// A PLAN THAT NEVER ROUTED IS UNCHANGED, byte for byte. auto_assign is off by
+// default and most plans never route at all.
+func TestAPlanThatDidNotRouteIsUnaffected(t *testing.T) {
+	for _, tokens := range []int{0, -1} {
+		report := ExecutePlan(context.Background(), routerSpendPlan(t),
+			PlanReadOnlyToolNames(), succeedingRun(1000), nil, WithPreSpentTokens(tokens))
+		if report.TokensUsed != 1000 {
+			t.Fatalf("WithPreSpentTokens(%d) changed an unrouted plan's total to %d", tokens, report.TokensUsed)
+		}
+	}
+}
+
+// THE BUDGET SEES THE SAME NUMBER THE REPORT DOES. If the report counted router
+// spend and the limit did not, "budget exhausted at N/M" would print an N
+// counting something never charged against M — two spellings of one quantity,
+// free to drift.
+func TestTheBudgetIsReducedByWhatRoutingAlreadySpent(t *testing.T) {
+	for _, tc := range []struct {
+		name     string
+		budget   int
+		preSpent int
+		want     int64
+	}{
+		{"ordinary", 1_000_000, 10_513, 989_487},
+		{"unbounded stays unbounded", 0, 10_513, 0},
+		{"nothing pre-spent", 1_000_000, 0, 1_000_000},
+		// A POSITIVE BUDGET NEVER BECOMES UNBOUNDED: limit <= 0 means "no bound"
+		// everywhere in planSpend, so a plan that has already overspent must
+		// floor at 1 and refuse its next task, not have its bound switched off.
+		{"pre-spend equals the budget", 10_513, 10_513, 1},
+		{"pre-spend exceeds the budget", 5_000, 10_513, 1},
+	} {
+		t.Run(tc.name, func(t *testing.T) {
+			if got := planSpendLimit(tc.budget, tc.preSpent); got != tc.want {
+				t.Fatalf("planSpendLimit(%d, %d) = %d, want %d", tc.budget, tc.preSpent, got, tc.want)
+			}
+		})
+	}
+}
+
+// The floor is not cosmetic: at limit 1 the very next task must be refused.
+// Switching the bound off instead would do the exact opposite of what an
+// already-overspent plan needs.
+func TestAnAlreadyOverspentPlanStillRefusesItsNextTask(t *testing.T) {
+	overspent := &planSpend{limit: planSpendLimit(5_000, 10_513)}
+	if !overspent.overPool(overspent.add(1_000, false), false) {
+		t.Fatal("a plan that had already overspent its budget accepted more work")
+	}
+	// And an unbounded plan is still unbounded after the same treatment.
+	unbounded := &planSpend{limit: planSpendLimit(0, 10_513)}
+	if unbounded.overPool(unbounded.add(9_000_000, false), false) {
+		t.Fatal("an unbounded plan grew a ceiling nobody asked for")
+	}
+}
+
+// SEEDED, NOT ADDED AT THE END. Every early return between the seed and the end
+// reports whatever TokensUsed holds, so a total corrected only on the success
+// path would be wrong on exactly the runs a reader most wants the truth about.
+func TestACancelledPlanStillReportsWhatRoutingCost(t *testing.T) {
+	ctx, cancel := context.WithCancel(context.Background())
+	run := func(_ context.Context, req PlanTaskRequest) (TaskResult, error) {
+		cancel()
+		return TaskResult{ID: req.Task.ID, Outcome: TaskCancelled, Output: "stopped"}, context.Canceled
+	}
+	report := ExecutePlan(ctx, routerSpendPlan(t), PlanReadOnlyToolNames(), run, nil,
+		WithPreSpentTokens(measuredRouterTokens))
+	if report.TokensUsed < measuredRouterTokens {
+		t.Fatalf("a cancelled plan reported %d, losing the %d routing already cost",
+			report.TokensUsed, measuredRouterTokens)
+	}
+}
+
+// BOTH EXECUTION PATHS. plan_tool runs a plan in the foreground and in the
+// background from two different call sites; wiring one and not the other would
+// make the reported total correct only for whichever the user happened to pick.
+func TestBothExecutionPathsChargeRouterSpend(t *testing.T) {
+	source := readFileForTest(t, "plan_tool.go")
+	calls := strings.Count(source, "ExecutePlanIn(")
+	charged := strings.Count(source, "WithPreSpentTokens(routerTokens)")
+	if calls != charged {
+		t.Fatalf("plan_tool.go has %d ExecutePlanIn call(s) but charges router spend on %d of them",
+			calls, charged)
+	}
+}

diff --git a/dev/zero/internal/specialist/plan_workspace_reach.go b/dev/zero/internal/specialist/plan_workspace_reach.go
--- /dev/null
+++ b/dev/zero/internal/specialist/plan_workspace_reach.go
@@ @@
+package specialist
+
+import (
+	"fmt"
+	"os"
+	"path/filepath"
+	"regexp"
+	"sort"
+	"strings"
+)
+
+// A plan that isolated into a tree its own tasks cannot read.
+//
+// THE MEASURED FAILURE. A six-task research plan was started from a directory
+// that happened to be a git repo with ONE tracked file. Five tasks asked for
+// read_file/grep/glob; the sixth also asked for exec_command, which is not in
+// planReadOnlyTools — so RequiresIsolation flipped for the WHOLE plan and every
+// task was moved into a worktree containing that one file. The tasks had been
+// pointed at absolute paths in a different tree, which was now outside their
+// sandbox, and three of them died reporting "I cannot". About 143,000 tokens,
+// and the sixth task succeeded only because asking for exec_command had raised
+// its autonomy far enough to read back out.
+//
+// Isolation itself is right: write tasks belong in a worktree. What was missing
+// is that nothing checked the worktree could serve the plan before dispatching
+// six tasks into it. resolvePlanWorkspace already refuses when isolation is
+// UNAVAILABLE; this refuses when it is available and useless.
+//
+// FAILS TOWARD RUNNING THE PLAN. A false refusal blocks work that would have
+// succeeded, so this only fires on evidence that cannot be a guess: an absolute
+// path, written in a task's own prompt, that EXISTS on disk, and that is outside
+// the workspace the task will run in. All three, or nothing happens. A path that
+// does not exist is somebody else's error; a relative path resolves against the
+// workspace and is not this function's business; a plan that never isolated
+// keeps the parent's tree and cannot have this problem at all.
+
+// absolutePathPattern finds POSIX-style absolute paths in prose.
+//
+// Deliberately loose, because the EXISTENCE check below is what makes a match
+// meaningful. It will happily match "/settings" out of a URL and "/v1/pay" out
+// of a sentence; neither exists on disk, so neither survives.
+var absolutePathPattern = regexp.MustCompile(`/[A-Za-z0-9._+@-]+(?:/[A-Za-z0-9._+@-]+)+`)
+
+// unreachablePlanPaths lists paths the plan's own prompts name that the plan's
+// workspace cannot reach. Empty for every plan that is fine — including every
+// plan that did not isolate.
+func unreachablePlanPaths(plan Plan, workspace PlanWorkspace) []string {
+	if !workspace.Isolated || strings.TrimSpace(workspace.Path) == "" {
+		return nil
+	}
+	root := resolvedPath(workspace.Path)
+	seen := map[string]bool{}
+	var unreachable []string
+	for _, task := range plan.Tasks() {
+		for _, candidate := range absolutePathPattern.FindAllString(task.Prompt, -1) {
+			path, ok := existingPath(candidate)
+			if !ok || seen[path] {
+				continue
+			}
+			seen[path] = true
+			if !pathInsideRoot(root, resolvedPath(path)) {
+				unreachable = append(unreachable, path)
+			}
+		}
+	}
+	sort.Strings(unreachable)
+	return unreachable
+}
+
+// existingPath reports the path if something is really there.
+//
+// Trailing punctuation is retried once, because a path at the end of a sentence
+// arrives as "…/plan.go." and the bare Stat would miss it — a false NEGATIVE,
+// which is the safe direction but a cheap one to reduce.
+func existingPath(candidate string) (string, bool) {
+	if _, err := os.Lstat(candidate); err == nil {
+		return candidate, true
+	}
+	trimmed := strings.TrimRight(candidate, ".,;:)]}\"'")
+	if trimmed == candidate || trimmed == "" {
+		return "", false
+	}
+	if _, err := os.Lstat(trimmed); err == nil {
+		return trimmed, true
+	}
+	return "", false
+}
+
+// resolvedPath follows symlinks so /var and /private/var are the same place.
+// Falls back to a lexical clean when it cannot resolve, which is the honest
+// answer for a path that exists but cannot be walked.
+func resolvedPath(path string) string {
+	if resolved, err := filepath.EvalSymlinks(path); err == nil {
+		return filepath.Clean(resolved)
+	}
+	return filepath.Clean(path)
+}
+
+// pathInsideRoot reports containment, SEPARATOR-AWARE: "/a/b" does not contain
+// "/a/bc", which a bare strings.HasPrefix would get wrong.
+func pathInsideRoot(root, path string) bool {
+	if root == "" || path == "" {
+		return false
+	}
+	if path == root {
+		return true
+	}
+	return strings.HasPrefix(path, strings.TrimSuffix(root, string(filepath.Separator))+string(filepath.Separator))
+}
+
+// planIsolationTrigger names the first task and tool that made the plan need a
+// worktree, so the refusal can say WHY it isolated rather than leaving the
+// author to work it out. Isolation is a plan-level property and one task's
+// grant decides it for all of them, which is exactly the surprising part.
+func planIsolationTrigger(plan Plan) (taskID, tool string) {
+	for _, task := range plan.Tasks() {
+		for _, name := range task.Tools {
+			if !planReadOnlyTools[name] {
+				return task.ID, name
+			}
+		}
+	}
+	return "", ""
+}
+
+// refuseUnreachableWorkspace turns the finding into the error a caller sees.
+//
+// IT NAMES BOTH FIXES, because the author cannot be expected to know that one
+// task's tool grant moved every other task's workspace: run from the tree the
+// paths are in, or drop the tool that forced isolation and let the plan stay
+// where its parent is.
+func refuseUnreachableWorkspace(plan Plan, workspace PlanWorkspace, unreachable []string) error {
+	shown := unreachable
+	const maxShown = 3
+	more := ""
+	if len(shown) > maxShown {
+		more = fmt.Sprintf(" (and %d more)", len(shown)-maxShown)
+		shown = shown[:maxShown]
+	}
+	because := ""
+	if taskID, tool := planIsolationTrigger(plan); taskID != "" {
+		because = fmt.Sprintf(" The plan runs in a worktree because task %q asks for %q, which is not a read-only tool — and isolation applies to every task, not just that one.", taskID, tool)
+	}
+	return fmt.Errorf(
+		"plan %q would run in an isolated worktree at %s, and its tasks name %s that the worktree does not contain: %s%s.%s "+
+			"Every task reading those paths would be refused by the sandbox. "+
+			"Either start the run from the tree those paths are in, or remove the write tool so the plan stays read-only and runs where its parent does",
+		plan.Name(), workspace.Path, pluralPaths(len(unreachable)), strings.Join(shown, ", "), more, because)
+}
+
+func pluralPaths(n int) string {
+	if n == 1 {
+		return "a path"
+	}
+	return "paths"
+}
diff --git a/dev/zero/internal/specialist/plan_worktree.go b/dev/zero/internal/specialist/plan_worktree.go
--- a/dev/zero/internal/specialist/plan_worktree.go
+++ b/dev/zero/internal/specialist/plan_worktree.go
@@ @@
 	if workspace.Release == nil {
 		workspace.Release = func() {}
 	}
+	// AND THE WORKTREE MUST BE ABLE TO SERVE THE PLAN. The two refusals above
+	// cover isolation being unavailable or dishonest; this covers it being
+	// available, honest, and useless — a worktree of the wrong tree, which a
+	// six-task plan discovered one failed task at a time. See
+	// unreachablePlanPaths for the evidence bar this holds itself to.
+	//
+	// RELEASED BEFORE RETURNING. A refusal that left the worktree on disk would
+	// leak one directory per attempt, and the caller has no handle to clean up
+	// something it was never given.
+	if unreachable := unreachablePlanPaths(plan, workspace); len(unreachable) > 0 {
+		workspace.Release()
+		return PlanWorkspace{}, refuseUnreachableWorkspace(plan, workspace, unreachable)
+	}
 	return workspace, nil
 }
diff --git a/dev/zero/internal/specialist/plan_workspace_reach_test.go b/dev/zero/internal/specialist/plan_workspace_reach_test.go
--- /dev/null
+++ b/dev/zero/internal/specialist/plan_workspace_reach_test.go
@@ @@
+package specialist
+
+import (
+	"context"
+	"errors"
+	"os"
+	"path/filepath"
+	"strings"
+	"testing"
+)
+
+// THE MEASURED FAILURE, REPRODUCED. A six-task plan started from a directory
+// that was a git repo with one tracked file; one task asked for exec_command, so
+// every task was moved into a worktree of that directory; the five reading a
+// different tree were refused by the sandbox and three died reporting "I
+// cannot". This is that shape, in miniature.
+func reachPlan(t *testing.T, prompt string, tools []string) Plan {
+	t.Helper()
+	anyTools := make([]any, 0, len(tools))
+	for _, name := range tools {
+		anyTools = append(anyTools, name)
+	}
+	return mustParsePlan(t, map[string]any{
+		"name": "swarm-session-id-leak",
+		"tasks": []any{
+			map[string]any{"id": "finder", "prompt": prompt, "tools": anyTools},
+			map[string]any{"id": "runner", "prompt": "run the tests", "tools": []any{"read_file", "exec_command"}},
+		},
+		"budget": map[string]any{"max_workers": float64(1)},
+	}, Limits{MaxTasks: 20, ParentTools: []string{"read_file", "grep", "glob", "exec_command"}})
+}
+
+func isolatedWorkspace(path string) PlanWorkspace {
+	return PlanWorkspace{Path: path, Isolated: true, Describe: "worktree", Release: func() {}}
+}
+
+func TestAPlanIsRefusedWhenItsWorktreeCannotReachThePathsItNames(t *testing.T) {
+	// The tree the tasks were pointed at.
+	realTree := t.TempDir()
+	target := filepath.Join(realTree, "internal", "swarm", "tools.go")
+	if err := os.MkdirAll(filepath.Dir(target), 0o755); err != nil {
+		t.Fatal(err)
+	}
+	if err := os.WriteFile(target, []byte("package swarm\n"), 0o600); err != nil {
+		t.Fatal(err)
+	}
+	// The worktree the plan actually got: a different tree, with one file.
+	worktree := t.TempDir()
+	if err := os.WriteFile(filepath.Join(worktree, "gauntlet_test.txt"), []byte("test"), 0o600); err != nil {
+		t.Fatal(err)
+	}
+
+	plan := reachPlan(t, "Read "+target+" and report every render site.", []string{"read_file", "grep"})
+	unreachable := unreachablePlanPaths(plan, isolatedWorkspace(worktree))
+	if len(unreachable) == 0 {
+		t.Fatal("a plan naming a path outside its own worktree was allowed to dispatch")
+	}
+	if unreachable[0] != target {
+		t.Fatalf("named %q, want %q", unreachable[0], target)
+	}
+
+	// The refusal must be ACTIONABLE: name the path, name why it isolated, and
+	// name both ways out.
+	err := refuseUnreachableWorkspace(plan, isolatedWorkspace(worktree), unreachable)
+	text := err.Error()
+	for _, want := range []string{target, worktree, "exec_command", "runner", "read-only"} {
+		if !strings.Contains(text, want) {
+			t.Errorf("the refusal never mentions %q:\n%s", want, text)
+		}
+	}
+}
+
+// FAILS TOWARD RUNNING THE PLAN. Each of these must NOT fire — a false refusal
+// blocks work that would have succeeded.
+func TestTheReachGuardStaysQuietWithoutUnambiguousEvidence(t *testing.T) {
+	worktree := t.TempDir()
+	inside := filepath.Join(worktree, "internal", "app.go")
+	if err := os.MkdirAll(filepath.Dir(inside), 0o755); err != nil {
+		t.Fatal(err)
+	}
+	if err := os.WriteFile(inside, []byte("package app\n"), 0o600); err != nil {
+		t.Fatal(err)
+	}
+
+	for _, tc := range []struct {
+		name      string
+		prompt    string
+		workspace PlanWorkspace
+	}{
+		{
+			// The overwhelmingly common case: no isolation, so the parent's tree
+			// is the workspace and nothing was ever relocated.
+			name:      "a plan that never isolated",
+			prompt:    "Read /definitely/outside/whatever.go",
+			workspace: PlanWorkspace{},
+		},
+		{
+			name:      "a path inside the worktree",
+			prompt:    "Read " + inside + " carefully.",
+			workspace: isolatedWorkspace(worktree),
+		},
+		{
+			// Somebody else's error. A path that is not there would fail for its
+			// own reasons and this guard must not claim it.
+			name:      "a path that does not exist",
+			prompt:    "Read /Users/nobody/dev/ghost/internal/thing.go",
+			workspace: isolatedWorkspace(worktree),
+		},
+		{
+			// Prose is full of slash-shaped things that are not paths.
+			name:      "a URL path and an endpoint",
+			prompt:    "See https://ollama.com/settings and the /v1/pay endpoint, then read app.go",
+			workspace: isolatedWorkspace(worktree),
+		},
+		{
+			name:      "relative paths resolve against the workspace",
+			prompt:    "Read internal/app.go and internal/swarm/tools.go",
+			workspace: isolatedWorkspace(worktree),
+		},
+	} {
+		t.Run(tc.name, func(t *testing.T) {
+			plan := reachPlan(t, tc.prompt, []string{"read_file", "grep"})
+			if got := unreachablePlanPaths(plan, tc.workspace); len(got) > 0 {
+				t.Fatalf("refused a plan that would have worked: %v", got)
+			}
+		})
+	}
+}
+
+// A path at the end of a sentence arrives with punctuation attached; missing it
+// is safe but cheap to avoid.
+func TestAPathFollowedByPunctuationIsStillFound(t *testing.T) {
+	realTree := t.TempDir()
+	target := filepath.Join(realTree, "streamer.go")
+	if err := os.WriteFile(target, []byte("package x\n"), 0o600); err != nil {
+		t.Fatal(err)
+	}
+	worktree := t.TempDir()
+
+	for _, suffix := range []string{".", ",", ")", "'", `"`, ";"} {
+		plan := reachPlan(t, "Open "+target+suffix+" and report.", []string{"read_file"})
+		got := unreachablePlanPaths(plan, isolatedWorkspace(worktree))
+		if len(got) != 1 || got[0] != target {
+			t.Errorf("suffix %q: got %v, want [%s]", suffix, got, target)
+		}
+	}
+}
+
+// "/a/b" does not contain "/a/bc". A bare prefix check gets this wrong and would
+// wave through a plan pointed at a sibling directory.
+func TestContainmentIsSeparatorAware(t *testing.T) {
+	for _, tc := range []struct {
+		root, path string
+		want       bool
+	}{
+		{"/a/b", "/a/b", true},
+		{"/a/b", "/a/b/c", true},
+		{"/a/b", "/a/bc", false},
+		{"/a/b", "/a/bc/d", false},
+		{"/a/b/", "/a/b/c", true},
+		{"", "/a", false},
+		{"/a", "", false},
+	} {
+		if got := pathInsideRoot(tc.root, tc.path); got != tc.want {
+			t.Errorf("pathInsideRoot(%q, %q) = %v, want %v", tc.root, tc.path, got, tc.want)
+		}
+	}
+}
+
+// The refusal must name the tool that caused isolation, because one task's grant
+// silently decides the workspace for every other task — the surprising part.
+func TestTheTriggeringTaskAndToolAreNamed(t *testing.T) {
+	plan := reachPlan(t, "read something", []string{"read_file", "grep"})
+	taskID, tool := planIsolationTrigger(plan)
+	if taskID != "runner" || tool != "exec_command" {
+		t.Fatalf("trigger = (%q, %q), want (\"runner\", \"exec_command\")", taskID, tool)
+	}
+
+	// A wholly read-only plan has no trigger to name.
+	readOnly := mustParsePlan(t, map[string]any{
+		"name":   "p",
+		"tasks":  []any{map[string]any{"id": "a", "prompt": "look", "tools": []any{"read_file"}}},
+		"budget": map[string]any{"max_workers": float64(1)},
+	}, Limits{MaxTasks: 20, ParentTools: PlanReadOnlyToolNames()})
+	if id, name := planIsolationTrigger(readOnly); id != "" || name != "" {
+		t.Fatalf("a read-only plan reported a trigger (%q, %q)", id, name)
+	}
+}
+
+// END TO END through resolvePlanWorkspace: the refusal must arrive from the one
+// function both call sites use, and the worktree must not be left on disk.
+func TestResolvePlanWorkspaceRefusesAndReleasesTheWorktree(t *testing.T) {
+	realTree := t.TempDir()
+	target := filepath.Join(realTree, "tools.go")
+	if err := os.WriteFile(target, []byte("package x\n"), 0o600); err != nil {
+		t.Fatal(err)
+	}
+	worktree := t.TempDir()
+
+	released := false
+	isolate := func(context.Context, string) (PlanWorkspace, error) {
+		return PlanWorkspace{
+			Path: worktree, Isolated: true, Describe: "worktree",
+			Release: func() { released = true },
+		}, nil
+	}
+	plan := reachPlan(t, "Read "+target+" and report.", []string{"read_file"})
+
+	got, err := resolvePlanWorkspace(context.Background(), plan, isolate)
+	if err == nil {
+		t.Fatal("the plan was allowed to run in a worktree it cannot read from")
+	}
+	if got.Path != "" {
+		t.Fatalf("a refused resolution still handed back a workspace: %+v", got)
+	}
+	if !released {
+		t.Fatal("the worktree was left on disk: one leaked directory per attempt")
+	}
+	if !strings.Contains(err.Error(), target) {
+		t.Fatalf("the refusal does not name the unreachable path: %v", err)
+	}
+}
+
+// A plan whose worktree DOES serve it must still run, and must keep its
+// workspace — the guard is a check, not a new refusal path for ordinary plans.
+func TestAWorktreeThatServesThePlanIsStillAccepted(t *testing.T) {
+	worktree := t.TempDir()
+	inside := filepath.Join(worktree, "tools.go")
+	if err := os.WriteFile(inside, []byte("package x\n"), 0o600); err != nil {
+		t.Fatal(err)
+	}
+	isolate := func(context.Context, string) (PlanWorkspace, error) {
+		return PlanWorkspace{Path: worktree, Isolated: true, Describe: "worktree", Release: func() {}}, nil
+	}
+	plan := reachPlan(t, "Read "+inside+" and report.", []string{"read_file"})
+
+	got, err := resolvePlanWorkspace(context.Background(), plan, isolate)
+	if err != nil {
+		t.Fatalf("a usable worktree was refused: %v", err)
+	}
+	if got.Path != worktree || !got.Isolated {
+		t.Fatalf("workspace = %+v, want the worktree", got)
+	}
+}
+
+// The pre-existing refusals must survive: this adds a check, it does not replace
+// the ones that were already there.
+func TestTheExistingWorkspaceRefusalsStillFire(t *testing.T) {
+	writePlan := reachPlan(t, "read something", []string{"read_file"})
+
+	if _, err := resolvePlanWorkspace(context.Background(), writePlan, nil); err == nil {
+		t.Fatal("a write-capable plan ran with no isolator")
+	}
+	dishonest := func(context.Context, string) (PlanWorkspace, error) {
+		return PlanWorkspace{Path: "", Isolated: false}, nil
+	}
+	if _, err := resolvePlanWorkspace(context.Background(), writePlan, dishonest); err == nil {
+		t.Fatal("an isolator returning no isolation was believed")
+	}
+	failing := func(context.Context, string) (PlanWorkspace, error) {
+		return PlanWorkspace{}, errors.New("no git here")
+	}
+	if _, err := resolvePlanWorkspace(context.Background(), writePlan, failing); err == nil {
+		t.Fatal("a failed isolator was ignored")
+	}
+}

diff --git a/dev/zero/internal/specialist/plan_workspace_reach.go b/dev/zero/internal/specialist/plan_workspace_reach.go
--- a/dev/zero/internal/specialist/plan_workspace_reach.go
+++ b/dev/zero/internal/specialist/plan_workspace_reach.go
@@ @@
+// THE SECOND SHAPE OF THE SAME FAILURE, and the one the absolute-path check
+// above misses entirely.
+//
+// A later run of the same plan named its targets RELATIVELY — "internal/
+// specialist/", "internal/swarm/" — plus a commit sha. Not one absolute path
+// anywhere, so unreachablePlanPaths found nothing and six tasks were dispatched
+// into a worktree holding a single file. The child said it plainly: "no Go files
+// anywhere in the workspace… the only reachable commit is 3177684c".
+//
+// A relative path is far weaker evidence than an absolute one: prose is full of
+// slash-shaped things, and a path that does not exist yet is exactly what a
+// scaffolding task is for. So this fires only on a CONJUNCTION that a working
+// plan cannot satisfy:
+//
+//   - the plan isolated, and
+//   - it names at least two path-shaped tokens, and
+//   - NOT ONE of them exists in the workspace, and
+//   - the workspace is bare.
+//
+// A plan genuinely about its own tree resolves at least one token. A scaffolding
+// plan creating new files runs in a worktree of a real repo, which is not bare.
+// Both conditions have to be wrong at once, which is what the measured failure
+// looked like and what an ordinary run does not.
+
+// relativePathPattern matches path-shaped tokens.
+//
+// DELIBERATELY NARROWER THAN "has a slash", because "and/or", "read/write" and
+// "input/output" are not paths and appear in prompts constantly. A token
+// qualifies only if it ends in a slash, carries a file extension, or has three
+// or more segments — which those three do not.
+var relativePathPattern = regexp.MustCompile(`\b[A-Za-z0-9._-]+/(?:[A-Za-z0-9._-]+/)*[A-Za-z0-9._-]*`)
+
+// urlPattern strips URLs before scanning, so "https://ollama.com/settings" does
+// not contribute "ollama.com/settings" as a path.
+var urlPattern = regexp.MustCompile(`\b[a-zA-Z][a-zA-Z0-9+.-]*://\S+`)
+
+// bareWorkspaceMaxEntries is how few visible entries make a workspace "bare".
+// The measured failure had exactly one — gauntlet_test.txt. A checkout a plan
+// could actually work in has many more, so this does not need to be near the
+// boundary and deliberately is not.
+const bareWorkspaceMaxEntries = 2
+
+// planNamesNothingPresent reports the tokens a plan names when NONE of them are
+// in the workspace and the workspace is bare.
+func planNamesNothingPresent(plan Plan, workspace PlanWorkspace) ([]string, bool) {
+	if !workspace.Isolated || strings.TrimSpace(workspace.Path) == "" {
+		return nil, false
+	}
+	if !workspaceIsBare(workspace.Path) {
+		return nil, false
+	}
+	seen := map[string]bool{}
+	var named []string
+	for _, task := range plan.Tasks() {
+		text := urlPattern.ReplaceAllString(task.Prompt, " ")
+		for _, token := range relativePathPattern.FindAllString(text, -1) {
+			token = strings.TrimRight(token, ".,;:)]}\"'")
+			if !pathShapedToken(token) || seen[token] {
+				continue
+			}
+			seen[token] = true
+			// ANY hit ends it: the workspace is serving the plan after all, and
+			// bare or not, this is not the failure being detected.
+			if _, err := os.Lstat(filepath.Join(workspace.Path, filepath.FromSlash(token))); err == nil {
+				return nil, false
+			}
+			named = append(named, token)
+		}
+	}
+	if len(named) < 2 {
+		return nil, false
+	}
+	sort.Strings(named)
+	return named, true
+}
+
+// pathShapedToken keeps only tokens that read as file paths rather than as
+// ordinary prose containing a slash.
+func pathShapedToken(token string) bool {
+	if token == "" || strings.HasPrefix(token, "/") {
+		return false
+	}
+	if strings.HasSuffix(token, "/") {
+		return true
+	}
