+		mixAgent("big", specialistRunning), mixAgent("big", specialistRunning),
+		mixAgent("big", specialistRunning), mixAgent("big", specialistRunning),
+		mixAgent("big", specialistRunning), mixAgent("big", specialistRunning),
+		mixAgent("big", specialistRunning),
