diff --git a/dev/zero/cmd/zero-xplat-provider/main.go b/dev/zero/cmd/zero-xplat-provider/main.go
--- /dev/null
+++ b/dev/zero/cmd/zero-xplat-provider/main.go
@@ @@
+// Command zero-xplat-provider is a deterministic OpenAI-compatible provider
+// used by the cross-platform feature runner.
+//
+// Real feature runs need a provider, but a real provider makes the run
+// non-deterministic and credential-dependent — neither of which survives CI on
+// three operating systems. This serves a scripted sequence of turns instead, so
+// the same scenario produces byte-identical model behavior on macOS, Linux, and
+// Windows and any divergence in the result is attributable to the OS rather
+// than to the model.
+//
+// It prints its listening port on the first line of stdout so the caller can
+// bind to port 0 and avoid races on a fixed port.
+package main
+
+import (
+	"encoding/json"
+	"fmt"
+	"net"
+	"net/http"
+	"os"
+	"sync"
+)
+
+// Turn is one scripted model response. A Turn either calls a tool or emits
+// text; Tool takes precedence when both are set.
+type Turn struct {
+	Text string `json:"text,omitempty"`
+	Tool *struct {
+		Name string `json:"name"`
+		Args string `json:"args"`
+	} `json:"tool,omitempty"`
+}
+
+func main() {
+	if len(os.Args) < 2 {
+		fmt.Fprintln(os.Stderr, "usage: zero-xplat-provider <script.json>")
+		os.Exit(2)
+	}
+	script, err := loadScript(os.Args[1])
+	if err != nil {
+		fmt.Fprintln(os.Stderr, "zero-xplat-provider: "+err.Error())
+		os.Exit(1)
+	}
+
+	server := &scriptedServer{script: script}
+	mux := http.NewServeMux()
+	mux.HandleFunc("/v1/models", server.handleModels)
+	mux.HandleFunc("/v1/chat/completions", server.handleCompletions)
+
+	listener, err := net.Listen("tcp", "127.0.0.1:0")
+	if err != nil {
+		fmt.Fprintln(os.Stderr, "zero-xplat-provider: "+err.Error())
+		os.Exit(1)
+	}
+	// The port line must be flushed before the caller's read, and must be the
+	// only thing on stdout, so the runner can parse it without a delimiter.
+	fmt.Println(listener.Addr().(*net.TCPAddr).Port)
+	if err := http.Serve(listener, mux); err != nil {
+		fmt.Fprintln(os.Stderr, "zero-xplat-provider: "+err.Error())
+		os.Exit(1)
+	}
+}
+
+func loadScript(path string) ([]Turn, error) {
+	data, err := os.ReadFile(path)
+	if err != nil {
+		return nil, err
+	}
+	var script []Turn
+	if err := json.Unmarshal(data, &script); err != nil {
+		return nil, fmt.Errorf("parse %s: %w", path, err)
+	}
+	return script, nil
+}
+
+type scriptedServer struct {
+	mu     sync.Mutex
+	script []Turn
+	index  int
+}
+
+// next returns the turn for this request. Once the script is exhausted it
+// returns a terminal text turn rather than erroring, so a scenario that takes
+// more turns on one OS than another fails on its assertions — which name the
+// actual difference — instead of on a provider error, which would not.
+func (s *scriptedServer) next() Turn {
+	s.mu.Lock()
+	defer s.mu.Unlock()
+	if s.index >= len(s.script) {
+		return Turn{Text: "script exhausted"}
+	}
+	turn := s.script[s.index]
+	s.index++
+	return turn
+}
+
+func (s *scriptedServer) handleModels(w http.ResponseWriter, _ *http.Request) {
+	w.Header().Set("Content-Type", "application/json")
+	_ = json.NewEncoder(w).Encode(map[string]any{
+		"object": "list",
+		"data": []map[string]any{
+			{"id": ModelID, "object": "model", "owned_by": "zero-xplat"},
+		},
+	})
+}
+
+// ModelID is the single model the scripted provider serves. Scenarios name it
+// so the run never depends on the developer's configured model.
+const ModelID = "zero-xplat-70b"
+
+func (s *scriptedServer) handleCompletions(w http.ResponseWriter, _ *http.Request) {
+	turn := s.next()
+	w.Header().Set("Content-Type", "text/event-stream")
+	w.Header().Set("Cache-Control", "no-cache")
+	flusher, _ := w.(http.Flusher)
+
+	emit := func(delta map[string]any, finish string) {
+		choice := map[string]any{"index": 0, "delta": delta}
+		if finish != "" {
+			choice["finish_reason"] = finish
+		}
+		payload, err := json.Marshal(map[string]any{
+			"id":      "chatcmpl-zero-xplat",
+			"object":  "chat.completion.chunk",
+			"model":   ModelID,
+			"choices": []map[string]any{choice},
+		})
+		if err != nil {
+			return
+		}
+		fmt.Fprintf(w, "data: %s\n\n", payload)
+		if flusher != nil {
+			flusher.Flush()
+		}
+	}
+
+	if turn.Tool != nil {
+		emit(map[string]any{"tool_calls": []map[string]any{{
+			"index": 0,
+			"id":    "call_zero_xplat",
+			"type":  "function",
+			"function": map[string]any{
+				"name":      turn.Tool.Name,
+				"arguments": turn.Tool.Args,
+			},
+		}}}, "tool_calls")
+	} else {
+		emit(map[string]any{"content": turn.Text}, "stop")
+	}
+	fmt.Fprint(w, "data: [DONE]\n\n")
+	if flusher != nil {
+		flusher.Flush()
+	}
+}
diff --git a/dev/zero/internal/xplat/xplat.go b/dev/zero/internal/xplat/xplat.go
--- /dev/null
+++ b/dev/zero/internal/xplat/xplat.go
@@ @@
+// Package xplat runs complete Zero features against the real built binary on
+// whichever operating system it is executing on, so the same scenario can be
+// compared across macOS, Linux, and Windows.
+//
+// This is deliberately not a unit-test layer. Zero carries 28 Windows-specific
+// source files against 1 for macOS, plus 57 runtime.GOOS branches across 21
+// packages; the divergence that matters lives in process spawning, path
+// handling, and sandbox enforcement, none of which a compile-time check or a
+// table test exercises. A scenario here builds a workspace, starts a scripted
+// provider, executes `zero exec`, and asserts on the observable result: exit
+// code, output, and the files actually left on disk.
+//
+// Determinism comes from cmd/zero-xplat-provider, which serves a fixed turn
+// script instead of a model. Any difference between two platforms is therefore
+// attributable to the platform.
+package xplat
+
+import (
+	"bufio"
+	"context"
+	"encoding/json"
+	"errors"
+	"fmt"
+	"io"
+	"os"
+	"os/exec"
+	"path/filepath"
+	"runtime"
+	"sort"
+	"strconv"
+	"strings"
+	"time"
+)
+
+// providerCredentialEnv lists the variables that must not reach a scenario.
+// A developer's real credentials would make the run depend on a live provider,
+// which is the one thing a reproducible cross-platform comparison cannot have.
+// Mirrors perfbench's offline environment for the same reason.
+var providerCredentialEnv = []string{
+	"ZERO_PROVIDER", "ZERO_PROVIDER_COMMAND",
+	"OPENAI_API_KEY", "OPENAI_BASE_URL", "OPENAI_MODEL",
+	"ANTHROPIC_API_KEY", "ANTHROPIC_BASE_URL", "ANTHROPIC_MODEL",
+	"GEMINI_API_KEY", "GEMINI_BASE_URL", "GEMINI_MODEL",
+	"GOOGLE_API_KEY", "GOOGLE_BASE_URL", "GOOGLE_MODEL",
+	"OPENROUTER_API_KEY", "ZERO_OPENROUTER_BASE_URL",
+}
+
+// Scenario is one feature run, expressed identically for every platform.
+// Only SkipOS and the expectations may acknowledge that platforms differ; the
+// command and inputs are shared, which is what makes a divergence meaningful.
+type Scenario struct {
+	Name        string            `json:"name"`
+	Description string            `json:"description,omitempty"`
+	// Script is the provider turn sequence, handed to zero-xplat-provider.
+	Script json.RawMessage `json:"script"`
+	// Args are appended to the zero binary invocation. The workspace is passed
+	// separately via -C so scenarios never hard-code a path.
+	Args []string `json:"args"`
+	// Files seeds the workspace before the run. Keys use forward slashes and
+	// are converted to the host separator.
+	Files map[string]string `json:"files,omitempty"`
+	// Env adds scenario-specific variables after the credential scrub.
+	Env map[string]string `json:"env,omitempty"`
+	// SkipOS names runtime.GOOS values this scenario cannot run on, with the
+	// reason recorded in the report rather than silently omitted.
+	SkipOS map[string]string `json:"skip_os,omitempty"`
+	// TimeoutSeconds bounds the run; 0 uses DefaultScenarioTimeout.
+	TimeoutSeconds int    `json:"timeout_seconds,omitempty"`
+	Expect         Expect `json:"expect"`
+}
+
+// Expect is what the scenario asserts about the completed run.
+type Expect struct {
+	ExitCode          *int         `json:"exit_code,omitempty"`
+	StdoutContains    []string     `json:"stdout_contains,omitempty"`
+	StdoutNotContains []string     `json:"stdout_not_contains,omitempty"`
+	OutputNotContains []string     `json:"output_not_contains,omitempty"`
+	Files             []FileExpect `json:"files,omitempty"`
+}
+
+// FileExpect asserts on a workspace file after the run.
+type FileExpect struct {
+	Path        string `json:"path"`
+	Absent      bool   `json:"absent,omitempty"`
+	Contains    string `json:"contains,omitempty"`
+	NotContains string `json:"not_contains,omitempty"`
+}
+
+// DefaultScenarioTimeout bounds a single feature run. A scenario that hangs on
+// one platform is a finding, so the timeout is generous enough that expiry
+// means something rather than being routine flake.
+const DefaultScenarioTimeout = 90 * time.Second
+
+// Status values for a scenario on one platform.
+const (
+	StatusPassed  = "passed"
+	StatusFailed  = "failed"
+	StatusSkipped = "skipped"
+)
+
+// ScenarioResult is one scenario's outcome on this platform.
+type ScenarioResult struct {
+	Name       string   `json:"name"`
+	Status     string   `json:"status"`
+	RuntimeMS  int64    `json:"runtime_ms"`
+	ExitCode   int      `json:"exit_code"`
+	Failures   []string `json:"failures,omitempty"`
+	SkipReason string   `json:"skip_reason,omitempty"`
+	Stdout     string   `json:"stdout,omitempty"`
+	Stderr     string   `json:"stderr,omitempty"`
+	Artifacts  []string `json:"artifacts,omitempty"`
+}
+
+// PlatformReport is the normalized result for one operating system. Reports
+// from three platforms merge into the cross-platform comparison.
+type PlatformReport struct {
+	OS         string           `json:"os"`
+	Arch       string           `json:"arch"`
+	ZeroBinary string           `json:"zero_binary"`
+	Version    string           `json:"version,omitempty"`
+	StartedAt  string           `json:"started_at"`
+	RuntimeMS  int64            `json:"runtime_ms"`
+	Status     string           `json:"status"`
+	Passed     int              `json:"passed"`
+	Failed     int              `json:"failed"`
+	Skipped    int              `json:"skipped"`
+	Scenarios  []ScenarioResult `json:"scenarios"`
+}
+
+// Options configures a run.
+type Options struct {
+	RootDir        string
+	ZeroBinary     string
+	ProviderBinary string
+	ScenarioDir    string
+	WorkDir        string
+	Filter         string
+	KeepWorkspaces bool
+	Stdout         io.Writer
+}
+
+// Run executes every scenario on the current platform and returns the report.
+// It returns a non-nil error only when the run could not be performed at all;
+// a scenario that fails its assertions is reported, not returned as an error,
+// because the caller needs the other scenarios' results too.
+func Run(ctx context.Context, options Options) (PlatformReport, error) {
+	started := time.Now()
+	if options.Stdout == nil {
+		options.Stdout = io.Discard
+	}
+	rootDir, err := resolveRootDir(options.RootDir)
+	if err != nil {
+		return PlatformReport{}, err
+	}
+	zeroBinary := options.ZeroBinary
+	if strings.TrimSpace(zeroBinary) == "" {
+		zeroBinary = DefaultZeroBinary(rootDir)
+	}
+	if _, err := os.Stat(zeroBinary); err != nil {
+		return PlatformReport{}, fmt.Errorf("zero binary not found at %s: run `go run ./cmd/zero-release build` first", zeroBinary)
+	}
+	providerBinary := options.ProviderBinary
+	if strings.TrimSpace(providerBinary) == "" {
+		providerBinary = DefaultProviderBinary(rootDir)
+	}
+	if _, err := os.Stat(providerBinary); err != nil {
+		return PlatformReport{}, fmt.Errorf("scripted provider not found at %s: build ./cmd/zero-xplat-provider first", providerBinary)
+	}
+	scenarioDir := options.ScenarioDir
+	if strings.TrimSpace(scenarioDir) == "" {
+		scenarioDir = filepath.Join(rootDir, "testdata", "xplat")
+	}
+	workDir := options.WorkDir
+	if strings.TrimSpace(workDir) == "" {
+		workDir = DefaultWorkDir(rootDir)
+	}
+
+	scenarios, err := LoadScenarios(scenarioDir, options.Filter)
+	if err != nil {
+		return PlatformReport{}, err
+	}
+	if len(scenarios) == 0 {
+		return PlatformReport{}, fmt.Errorf("no scenarios matched in %s", scenarioDir)
+	}
+
+	report := PlatformReport{
+		OS:         runtime.GOOS,
+		Arch:       runtime.GOARCH,
+		ZeroBinary: zeroBinary,
+		Version:    binaryVersion(ctx, zeroBinary),
+		StartedAt:  started.UTC().Format(time.RFC3339),
+	}
+	for _, scenario := range scenarios {
+		result := runScenario(ctx, scenario, runConfig{
+			zeroBinary:     zeroBinary,
+			providerBinary: providerBinary,
+			workDir:        workDir,
+			keepWorkspace:  options.KeepWorkspaces,
+		})
+		switch result.Status {
+		case StatusPassed:
+			report.Passed++
+		case StatusSkipped:
+			report.Skipped++
+		default:
+			report.Failed++
+		}
+		report.Scenarios = append(report.Scenarios, result)
+		fmt.Fprintln(options.Stdout, formatScenarioLine(result))
+	}
+	report.RuntimeMS = time.Since(started).Milliseconds()
+	report.Status = StatusPassed
+	if report.Failed > 0 {
+		report.Status = StatusFailed
+	}
+	return report, nil
+}
+
+type runConfig struct {
+	zeroBinary     string
+	providerBinary string
+	workDir        string
+	keepWorkspace  bool
+}
+
+func runScenario(ctx context.Context, scenario Scenario, config runConfig) ScenarioResult {
+	result := ScenarioResult{Name: scenario.Name}
+	if reason, skipped := scenario.SkipOS[runtime.GOOS]; skipped {
+		result.Status = StatusSkipped
+		result.SkipReason = reason
+		return result
+	}
+
+	started := time.Now()
+	workspace := filepath.Join(config.workDir, scenario.Name)
+	if err := resetDir(workspace); err != nil {
+		return failScenario(result, started, "prepare workspace: "+err.Error())
+	}
+	if !config.keepWorkspace {
+		defer func() { _ = os.RemoveAll(workspace) }()
+	}
+	configHome := filepath.Join(workspace, ".xplat-config")
+	if err := os.MkdirAll(configHome, 0o755); err != nil {
+		return failScenario(result, started, "prepare config dir: "+err.Error())
+	}
+	source := filepath.Join(workspace, "src")
+	if err := os.MkdirAll(source, 0o755); err != nil {
+		return failScenario(result, started, "prepare source dir: "+err.Error())
+	}
+	for name, content := range scenario.Files {
+		path := filepath.Join(source, filepath.FromSlash(name))
+		if err := os.MkdirAll(filepath.Dir(path), 0o755); err != nil {
+			return failScenario(result, started, "seed "+name+": "+err.Error())
+		}
+		if err := os.WriteFile(path, []byte(content), 0o644); err != nil {
+			return failScenario(result, started, "seed "+name+": "+err.Error())
+		}
+	}
+
+	scriptPath := filepath.Join(workspace, "script.json")
+	script := scenario.Script
+	if len(script) == 0 {
+		script = json.RawMessage("[]")
+	}
+	if err := os.WriteFile(scriptPath, script, 0o644); err != nil {
+		return failScenario(result, started, "write provider script: "+err.Error())
+	}
+
+	provider, port, err := startProvider(ctx, config.providerBinary, scriptPath)
+	if err != nil {
+		return failScenario(result, started, "start scripted provider: "+err.Error())
+	}
+	defer stopProvider(provider)
+
+	timeout := DefaultScenarioTimeout
+	if scenario.TimeoutSeconds > 0 {
+		timeout = time.Duration(scenario.TimeoutSeconds) * time.Second
+	}
+	runCtx, cancel := context.WithTimeout(ctx, timeout)
+	defer cancel()
+
+	args := append([]string{"-C", source}, scenario.Args...)
+	command := exec.CommandContext(runCtx, config.zeroBinary, args...)
+	command.Dir = source
+	command.Env = scenarioEnv(port, configHome, scenario.Env)
+	// The child must die with the context rather than outliving it; a hung
+	// feature on one platform would otherwise stall the whole matrix.
+	command.WaitDelay = 5 * time.Second
+	var stdout, stderr strings.Builder
+	command.Stdout = &stdout
+	command.Stderr = &stderr
+
+	runErr := command.Run()
+	result.RuntimeMS = time.Since(started).Milliseconds()
+	result.Stdout = stdout.String()
+	result.Stderr = stderr.String()
+	result.ExitCode = exitCodeOf(runErr)
+
+	if errors.Is(runCtx.Err(), context.DeadlineExceeded) {
+		return finishScenario(result, []string{fmt.Sprintf("timed out after %s", timeout)})
+	}
+	return finishScenario(result, assert(scenario.Expect, result, source))
+}
+
+// assert checks every expectation and returns all failures rather than the
+// first. On a cross-platform run the full set is the useful signal: knowing a
+// file is missing AND the exit code was non-zero says more than either alone.
+func assert(expect Expect, result ScenarioResult, workspace string) []string {
+	var failures []string
+	if expect.ExitCode != nil && result.ExitCode != *expect.ExitCode {
+		failures = append(failures, fmt.Sprintf("exit code = %d, want %d", result.ExitCode, *expect.ExitCode))
+	}
+	for _, want := range expect.StdoutContains {
+		if !strings.Contains(result.Stdout, want) {
+			failures = append(failures, fmt.Sprintf("stdout missing %q", want))
+		}
+	}
+	for _, unwanted := range expect.StdoutNotContains {
+		if strings.Contains(result.Stdout, unwanted) {
+			failures = append(failures, fmt.Sprintf("stdout contains %q", unwanted))
+		}
+	}
+	combined := result.Stdout + result.Stderr
+	for _, unwanted := range expect.OutputNotContains {
+		if strings.Contains(combined, unwanted) {
+			failures = append(failures, fmt.Sprintf("output contains %q", unwanted))
+		}
+	}
+	for _, file := range expect.Files {
+		path := filepath.Join(workspace, filepath.FromSlash(file.Path))
+		data, err := os.ReadFile(path)
+		if file.Absent {
+			if err == nil {
+				failures = append(failures, fmt.Sprintf("%s exists but should not", file.Path))
+			}
+			continue
+		}
+		if err != nil {
+			failures = append(failures, fmt.Sprintf("%s unreadable: %v", file.Path, err))
+			continue
+		}
+		content := string(data)
+		if file.Contains != "" && !strings.Contains(content, file.Contains) {
+			failures = append(failures, fmt.Sprintf("%s missing %q", file.Path, file.Contains))
+		}
+		if file.NotContains != "" && strings.Contains(content, file.NotContains) {
+			failures = append(failures, fmt.Sprintf("%s contains %q", file.Path, file.NotContains))
+		}
+	}
+	return failures
+}
+
+// scenarioEnv builds the child environment: the developer's provider
+// credentials removed, the scripted provider substituted, and the per-user
+// config directory redirected into the workspace so a real ~/.config/zero
+// cannot change the outcome. XDG_CONFIG_HOME covers macOS and Linux (Zero
+// honors it on macOS too); APPDATA is what os.UserConfigDir reads on Windows.
+func scenarioEnv(port int, configHome string, extra map[string]string) []string {
+	drop := make(map[string]bool, len(providerCredentialEnv))
+	for _, name := range providerCredentialEnv {
+		drop[name] = true
+	}
+	env := make([]string, 0, len(os.Environ())+10)
+	for _, entry := range os.Environ() {
+		name, _, ok := strings.Cut(entry, "=")
+		if ok && drop[name] {
+			continue
+		}
+		env = append(env, entry)
+	}
+	base := "http://127.0.0.1:" + strconv.Itoa(port) + "/v1"
+	assign := map[string]string{
+		"ZERO_PROVIDER":         "openai",
+		"OPENAI_BASE_URL":       base,
+		"OPENAI_API_KEY":        "zero-xplat-scripted",
+		"OPENAI_MODEL":          "zero-xplat-70b",
+		"NO_COLOR":              "1",
+		"XDG_CONFIG_HOME":       configHome,
+		"APPDATA":               configHome,
+		"ZERO_DISABLE_MODELS_FETCH": "1",
+	}
+	for name, value := range extra {
+		assign[name] = value
+	}
+	names := make([]string, 0, len(assign))
+	for name := range assign {
+		names = append(names, name)
+	}
+	sort.Strings(names)
+	for _, name := range names {
+		env = append(env, name+"="+assign[name])
+	}
+	return env
+}
+
+// startProvider launches the scripted provider and waits for it to publish its
+// port. Binding to port 0 and reading the chosen port back avoids the fixed-port
+// races that would otherwise appear when scenarios run back to back.
+func startProvider(ctx context.Context, binary, scriptPath string) (*exec.Cmd, int, error) {
+	command := exec.CommandContext(ctx, binary, scriptPath)
+	stdout, err := command.StdoutPipe()
+	if err != nil {
+		return nil, 0, err
+	}
+	var stderr strings.Builder
+	command.Stderr = &stderr
+	if err := command.Start(); err != nil {
+		return nil, 0, err
+	}
+	type portRead struct {
+		port int
+		err  error
+	}
+	results := make(chan portRead, 1)
+	go func() {
+		reader := bufio.NewReader(stdout)
+		line, err := reader.ReadString('\n')
+		if err != nil {
+			results <- portRead{err: err}
+			return
+		}
+		port, err := strconv.Atoi(strings.TrimSpace(line))
+		results <- portRead{port: port, err: err}
+	}()
+
+	select {
+	case result := <-results:
+		if result.err != nil {
+			stopProvider(command)
+			detail := strings.TrimSpace(stderr.String())
+			if detail != "" {
+				return nil, 0, fmt.Errorf("%w: %s", result.err, detail)
+			}
+			return nil, 0, result.err
+		}
+		return command, result.port, nil
+	case <-time.After(20 * time.Second):
+		stopProvider(command)
+		return nil, 0, errors.New("scripted provider did not report a port within 20s")
+	}
+}
+
+func stopProvider(command *exec.Cmd) {
+	if command == nil || command.Process == nil {
+		return
+	}
+	_ = command.Process.Kill()
+	_ = command.Wait()
+}
+
+// LoadScenarios reads every *.json scenario in dir, optionally filtered by a
+// substring of the name, sorted so the execution order is identical on every
+// platform.
+func LoadScenarios(dir, filter string) ([]Scenario, error) {
+	entries, err := os.ReadDir(dir)
+	if err != nil {
+		return nil, err
+	}
+	var scenarios []Scenario
+	for _, entry := range entries {
+		if entry.IsDir() || !strings.HasSuffix(entry.Name(), ".json") {
+			continue
+		}
+		data, err := os.ReadFile(filepath.Join(dir, entry.Name()))
+		if err != nil {
+			return nil, err
+		}
+		var scenario Scenario
+		if err := json.Unmarshal(data, &scenario); err != nil {
+			return nil, fmt.Errorf("parse %s: %w", entry.Name(), err)
+		}
+		if strings.TrimSpace(scenario.Name) == "" {
+			return nil, fmt.Errorf("%s: scenario needs a name", entry.Name())
+		}
+		if filter != "" && !strings.Contains(scenario.Name, filter) {
+			continue
+		}
+		scenarios = append(scenarios, scenario)
+	}
+	sort.Slice(scenarios, func(i, j int) bool { return scenarios[i].Name < scenarios[j].Name })
+	return scenarios, nil
+}
+
+// DefaultZeroBinary is where `zero-release build` leaves the binary.
+func DefaultZeroBinary(rootDir string) string {
+	name := "zero"
+	if runtime.GOOS == "windows" {
+		name = "zero.exe"
+	}
+	return filepath.Join(rootDir, name)
+}
+
+// DefaultProviderBinary is where the Makefile builds the scripted provider.
+func DefaultProviderBinary(rootDir string) string {
+	name := "zero-xplat-provider"
+	if runtime.GOOS == "windows" {
+		name = "zero-xplat-provider.exe"
+	}
+	return filepath.Join(rootDir, ".xplat-run", name)
+}
+
+// DefaultWorkDir keeps scenario workspaces inside the repository rather than
+// under os.TempDir(). On macOS and Linux the temp directory is a default
+// sandbox write root, so a scenario asserting that writes outside the
+// workspace are refused would pass for the wrong reason there.
+func DefaultWorkDir(rootDir string) string {
+	return filepath.Join(rootDir, ".xplat-run", "workspaces")
+}
+
+// WriteJSON emits the normalized report.
+func WriteJSON(w io.Writer, report PlatformReport) error {
+	encoder := json.NewEncoder(w)
+	encoder.SetIndent("", "  ")
+	return encoder.Encode(report)
+}
+
+func resolveRootDir(rootDir string) (string, error) {
+	if strings.TrimSpace(rootDir) != "" {
+		return filepath.Abs(rootDir)
+	}
+	wd, err := os.Getwd()
+	if err != nil {
+		return "", err
+	}
+	return wd, nil
+}
+
+func resetDir(path string) error {
+	if err := os.RemoveAll(path); err != nil {
+		return err
+	}
+	return os.MkdirAll(path, 0o755)
+}
+
+func failScenario(result ScenarioResult, started time.Time, failure string) ScenarioResult {
+	result.RuntimeMS = time.Since(started).Milliseconds()
+	result.Status = StatusFailed
+	result.Failures = append(result.Failures, failure)
+	return result
+}
+
+func finishScenario(result ScenarioResult, failures []string) ScenarioResult {
+	result.Failures = failures
+	result.Status = StatusPassed
+	if len(failures) > 0 {
+		result.Status = StatusFailed
+	}
+	return result
+}
+
+func exitCodeOf(err error) int {
+	if err == nil {
+		return 0
+	}
+	exitErr := new(exec.ExitError)
+	if errors.As(err, &exitErr) {
+		return exitErr.ExitCode()
+	}
+	return -1
+}
+
+func binaryVersion(ctx context.Context, binary string) string {
+	command := exec.CommandContext(ctx, binary, "--version")
+	output, err := command.Output()
+	if err != nil {
+		return ""
+	}
+	return strings.TrimSpace(string(output))
+}
+
+func formatScenarioLine(result ScenarioResult) string {
+	switch result.Status {
+	case StatusPassed:
+		return fmt.Sprintf("  PASS  %-32s %dms", result.Name, result.RuntimeMS)
+	case StatusSkipped:
+		return fmt.Sprintf("  SKIP  %-32s %s", result.Name, result.SkipReason)
+	default:
+		return fmt.Sprintf("  FAIL  %-32s %dms\n        %s", result.Name, result.RuntimeMS,
+			strings.Join(result.Failures, "\n        "))
+	}
+}
