+// Command zero-xplat runs complete Zero features against the real binary on
+// the current operating system, and merges the per-platform reports into one
+// cross-platform comparison.
+//
+//	zero-xplat run                       # execute scenarios on this OS
+//	zero-xplat merge macos.json linux.json windows.json
+//
+// `run` is what each CI matrix leg executes; `merge` is what turns three
+// independent runs into the answer to "does this feature behave the same
+// everywhere".
+package main
+
+import (
+	"context"
+	"encoding/json"
+	"fmt"
+	"io"
+	"os"
+	"sort"
+	"strings"
+	"time"
+
+	"github.com/Gitlawb/zero/internal/xplat"
+)
+
+func main() {
+	os.Exit(run(os.Args[1:], os.Stdout, os.Stderr))
+}
+
+func run(args []string, stdout, stderr io.Writer) int {
+	if len(args) == 0 {
+		writeHelp(stdout)
+		return 2
+	}
+	switch args[0] {
+	case "run":
+		return runScenarios(args[1:], stdout, stderr)
+	case "merge":
+		return runMerge(args[1:], stdout, stderr)
+	case "-h", "--help", "help":
+		writeHelp(stdout)
+		return 0
+	default:
+		fmt.Fprintf(stderr, "[zero-xplat] unknown command %q\n", args[0])
+		return 2
+	}
+}
+
+func runScenarios(args []string, stdout, stderr io.Writer) int {
+	options := xplat.Options{Stdout: stdout}
+	outputPath := ""
+	for index := 0; index < len(args); index++ {
+		name, value, hasInline := strings.Cut(args[index], "=")
+		next := func() (string, bool) {
+			if hasInline {
+				return value, true
+			}
+			if index+1 >= len(args) {
+				fmt.Fprintf(stderr, "[zero-xplat] %s needs a value\n", name)
+				return "", false
+			}
+			index++
+			return args[index], true
+		}
+		switch name {
+		case "--root":
+			got, ok := next()
+			if !ok {
+				return 2
+			}
+			options.RootDir = got
+		case "--binary":
+			got, ok := next()
+			if !ok {
+				return 2
+			}
+			options.ZeroBinary = got
+		case "--scenarios":
+			got, ok := next()
+			if !ok {
+				return 2
+			}
+			options.ScenarioDir = got
+		case "--filter":
+			got, ok := next()
+			if !ok {
+				return 2
+			}
+			options.Filter = got
+		case "--json":
+			got, ok := next()
+			if !ok {
+				return 2
+			}
+			outputPath = got
+		case "--keep-workspaces":
+			options.KeepWorkspaces = true
+		default:
+			fmt.Fprintf(stderr, "[zero-xplat] unknown flag %q\n", name)
+			return 2
+		}
+	}
+
+	report, err := xplat.Run(context.Background(), options)
+	if err != nil {
+		fmt.Fprintf(stderr, "[zero-xplat] %v\n", err)
+		return 1
+	}
+	fmt.Fprintf(stdout, "\n%s: %d passed, %d failed, %d skipped (%dms)\n",
+		report.OS, report.Passed, report.Failed, report.Skipped, report.RuntimeMS)
+
+	if outputPath != "" {
+		file, err := os.Create(outputPath)
+		if err != nil {
+			fmt.Fprintf(stderr, "[zero-xplat] %v\n", err)
+			return 1
+		}
+		defer func() { _ = file.Close() }()
+		if err := xplat.WriteJSON(file, report); err != nil {
+			fmt.Fprintf(stderr, "[zero-xplat] %v\n", err)
+			return 1
+		}
+	}
+	if report.Failed > 0 {
+		return 1
+	}
+	return 0
+}
+
+// platformResult is one operating system's outcome for a single feature.
+type platformResult struct {
+	Status    string   `json:"status"`
+	RuntimeMS int64    `json:"runtime_ms"`
+	ExitCode  int      `json:"exit_code"`
+	Logs      string   `json:"logs,omitempty"`
+	Error     string   `json:"error,omitempty"`
+	Artifacts []string `json:"artifacts"`
+}
+
+// featureComparison is one feature across every platform that reported.
+type featureComparison struct {
+	Feature   string                    `json:"feature"`
+	Agreement string                    `json:"agreement"`
+	Platforms map[string]platformResult `json:"platforms"`
+}
+
+type mergedReport struct {
+	GeneratedAt string              `json:"generated_at"`
+	Status      string              `json:"status"`
+	Platforms   []string            `json:"platforms"`
+	Divergent   []string            `json:"divergent_features"`
+	Features    []featureComparison `json:"features"`
+}
+
+func runMerge(args []string, stdout, stderr io.Writer) int {
+	if len(args) == 0 {
+		fmt.Fprintln(stderr, "[zero-xplat] merge needs at least one report file")
+		return 2
+	}
+	merged := mergedReport{
+		GeneratedAt: time.Now().UTC().Format(time.RFC3339),
+		Status:      "passed",
+	}
+	byFeature := map[string]map[string]platformResult{}
+	for _, path := range args {
+		data, err := os.ReadFile(path)
+		if err != nil {
+			fmt.Fprintf(stderr, "[zero-xplat] %v\n", err)
+			return 1
+		}
+		var report xplat.PlatformReport
+		if err := json.Unmarshal(data, &report); err != nil {
+			fmt.Fprintf(stderr, "[zero-xplat] parse %s: %v\n", path, err)
+			return 1
+		}
+		merged.Platforms = append(merged.Platforms, report.OS)
+		for _, scenario := range report.Scenarios {
+			if byFeature[scenario.Name] == nil {
+				byFeature[scenario.Name] = map[string]platformResult{}
+			}
+			byFeature[scenario.Name][report.OS] = platformResult{
+				Status:    scenario.Status,
+				RuntimeMS: scenario.RuntimeMS,
+				ExitCode:  scenario.ExitCode,
+				Logs:      tail(scenario.Stdout+scenario.Stderr, 4000),
+				Error:     strings.Join(scenario.Failures, "; "),
+				Artifacts: emptyIfNil(scenario.Artifacts),
+			}
+		}
+	}
+	sort.Strings(merged.Platforms)
+
+	names := make([]string, 0, len(byFeature))
+	for name := range byFeature {
+		names = append(names, name)
+	}
+	sort.Strings(names)
+
+	for _, name := range names {
+		platforms := byFeature[name]
+		comparison := featureComparison{
+			Feature:   name,
+			Agreement: agreementOf(platforms),
+			Platforms: platforms,
+		}
+		if comparison.Agreement == "divergent" {
+			merged.Divergent = append(merged.Divergent, name)
+			merged.Status = "failed"
+		}
+		merged.Features = append(merged.Features, comparison)
+	}
+	if merged.Divergent == nil {
+		merged.Divergent = []string{}
+	}
+
+	encoder := json.NewEncoder(stdout)
+	encoder.SetIndent("", "  ")
+	if err := encoder.Encode(merged); err != nil {
+		fmt.Fprintf(stderr, "[zero-xplat] %v\n", err)
+		return 1
+	}
+	if merged.Status != "passed" {
+		return 1
+	}
+	return 0
+}
+
+// agreementOf reports whether every platform that actually ran the feature
+// reached the same status. Skips are excluded: a scenario a platform cannot
+// run is not evidence that the platforms disagree. If every platform skipped,
+// the feature is "unrun" rather than agreeing.
+func agreementOf(platforms map[string]platformResult) string {
+	statuses := map[string]bool{}
+	for _, result := range platforms {
+		if result.Status == xplat.StatusSkipped {
+			continue
+		}
+		statuses[result.Status] = true
+	}
+	switch len(statuses) {
+	case 0:
+		return "unrun"
+	case 1:
+		if statuses[xplat.StatusPassed] {
+			return "agreed"
+		}
+		// Failing identically everywhere is a bug, but not a platform
+		// difference; naming it separately keeps the divergence list honest.
+		return "agreed-failing"
+	default:
+		return "divergent"
+	}
+}
+
+func tail(text string, limit int) string {
+	if len(text) <= limit {
+		return text
+	}
+	return "...(truncated)...\n" + text[len(text)-limit:]
+}
+
+func emptyIfNil(values []string) []string {
+	if values == nil {
+		return []string{}
+	}
+	return values
+}
+
+func writeHelp(w io.Writer) {
+	fmt.Fprint(w, `Usage:
+  zero-xplat run [flags]
+  zero-xplat merge <report.json>...
+
+Runs complete Zero features against the real binary on this operating system,
+so the same scenario can be compared across macOS, Linux, and Windows.
+
+run flags:
+  --root <dir>          Repository root (default: working directory)
+  --binary <path>       zero binary to exercise (default: <root>/zero)
+  --scenarios <dir>     Scenario directory (default: <root>/testdata/xplat)
+  --filter <substring>  Only run scenarios whose name contains this
+  --json <path>         Write the normalized platform report here
+  --keep-workspaces     Leave scenario workspaces on disk for inspection
+
+merge combines per-platform reports and exits non-zero when any feature
+behaves differently on one platform than another.
+`)
+}
